// Generated by scripts/gen-l10n.mjs (gdetail n4, vi) — 不要手改;改翻譯請改 scripts/out/l10n/vi/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["vi"]=Object.assign(window.GRAMMAR_DETAIL_L10N["vi"]||{},{"n4-30":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Ba mẫu này đều mang nghĩa «<b>giúp</b>» trong tiếng Việt. Bạn giúp người khác thì dùng <b>てあげる</b>, người khác giúp bạn thì dùng <b>てくれる</b>, còn bạn nhận được sự giúp đỡ của ai đó thì dùng <b>てもらう</b>. Hướng đi giống hệt あげる・くれる・もらう khi cho nhận đồ, chỉ khác là thứ được trao đi không phải quà mà là «việc giúp làm một điều gì đó».</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chia động từ sang thể て trước, rồi nối với あげる／くれる／もらう.<br><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span> → <span class='gd-jp'>貸してあげる</span></span><br><span class='gd-pair'><span class='gd-jp'>作る</span> → <span class='gd-jp'>作って</span> → <span class='gd-jp'>作ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってもらう</span></span><br>Muốn nói lịch sự thì dùng あげます、くれます、もらいます.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Mình giúp người khác</span><b>てあげる</b>. Mẫu câu là 「Mình は người kia に ～てあげる」.</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげました。</span>（Mình đọc sách cho em gái nghe）</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに傘を貸してあげた。</span>（Mình cho bạn mượn ô）</div><div class='gd-sec'><span class='gd-tag'>Người khác giúp mình</span><b>てくれる</b>. Mẫu câu là 「Người kia が ～てくれる」. Thường không cần nói «cho tôi», vì bản thân くれる đã mang nghĩa «hướng về phía tôi» rồi. Người nhà cũng được tính là «phía của tôi».</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>（Mẹ làm cơm hộp cho mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちが駅まで送ってくれました。</span>（Bạn tiễn mình ra tận ga）</div><div class='gd-sec'><span class='gd-tag'>Mình nhận được sự giúp đỡ</span><b>てもらう</b>. Mẫu câu là 「Mình は người kia に ～てもらう」, ở đây 「に」 có nghĩa là «<b>từ ai</b>» mà mình nhận được sự giúp đỡ.</div><div class='gd-ex-line'>・<span class='gd-jp'>友だちに写真を撮ってもらいました。</span>（Mình nhờ bạn chụp ảnh giúp）</div><div class='gd-ex-line'>・<span class='gd-jp'>美容院で髪を切ってもらいました。</span>（Mình đi tiệm làm tóc cắt tóc）</div><div class='gd-sec'>Tóc là do nhà tạo mẫu cắt chứ không phải tự mình cắt, nên tiếng Nhật rất tự nhiên dùng てもらう.</div><div class='gd-h'>Cách nói nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Nhờ người khác</span>Muốn nhờ giúp, bạn có thể hỏi thẳng «Bạn giúp mình ～ được không?»</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれない？</span>（Giúp mình một chút được không?: nói với bạn bè）</div><div class='gd-ex-line'>・<span class='gd-jp'>このペンを貸してもらえませんか。</span>（Cho tôi mượn cây bút này được không ạ?: lịch sự）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・くれる chỉ dùng khi hướng về «tôi (phía tôi)». Mình giúp người khác thì nhất định là あげる, không thể nói 「私が友だちに貸してくれた」.<br>・「に」 của もらう không phải nghĩa «cho»: <span class='gd-jp'>友だちに手伝ってもらった</span> là «bạn giúp mình», không phải «mình giúp bạn». Nếu theo trực giác tiếng Việt thì rất dễ hiểu ngược.<br>・Trợ từ đi với đối tượng phụ thuộc vào động từ gốc, không phải lúc nào cũng là に. «Xách hành lý giúp mẹ» là <span class='gd-jp'>母の荷物を持ってあげた</span>, nói 「母に持ってあげた」 nghe không tự nhiên.<br>・Tiếng Việt nói «bạn dạy tôi tiếng Nhật», nhưng tiếng Nhật nếu chỉ nói <span class='gd-jp'>友だちが日本語を教えた</span> thì nghe như đang kể chuyện của người khác, và cũng thiếu cảm giác biết ơn. Việc người khác làm cho mình thì người Nhật hầu như luôn thêm てくれる: <span class='gd-jp'>友だちが日本語を教えてくれた</span>.<br>・てあげる mang sắc thái «tôi đặc biệt giúp bạn». Nói với thầy cô, cấp trên 「持ってあげましょうか」 là rất bất lịch sự, phải nói <span class='gd-jp'>お持ちしましょうか</span>. Khi nói với người khác rằng «mình đã giúp họ» cũng cần cẩn thận, vì nghe có thể giống như đang kể công.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'>てくれる và てもらう thường nói về cùng một việc, chỉ khác nhân vật chính:<br><span class='gd-jp'>友だちが手伝ってくれた。</span>（Bạn đã giúp mình）Nhân vật chính là bạn, trọng tâm là «bạn tốt thật».<br><span class='gd-jp'>友だちに手伝ってもらった。</span>（Mình nhờ bạn giúp）Nhân vật chính là mình, trọng tâm là «mình nhận được sự giúp đỡ».<br>Phần lớn trường hợp dùng cái nào cũng được. Nhưng nếu là <b>thiện ý chủ động</b> của đối phương thì dùng くれる là tự nhiên nhất: <span class='gd-jp'>頼んでいないのに、友だちが手伝ってくれた。</span>（Mình đâu có nhờ, vậy mà bạn chủ động đến giúp）<br>Còn nếu là <b>tự mình đi nhờ, hoặc trả tiền nhờ người ta làm</b> thì hay dùng もらう hơn: <span class='gd-jp'>店の人に包んでもらいました。</span>（Mình nhờ nhân viên cửa hàng gói giúp）</div><div class='gd-warn'>Mẹo phân biệt nhanh: mình giúp người khác dùng あげる; chủ ngữ là đối phương và theo sau là が thì dùng くれる; chủ ngữ là mình và đối phương theo sau là に thì dùng もらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Với thầy cô, người lớn tuổi, bạn cần đổi sang dạng kính ngữ:<br><span class='gd-jp'>先生が教えてくださいました。</span>（Thầy/cô đã dạy mình）<br><span class='gd-jp'>先生に教えていただきました。</span>（Mình được thầy/cô chỉ dạy）<br>Khi nhờ vả, 「〜てもらえませんか」 lịch sự hơn nữa sẽ là 「〜ていただけませんか」. Bạn có thể học cùng với 尊敬語 và 謙譲語.</div>","n4-17":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ために」 chính là <b>«để ～ / vì ～»</b> trong tiếng Việt. Phía trước đặt mục tiêu bạn muốn đạt được, phía sau đặt <b>việc bạn cố ý làm</b> vì mục tiêu đó. Ví dụ «để mua xe, mình đang tiết kiệm tiền», tiếng Nhật là: <span class='gd-jp'>車を買うために、お金をためています。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>: dùng thẳng thể từ điển (dạng gốc tra trong từ điển) ＋ ために.<br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うために</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するために</span></span><br><b>Danh từ</b>: ở giữa phải thêm 「の」.<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族のために</span></span><span class='gd-pair'><span class='gd-jp'>健康</span> → <span class='gd-jp'>健康のために</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Để làm được một việc nào đó</span>Phía trước là động từ, nói về mục tiêu bạn muốn hoàn thành.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を勉強するために、日本へ来ました。</span>（Mình đến Nhật để học tiếng Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>資格試験に合格するために、毎日図書館へ通っています。</span>（Để đỗ kỳ thi chứng chỉ, ngày nào mình cũng đến thư viện）</div><div class='gd-sec'><span class='gd-tag'>Vì ai đó, vì điều gì đó tốt hơn</span>Phía trước là danh từ, nghĩa là «nghĩ cho nó, vì nó».</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、頑張って働いています。</span>（Mình cố gắng làm việc vì gia đình）</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>（Vì sức khỏe, sáng nào mình cũng chạy bộ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải có の: <span class='gd-jp'>家族ために</span> là sai, phải nói <span class='gd-jp'>家族のために</span>.<br>・Phía trước ために <b>luôn là thể từ điển</b>, kể cả khi cả câu nói về chuyện quá khứ: <span class='gd-jp'>切符を買うために、早く家を出ました。</span>（Để mua vé, mình đã ra khỏi nhà sớm）Không nói thành 買ったために.<br>・Hai vế thường có <b>cùng một chủ thể</b>: mình tự làm một việc vì mục tiêu của mình. Nếu là «để con có thể vào đại học», tức là việc người khác phải làm được, thì đổi sang ように: <span class='gd-jp'>子どもが大学に行けるように、働いています。</span>（Mình đi làm để con có thể học đại học）<br>・Phía trước không đặt cách nói «có thể ～» (thể khả năng): <span class='gd-jp'>日本語が話せるために</span> nghe không tự nhiên, phải nói <span class='gd-jp'>日本語が話せるように</span>.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'><b>ために vs ように (mục đích)</b><br>Cả hai đều có thể dịch là «để», khác nhau ở hình dạng của vế phía trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞を読むために、漢字を勉強しています。</span>（Để đọc báo tiếng Nhật, mình đang học chữ Hán）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めるように、漢字を勉強しています。</span>（Để có thể đọc hiểu báo tiếng Nhật, mình đang học chữ Hán）</div><div class='gd-sec'>Phía trước ために là «<b>làm</b> một việc gì đó» (<span class='gd-jp'>読む</span>); phía trước ように là «<b>có thể ～</b>» hoặc «trở thành một trạng thái nào đó» (<span class='gd-jp'>読める</span>).</div><div class='gd-sec'><b>ために (mục đích) vs ために (nguyên nhân)</b><br>Cách viết hoàn toàn giống nhau, nhưng cũng có thể diễn tả nghĩa «vì, do».</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、野菜を食べています。</span>（Mình ăn rau vì sức khỏe）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のために、試合が中止になりました。</span>（Do trời mưa nên trận đấu bị hủy）</div><div class='gd-sec'>Nếu vế sau là việc bạn <b>chủ động làm</b> thì là «để, vì mục đích»; nếu vế sau là kết quả <b>đã xảy ra, không có lựa chọn khác</b> thì là «do, bởi vì». Cách dùng chỉ nguyên nhân khá trang trọng, bình thường nói «vì» thường dùng <span class='gd-jp'>から</span>、<span class='gd-jp'>ので</span>.</div><div class='gd-warn'>Mẹo phân biệt nhanh: phía trước là «làm ～» thì dùng ために, phía trước là «có thể ～» thì dùng ように; vế sau là việc mình cố ý làm thì ために nghĩa là «để», vế sau là kết quả đã xảy ra thì ために nghĩa là «do, bởi vì».</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi ために thành 「ための＋danh từ」, nghĩa là «… dành cho việc ～»: <span class='gd-jp'>留学のためのお金をためています。</span>（Mình đang tiết kiệm tiền để dùng cho việc du học）</div>","n4-20":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Hai mẫu này trông rất giống nhau, khác ở chỗ cuối câu là <b>なる</b> hay <b>する</b>.<br><b>ようになる</b> = 「<b>đã trở nên</b>～」, nói về <b>kết quả</b>: trước đây chưa làm được, bây giờ làm được rồi.<br><b>ようにする</b> = 「tôi <b>cố gắng</b>～」, nói về việc bạn <b>đang nỗ lực</b>, vẫn đang làm và không đảm bảo lần nào cũng thành công.<br>Trong tiếng Việt, 「trở nên / đã biết」 ứng với なる, còn 「cố gắng」 ứng với する.</div><div class='gd-h'>ようになる：trước chưa làm được, giờ làm được rồi</div><div class='gd-sec'><span class='gd-tag'>Thay đổi về khả năng</span>Hay gặp nhất. Phía trước dùng <b>thể khả năng</b> (thể diễn tả「biết ～, có thể ～」, như <span class='gd-jp'>話せる</span>, <span class='gd-jp'>食べられる</span>), hoặc dùng <span class='gd-jp'>できる</span>, <span class='gd-jp'>わかる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、日本語が少し話せるようになりました。</span>（Sau khi luyện tập, tôi đã nói được một chút tiếng Nhật rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>辛い物が食べられるようになった。</span>（Tôi đã ăn được đồ cay rồi）</div><div class='gd-sec'><span class='gd-tag'>Thay đổi về thói quen</span>Đi với thể từ điển, nghĩa là 「bắt đầu có thói quen làm như vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来てから、毎朝コーヒーを飲むようになった。</span>（Từ khi đến Nhật, tôi có thói quen uống cà phê mỗi sáng）</div><div class='gd-sec'>Sự thay đổi có thể do bạn tự luyện mà có, hoặc cũng có thể đến lúc nào không hay. Dù vậy, trọng tâm vẫn là <b>kết quả ở hiện tại</b>.</div><div class='gd-h'>ようにする：tôi cố gắng làm như vậy</div><div class='gd-sec'>Việc cần làm: thể từ điển＋ようにする　<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるようにする</span></span><br>Việc không làm: thể ない＋ようにする　<span class='gd-pair'><span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まないようにする</span></span></div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>Thói quen bạn vẫn đang duy trì dạo gần đây, dùng nhiều nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日野菜を食べるようにしています。</span>（Tôi cố gắng ăn rau mỗi ngày）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜はコーヒーを飲まないようにしている。</span>（Buổi tối tôi cố gắng không uống cà phê）</div><div class='gd-sec'><span class='gd-tag'>ようにします</span>Từ bây giờ sẽ chú ý, hay dùng khi xin lỗi hoặc hứa hẹn.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅れないようにします。</span>（Từ giờ tôi sẽ cố gắng không đến muộn）</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>Nhờ đối phương cố gắng làm, bác sĩ và thầy cô rất hay nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は毎日飲むようにしてください。</span>（Hãy nhớ uống thuốc mỗi ngày nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Muốn nói「đã <b>biết/có thể</b> ～」thì phía trước phải dùng thể khả năng: <span class='gd-jp'>日本語が話せるようになった</span> mới là 「đã nói được tiếng Nhật」. Nếu viết <span class='gd-jp'>日本語を話すようになった</span>, nghĩa sẽ thành 「bắt đầu nói tiếng Nhật thường xuyên」, tức là nói về thói quen chứ không phải khả năng.<br>・Khi dùng thể khả năng, 「を」 phía trước thường đổi thành 「が」: <span class='gd-jp'>日本語が話せる</span>.<br>・Muốn nói 「trở nên <b>không</b> ～ nữa」, người Nhật thường nói thẳng <b>〜なくなる</b>: <span class='gd-jp'>最近、テレビを見なくなった。</span>（Dạo này tôi không xem TV nữa）. Họ ít nói「見ないようになった」 hơn.<br>・Tính từ và danh từ không đi với ようになる. 「Trở nên to」 là <span class='gd-jp'>大きくなる</span>, 「trở nên yên tĩnh」 là <span class='gd-jp'>静かになる</span>, 「trở thành giáo viên」 là <span class='gd-jp'>先生になる</span>. ようになる chỉ đi với động từ.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về chuyện dậy sớm, hãy xem ba cách nói:<br><b>ようになった</b> = kết quả: <span class='gd-jp'>早く起きられるようになった。</span>（Tôi đã dậy sớm được rồi）<br><b>ようにしている</b> = đang nỗ lực: <span class='gd-jp'>早く起きるようにしている。</span>（Tôi đang cố gắng dậy sớm）<br><b>ことにした</b> = tự quyết định: <span class='gd-jp'>明日から早く起きることにした。</span>（Tôi quyết định từ ngày mai sẽ dậy sớm）</div><div class='gd-sec'>Ngoài ra, <b>ことになった</b> nghĩa là 「được quyết định, được sắp xếp như vậy」, không phải bạn tự thay đổi cũng không phải bạn tự nỗ lực: <span class='gd-jp'>来月から大阪で働くことになった。</span>（Từ tháng sau tôi sẽ đi làm ở Osaka）</div><div class='gd-warn'>Mẹo nhỏ để chọn: 「đã biết làm ～」 dùng ようになる, 「cố gắng ～」 dùng ようにする, 「quyết định ～」 dùng ことにする, 「được sắp xếp ～」 dùng ことになる.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bỏ なる và する đi, 「ように」 đứng riêng có thể diễn tả 「để ～」: <span class='gd-jp'>忘れないように、メモします。</span>（Để không quên, tôi ghi lại）</div>","n4-8":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「のに」 nghĩa là <b>「rõ ràng ～ vậy mà…」</b>. Vế trước là một việc chắc chắn, còn kết quả ở vế sau lại khác với điều bạn nghĩ, khiến bạn có cảm giác 「sao lại thế được」. Đó có thể là bất mãn, bất ngờ, hoặc tiếc nuối.</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（Rõ ràng đã uống thuốc rồi mà sốt vẫn không giảm）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Vế trước là <b>một sự thật đã chắc chắn</b>. Đó có thể là việc đã xảy ra, trạng thái hiện tại, hoặc việc chắc chắn sẽ xảy ra. Vế sau là kết quả 「lẽ ra không nên như vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したのに、彼は来なかった。</span>（Rõ ràng đã hẹn rồi mà anh ấy vẫn không đến）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いのに、おいしい。</span>（Quán này rẻ vậy mà lại ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日テストなのに、全然勉強していない。</span>（Ngày mai có bài kiểm tra mà chẳng học gì cả）</div><div class='gd-sec'>Như câu thứ hai, kết quả có thể là một bất ngờ thú vị, nên のに không nhất thiết là phàn nàn. Trọng tâm là <b>「trái với dự đoán」</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước dùng thể thường (cách nói không có ます).<br><b>Động từ</b>：<span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったのに</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないのに</span></span><br><b>Tính từ い</b>：<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いのに</span></span><br><b>Tính từ な, danh từ</b>：phải thêm 「な」 trước.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日なのに</span></span><br>Nói về quá khứ thì dùng だった：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったのに</span></span></div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Nói lửng câu</span>Không nói ra kết quả ở vế sau, để lại cảm giác 「haizz」. Rất hay dùng khi phàn nàn hoặc tiếc nuối.</div><div class='gd-ex-line'>・<span class='gd-jp'>せっかく作ったのに…。</span>（Mình đã mất công làm vậy mà…）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ nhất định phải có な: nói <span class='gd-jp'>静かなのに</span>, không được nói 「静かのに」 hay 「静かだのに」.<br>・Sau のに <b>không được đặt ý chí của bản thân, lời mời, mệnh lệnh hay lời nhờ</b>, như 「hãy ～ nhé」「tôi sẽ ～」「xin hãy ～」 đều không được.<br>　× 高いのに、買おう。<br>　○ <span class='gd-jp'>高いけど、買おう。</span>（Tuy đắt nhưng vẫn mua thôi）<br>・のに mang cảm xúc. Nếu nói thẳng 「～のに」 với người lớn tuổi hoặc khách, nghe có thể giống như đang phàn nàn hoặc trách họ, nên cần chú ý hoàn cảnh.<br>・Có một 「のに」 khác trông giống hệt, nghĩa là 「để làm ～ (dùng, tốn)」: <span class='gd-jp'>駅へ行くのに30分かかる。</span>（Đi đến ga mất 30 phút）. Ở đây không có nghĩa 「rõ ràng… vậy mà」. Bạn chỉ cần xem phía sau có phải 「mất thời gian, cần, dùng」 hay không là phân biệt được.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'><b>のに</b> = rõ ràng ～ vậy mà… (có cảm xúc): <span class='gd-jp'>薬を飲んだのに、熱が下がらない。</span>（Rõ ràng đã uống thuốc mà sốt vẫn không giảm, sao lại thế được）<br><b>けど</b> = tuy ～ nhưng… (chỉ đơn thuần đối lập, bình tĩnh hơn): <span class='gd-jp'>薬を飲んだけど、熱が下がらない。</span>（Uống thuốc rồi nhưng vẫn chưa hết sốt）<br><b>ても</b> = dù ～ cũng…, có thể nói về giả định chưa xảy ra: <span class='gd-jp'>明日雨が降っても、行きます。</span>（Dù mai trời mưa tôi cũng sẽ đi）<br>Câu này không thể đổi sang のに, vì 「mai có mưa hay không」 còn chưa chắc, và vế sau là việc bạn sẽ tự làm.</div><div class='gd-sec'><b>ので</b> có nghĩa ngược lại, là 「vì ～ nên…」, đi thuận theo kết quả:<br><span class='gd-jp'>雨なので、出かけなかった。</span>（Vì trời mưa nên tôi đã không ra ngoài）<br><span class='gd-jp'>雨なのに、彼は出かけた。</span>（Trời mưa mà anh ấy vẫn ra ngoài）</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu vế trước là sự thật chắc chắn (không phải giả định) và trong lòng bạn nghĩ 「sao lại thế được」 thì dùng のに. Chỉ đối lập một cách bình thường thì dùng けど. 「Dù ～ cũng」 thì dùng ても. Kết quả thuận lý thì dùng ので.</div>","n4-18":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ために」đặt sau nguyên nhân, nghĩa là <b>「do ～」「vì ～」</b>. Mẫu này khá trang trọng và khách quan, giống giọng thông báo trên tàu điện: \"Do sự cố tín hiệu, tàu sẽ bị chậm\". Bạn sẽ gặp nó nhiều trong tin tức, thông báo, hoặc khi giải thích tình hình với khách hàng, cấp trên.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tin tức・Thông báo</span>Nói rõ đã xảy ra chuyện gì và dẫn đến kết quả gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、新幹線が止まりました。</span>（Do tuyết lớn, tàu Shinkansen đã ngừng chạy）</div><div class='gd-sec'><span class='gd-tag'>Giải thích trang trọng</span>Khi giải thích với thầy cô, cấp trên, khách hàng vì sao có sự cố, nghe sẽ khách quan, không giống đang viện cớ.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が遅れたために、授業に間に合いませんでした。</span>（Vì tàu bị trễ nên tôi không kịp giờ học）</div><div class='gd-sec'>Kết quả ở vế sau thường là chuyện <b>đã xảy ra và bản thân không kiểm soát được</b>, và hay là chuyện không tốt như ngừng chạy, bị trễ, bị hủy.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Trước ために là \"nguyên nhân\", loại từ nào cũng ghép được. Bạn chỉ cần nhớ: danh từ phải thêm「の」, tính từ な phải thêm「な」.<br>Động từ thể た：<span class='gd-pair'><span class='gd-jp'>起きた</span> → <span class='gd-jp'>起きたために</span></span><br>Động từ thể ない：<span class='gd-pair'><span class='gd-jp'>足りない</span> → <span class='gd-jp'>足りないために</span></span><br>Đang diễn ra（ている）：<span class='gd-pair'><span class='gd-jp'>工事をしている</span> → <span class='gd-jp'>工事をしているために</span></span><br>Động từ chỉ trạng thái（ある、いる、できる）：<span class='gd-pair'><span class='gd-jp'>用事がある</span> → <span class='gd-jp'>用事があるために</span></span><br>Tính từ い ghép trực tiếp：<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いために</span></span><br>Tính từ な thêm な：<span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便なために</span></span><br>Danh từ thêm の：<span class='gd-pair'><span class='gd-jp'>大雪</span> → <span class='gd-jp'>大雪のために</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>道が狭いために、大きい車は通れません。</span>（Vì đường hẹp nên xe lớn không đi qua được）</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるために、会議に出られません。</span>（Vì có việc nên tôi không thể dự họp được）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>のため</span>Trong thông báo, phát thanh, người ta hay lược「に」, thành「〜のため」「〜ため」. Nghĩa vẫn vậy, nhưng nghe trang trọng hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>工事中のため、この道は通れません。</span>（Đang thi công nên đường này không đi qua được）</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、明日の授業は休みです。</span>（Vì bão nên ngày mai nghỉ học）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ nhất định phải thêm「の」: phải nói <span class='gd-jp'>大雪のために</span>, không được nói 大雪ために. Tính từ な phải thêm「な」：<span class='gd-jp'>不便なために</span>.<br>・Vế sau không được dùng câu nhờ vả hay rủ rê như「～てください」「～ましょう」.<br>×<span class='gd-jp'>雨のために、傘を持っていってください。</span><br>○<span class='gd-jp'>雨なので、傘を持っていってください。</span>（Vì trời mưa, bạn hãy mang ô theo nhé）<br>・Giọng văn khá cứng. Nếu nói chuyện với bạn bè mà bạn nói <span class='gd-jp'>雨のために行かない</span> thì nghe như đang đọc bản tin. Giữa bạn bè cứ dùng「から」là được.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>ために (mục đích) vs ために (nguyên nhân)</b>: đây là cùng một từ, bạn phải nhìn phần đứng trước để phân biệt.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くために、お金をためています。</span>（Để đi Nhật, tôi đang tiết kiệm tiền: mục đích）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降ったために、電車が遅れました。</span>（Vì tuyết rơi nên tàu bị trễ: nguyên nhân）</div><div class='gd-sec'>「Danh từ＋のために」có thể mang cả hai nghĩa, tùy danh từ đó là mục tiêu bạn muốn đạt tới, hay là một sự việc đã xảy ra:</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝走っています。</span>（Vì sức khỏe, mỗi sáng tôi đều chạy bộ）</div><div class='gd-ex-line'>・<span class='gd-jp'>病気のために、学校を休みました。</span>（Vì bị bệnh nên tôi đã nghỉ học）</div><div class='gd-warn'>Mẹo nhỏ: hãy nhìn phần trước ために. Nếu là hành động bạn tự kiểm soát được và muốn đạt tới (ví dụ thể từ điển của <span class='gd-jp'>合格する</span>, <span class='gd-jp'>買う</span>) thì nghĩa là \"để\". Nếu là thể た, なかった, ている, hoặc động từ trạng thái như <span class='gd-jp'>ある</span>, <span class='gd-jp'>いる</span>, <span class='gd-jp'>できる</span>, tính từ, hoặc danh từ chỉ sự việc hay trạng thái như <span class='gd-jp'>台風</span>, <span class='gd-jp'>病気</span>, <span class='gd-jp'>事故</span> thì nghĩa là \"vì, do\".<br>Thể ない cần đặc biệt lưu ý: khi đi với hành động tự kiểm soát được, thường có nghĩa \"để không ～\", như <span class='gd-jp'>遅れないために、早く家を出ます</span> (để không bị trễ, tôi ra khỏi nhà sớm). Chỉ khi đi với trạng thái ngoài tầm kiểm soát như <span class='gd-jp'>足りない</span>, <span class='gd-jp'>わからない</span> thì mới là \"vì, do\".</div><div class='gd-sec'><b>ために vs から／ので</b>: cùng là \"trời mưa nên trận đấu bị hủy\", nhưng cách nói sẽ chọn theo hoàn cảnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨だから、試合は中止だって。</span>（Vì trời mưa nên nghe nói trận đấu bị hủy: nói chuyện với bạn bè）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨なので、試合は中止です。</span>（Vì trời mưa nên trận đấu bị hủy: giải thích lịch sự）</div><div class='gd-ex-line'>・<span class='gd-jp'>大雨のため、試合は中止になりました。</span>（Do mưa lớn, trận đấu đã bị hủy: thông báo, tin tức）</div><div class='gd-warn'>Mẹo nhỏ: nói với bạn bè thì dùng「から」, giải thích lịch sự thì dùng「ので」, còn tin tức, thông báo, văn bản trang trọng mới dùng「ため（に）」. Khi vế sau là nhờ người khác làm gì, hãy dùng ので hoặc から, đừng dùng ために.</div>","n4-19":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「<span class='gd-jp'>〜ように</span>」tương đương với <b>\"để có thể ～\", \"để không ～\"</b> trong tiếng Việt. Điểm mấu chốt là kết quả bạn mong muốn <b>không do bạn quyết định được</b>, bạn chỉ có thể chuẩn bị trước. Ví dụ \"để không ngủ quên, tôi đặt hai cái báo thức\": có ngủ quên hay không thì bạn không kiểm soát được, nhưng báo thức thì bạn đặt được.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Vế trước đặt \"trạng thái bạn mong muốn\", vế sau đặt \"việc bạn làm vì điều đó\".<br><b>Mong muốn \"có thể ～\"</b>: thể khả năng＋ように. Thể khả năng là dạng \"có thể ～, biết ～\", ví dụ <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span> (nói được).<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span> (để có thể nói)<br><b>Mong muốn \"không ～\"</b>: thể ない＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span> (để không quên)<br><b>Động từ vốn dĩ không do mình quyết định</b> (<span class='gd-jp'>わかる</span>、<span class='gd-jp'>治る</span>、<span class='gd-jp'>聞こえる</span>、<span class='gd-jp'>〜になる</span>): dùng thẳng thể từ điển＋ように<br><span class='gd-pair'><span class='gd-jp'>治る</span> → <span class='gd-jp'>治るように</span></span> (để khỏi bệnh)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Để làm được</span>Muốn rèn luyện một năng lực nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が話せるように、毎日練習しています。</span>（Để có thể nói tiếng Nhật, tôi luyện tập mỗi ngày）</div><div class='gd-sec'><span class='gd-tag'>Để không xảy ra</span>Chuẩn bị trước để tránh chuyện không mong muốn.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておきます。</span>（Để không quên, tôi ghi chú lại trước）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひかないように、暖かくして寝てください。</span>（Để không bị cảm, bạn hãy mặc ấm khi ngủ nhé）</div><div class='gd-sec'><span class='gd-tag'>Để người khác có thể ～</span>Hai vế có thể là hai người khác nhau: vế trước nói về người khác, vế sau là việc bạn làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が食べられるように、小さく切ります。</span>（Để trẻ con ăn được, tôi cắt nhỏ ra）</div><div class='gd-ex-line'>・<span class='gd-jp'>後ろの人にも聞こえるように、大きい声で話します。</span>（Để người ở phía sau cũng nghe được, tôi nói giọng lớn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Muốn nói \"để <b>có thể</b> nói\", phải dùng thể khả năng <span class='gd-jp'>話せる</span>. Nếu dùng nguyên dạng <span class='gd-jp'>話す</span> thì không còn nghĩa \"có thể\" nữa.<br>・Trước ように luôn là thể từ điển hoặc thể ない, dù cả câu nói về quá khứ cũng không đổi: <span class='gd-jp'>忘れないように、メモしました。</span> (Để không quên, tôi đã ghi lại.) Không nói thành「忘れなかったように」.<br>・Tiếng Việt đều dùng \"để\", nhưng không phải chữ \"để\" nào cũng dùng ように. Những hành động bạn muốn làm là làm được ngay như mua, đi, học bài thì phải dùng <span class='gd-jp'>ために</span> (xem phần dưới).<br>・Bản thân ように không có vấn đề lịch sự hay không, mức độ lịch sự nằm ở cuối câu: <span class='gd-jp'>メモします</span> là lịch sự, <span class='gd-jp'>メモする</span> là kiểu nói với bạn bè.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng nói về \"mục đích học tiếng Nhật\":<br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（Tôi học tiếng Nhật để làm việc ở Nhật）<br><span class='gd-jp'>日本人と話せるように、日本語を勉強しています。</span>（Tôi học tiếng Nhật để có thể trò chuyện với người Nhật）<br>\"Đi Nhật làm việc\" là hành động bạn quyết định là làm được, nên dùng <b>ために</b>. \"Có thể trò chuyện với người Nhật\" là năng lực xuất hiện dần sau khi học, bạn không thể nói làm là làm ngay, nên dùng <b>ように</b>. Ngược lại, nói「話せるために」sẽ rất không tự nhiên.<br>Còn một điểm nữa: khi hai vế là hai người khác nhau, như <span class='gd-jp'>子供が食べられるように、小さく切ります</span> (người ăn là trẻ con, người cắt là tôi), thì dùng ように là đúng. ために thường có hai vế cùng một chủ thể.</div><div class='gd-warn'>Mẹo nhỏ: nếu phía trước là \"có thể ～\", \"không ～\", hoặc chuyện bản thân không kiểm soát được thì dùng ように; nếu phía trước là hành động bạn muốn làm là làm được ngay thì dùng ために.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nếu sau ように có <span class='gd-jp'>する</span> đi liền, nghĩa sẽ thành \"cố gắng ～\": <span class='gd-jp'>毎日野菜を食べるようにしています。</span> (Mỗi ngày tôi đều cố gắng ăn rau.)<br>ように đứng riêng, theo sau là một hành động khác, có nghĩa \"để ～\"; còn <span class='gd-jp'>ようにする</span> là \"cố gắng ～\", đừng nhầm lẫn hai cái này.</div>","n4-22":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ても」tương đương với <b>「dù ～ cũng …」「cho dù ～ vẫn …」</b> trong tiếng Việt. Vế trước lùi một bước, thừa nhận có một tình huống nào đó; vế sau nói kết quả vẫn không đổi, không bị ảnh hưởng. Ví dụ “Dù trời mưa, mình cũng sẽ đi” thì tiếng Nhật là <span class='gd-jp'>雨が降っても、行きます。</span></div><div class='gd-h'>Cách chia</div><div class='gd-sec'><b>Động từ</b>: chuyển sang thể て trước, rồi thêm「も」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span>（thể て kết thúc bằng「で」thì thành「でも」）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span></div><div class='gd-sec'><b>Tính từ い</b>: đổi「い」ở cuối thành「く」, rồi thêm「ても」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くても</span></span></div><div class='gd-sec'><b>Tính từ な・danh từ</b>: thêm trực tiếp「でも」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでも</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨でも</span></span></div><div class='gd-sec'><b>Dù không ～</b>: đổi「ない」của thể ない thành「なくても」.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Dù có xảy ra</span>Giả định một tình huống trước, rồi nói rằng quyết định của mình sẽ không thay đổi.</div><div class='gd-ex-line'>・<span class='gd-jp'>体調が悪くても、試合に出ます。</span>（Dù trong người không khỏe, mình vẫn sẽ thi đấu）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買います。</span>（Dù đắt mình cũng mua）</div><div class='gd-sec'><span class='gd-tag'>Thử rồi mà vẫn vô ích</span>Đã thật sự làm rồi, nhưng kết quả vẫn không như mong đợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度読んでも、意味がわかりません。</span>（Đọc mấy lần rồi mà vẫn không hiểu）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話しても、出ません。</span>（Gọi điện cho anh ấy mà anh ấy cũng không nghe máy）</div><div class='gd-sec'><span class='gd-tag'>Bất kể thế nào cũng</span>Đặt các từ như <span class='gd-jp'>いくら</span>、<span class='gd-jp'>どんなに</span>、<span class='gd-jp'>何を</span>、<span class='gd-jp'>誰が</span> ở phía trước thì nghĩa trở thành “dù ～ đến mấy cũng …”.</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら食べても、太りません。</span>（Dù ăn bao nhiêu cũng không béo）</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ごはんは食べます。</span>（Dù bận đến mấy, mình vẫn ăn sáng）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ても、ドアを開けないでください。</span>（Dù ai đến cũng đừng mở cửa）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Những động từ như <span class='gd-jp'>読む</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>遊ぶ</span> có thể て kết thúc bằng「で」, nên phải nói <span class='gd-jp'>読んでも</span>, không phải 読んても.<br>・Danh từ và tính từ な đi với「でも」: <span class='gd-jp'>雨でも</span>、<span class='gd-jp'>元気でも</span>. <span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よくても</span>, không phải いくても.<br>・Vế sau phải nói về kết quả “không đổi” hoặc “trái với dự đoán”. Nếu là kết quả hiển nhiên, thuận theo lẽ thường thì tình huống giả định dùng たら (hoặc ば); còn khi đã là sự thật và bạn muốn nói lý do thì mới dùng から、ので.<br>　<span class='gd-jp'>雨が降ったら、行きません。</span>（Nếu trời mưa thì mình không đi）<br>　<span class='gd-jp'>雨が降っても、行きます。</span>（Dù trời mưa mình cũng đi）<br>・Chữ “cũng” trong tiếng Việt đã nằm sẵn trong ても rồi, nên vế sau không cần thêm「も」nữa. Nếu nói <span class='gd-jp'>雨が降っても、私も行きます</span> thì nghĩa sẽ thành “tôi cũng đi (giống những người khác)”.<br>・Đừng nhầm với「〜てもいいです」: phía sau có thêm いいです thì nghĩa thành “được phép ～”. <span class='gd-jp'>食べてもいいです。</span>（Được ăn）／<span class='gd-jp'>食べても、太りません。</span>（Dù ăn cũng không béo）</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>のに</b> cũng có cảm giác “vậy mà”, nhưng cách dùng khác. Cùng là tình huống trời mưa:<br><span class='gd-jp'>雨でも、行きます。</span>（Dù trời mưa mình cũng đi: nói về quyết định của bản thân, bây giờ mưa hay không đều không quan trọng）<br><span class='gd-jp'>雨なのに、彼は行きました。</span>（Rõ ràng trời đang mưa mà anh ấy vẫn đi: việc đã xảy ra, hơi bất ngờ hoặc không đồng tình）<br>Trọng tâm của <b>ても</b> là “dù vế trước thế nào cũng không thay đổi được vế sau”; có thể là giả định, cũng có thể là chuyện đã thử.<br>Vế trước của <b>のに</b> nhất định là chuyện đã thành sự thật, giọng điệu là “rõ ràng ～ vậy mà …”, thường mang ý phàn nàn hoặc bất ngờ. Và sau のに không được dùng những cách nói như “mình sẽ ～” hay “xin hãy ～”.</div><div class='gd-warn'>Mẹo nhỏ: muốn nói “dù ～ mình cũng sẽ／xin bạn hãy ～” thì dùng ても; muốn than phiền “rõ ràng ～ mà sao lại ～” thì dùng のに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm <span class='gd-jp'>たとえ</span> vào phía trước thì sắc thái mạnh hơn: <span class='gd-jp'>たとえ反対されても、留学します。</span>（Dù bị phản đối, mình cũng sẽ đi du học）</div>","n4-24":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てしまう」khá giống với <b>“～ mất rồi”, “～ xong rồi / hết rồi”, “lỡ ～ mất”</b> trong tiếng Việt.<br>Nó có hai nghĩa: một là <b>làm xong trọn vẹn, làm hết sạch</b>, ví dụ “ăn hết cái bánh rồi”; hai là <b>lỡ làm, thấy tiếc hoặc hối hận</b>, ví dụ “Chết rồi, mình quên ví mất rồi”. Điểm chung của hai nghĩa là: <b>việc đã xong rồi, không quay lại được nữa</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Làm xong hết</span>Nhấn mạnh việc đã được làm xong trọn vẹn, làm hết sạch, thường mang cảm giác “làm một lèo cho xong” hoặc “giải quyết cho nhanh”.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題はもう全部やってしまいました。</span>（Bài tập đã làm xong hết rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯の前に、宿題をやってしまおう。</span>（Trước bữa cơm, làm cho xong bài tập đi）</div><div class='gd-sec'><span class='gd-tag'>Lỡ tay・hối tiếc</span>Làm điều không muốn làm, hoặc xảy ra kết quả không mong muốn, trong lòng thấy “chết rồi”, “tiếc quá”. Trong đời sống hằng ngày, đây là nghĩa được dùng nhiều nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を忘れてしまいました。</span>（Mình lỡ quên ví mất rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>大事なお皿を割ってしまった。</span>（Lỡ làm vỡ cái đĩa quan trọng mất rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝、寝坊してしまいました。</span>（Sáng nay mình lỡ ngủ quên mất）</div><div class='gd-sec'>Đôi khi hai nghĩa xuất hiện cùng lúc, phải xem ngữ cảnh: <span class='gd-jp'>ケーキを全部食べてしまった。</span> có thể chỉ đơn giản là “ăn hết bánh rồi”, cũng có thể là “lỡ ăn hết sạch mất rồi (chết thật)”.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Chuyển động từ sang thể て trước, rồi thêm <b>しまう</b>.<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れて</span> → <span class='gd-jp'>忘れてしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>割る</span> → <span class='gd-jp'>割って</span> → <span class='gd-jp'>割ってしまう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んでしまう</span></span><br>Bản thân しまう chia theo nhóm 1 (五段動詞): thể lịch sự là <span class='gd-jp'>しまいます</span>, quá khứ là <span class='gd-jp'>しまいました</span>, với bạn bè là <span class='gd-jp'>しまった</span>. Vì phần lớn là nói về chuyện đã xảy ra, nên <b>dạng quá khứ là dạng nghe nhiều nhất</b>.</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Rút gọn trong khẩu ngữ</span>Khi nói chuyện, người ta hay rút gọn「てしまう」thành <b>ちゃう</b>, 「でしまう」thành <b>じゃう</b>.<br><span class='gd-pair'><span class='gd-jp'>食べてしまった</span> → <span class='gd-jp'>食べちゃった</span></span><br><span class='gd-pair'><span class='gd-jp'>行ってしまう</span> → <span class='gd-jp'>行っちゃう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んでしまった</span> → <span class='gd-jp'>飲んじゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ケーキ全部食べちゃった。</span>（A, mình ăn hết sạch cái bánh mất rồi）</div><div class='gd-sec'><span class='gd-tag'>Một câu đứng riêng</span>Câu <span class='gd-jp'>しまった！</span> bật ra khi phát hiện mình sai chính là “Chết rồi!”, “Toang rồi!”.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ có thể て kết thúc bằng「んで」(<span class='gd-jp'>飲む</span>、<span class='gd-jp'>読む</span>、<span class='gd-jp'>遊ぶ</span>、<span class='gd-jp'>死ぬ</span>) đi với <b>でしまう</b>, rút gọn thành <b>じゃう</b>: <span class='gd-jp'>飲んじゃった</span>, không phải 飲んちゃった.<br>・ちゃう、じゃう là khẩu ngữ, rất tự nhiên với bạn bè; với cấp trên, khách hàng hoặc khi viết thư thì dùng <span class='gd-jp'>〜てしまいました</span> sẽ an toàn hơn.<br>・Động từ <span class='gd-jp'>しまう</span> đứng một mình có nghĩa là “cất đi”: <span class='gd-jp'>本をかばんにしまう。</span>（Cất sách vào cặp）. Phía trước không có thể て thì không phải mẫu ngữ pháp này.<br>・Trong tiếng Việt chỉ nói “mình quên rồi” là đủ, nên nhiều bạn không thêm しまう. Câu <span class='gd-jp'>忘れた</span> đúng ngữ pháp, nhưng nghe chỉ như đang nêu sự việc; nói <span class='gd-jp'>忘れてしまった</span> mới thể hiện tâm trạng “chết rồi, tiếc quá”, giống như thêm “mất” hay “lỡ” trong “lỡ quên mất rồi”.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'>Cùng một việc, dùng quá khứ thông thường「た」hay dùng「てしまった」thì cảm giác khác nhau:<br><b>た</b> = chỉ đơn giản nói việc gì đã xảy ra: <span class='gd-jp'>財布を忘れた。</span>（Mình quên mang ví）<br><b>てしまった</b> = thêm tâm trạng “chết rồi, tiếc quá”: <span class='gd-jp'>財布を忘れてしまった。</span>（Chết rồi, mình quên ví mất rồi）<br><br><b>た</b> = đã ăn: <span class='gd-jp'>ケーキを食べた。</span>（Mình đã ăn bánh）<br><b>てしまった</b> = ăn hết sạch, hoặc lỡ ăn mất: <span class='gd-jp'>ケーキを食べてしまった。</span>（Cái bánh bị mình ăn hết rồi）</div><div class='gd-warn'>Mẹo nhỏ: khi trong tiếng Việt bạn muốn thêm “～ mất rồi”, “～ hết rồi”, “chết rồi, lỡ ～ rồi” thì dùng てしまう; còn chỉ nói bình thường là chuyện gì đã xảy ra thì dùng た là đủ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là “thể て + một động từ” còn có <span class='gd-jp'>〜ておく</span> (làm sẵn để chuẩn bị trước), bạn có thể đặt cạnh nhau để so sánh. Những cách nói rút gọn khi nói chuyện như ちゃう、じゃう sẽ được tổng hợp một lượt trong bài “縮約表現”.</div>","n4-32":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜そうです」này chính là <b>「nghe nói ~」「nghe đồn ~」</b> trong tiếng Việt, chỉ khác là tiếng Nhật đặt nó ở cuối câu. Khi bạn nghe được một tin từ bản tin, dự báo thời tiết hay bạn bè rồi muốn kể lại cho người khác, hãy thêm「そうです」vào sau câu đó. Ý là: \"Đây không phải do mình nói, mình nghe lại thôi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい社長は厳しいそうです。</span>（Nghe nói giám đốc mới rất nghiêm khắc）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったそうです。</span>（Nghe nói anh Tanaka đã về rồi）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>thể thường (普通形)</b>, tức là dạng không có ます、です, kiểu \"nói chuyện với bạn bè\". Bạn cứ nghĩ thế này: nói trọn câu mình nghe được bằng dạng thân mật trước, rồi cuối cùng gắn そうです vào.<br><b>Động từ</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうです</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないそうです</span></span><span class='gd-pair'><span class='gd-jp'>結婚した</span> → <span class='gd-jp'>結婚したそうです</span></span><br><b>Tính từ い</b>：nối trực tiếp. <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いそうです</span></span><br><b>Tính từ な, danh từ</b>：nhất định phải thêm <b>だ</b> trước. <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうです</span></span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Nói nguồn tin trước</span>Phía trước thường đi với「〜によると」（theo ~）、「〜の話では」（theo lời ~ kể）để nói rõ mình nghe từ đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（Theo dự báo thời tiết, ngày mai trời sẽ mưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>林さんの話では、あの店はおいしいそうです。</span>（Theo lời anh Lâm, quán đó ăn ngon lắm）</div><div class='gd-sec'><span class='gd-tag'>Nói với bạn bè</span>Đổi です thành だ là thành dạng thân mật: <span class='gd-jp'>明日は休みだそうだ。</span>Nhưng khi tám chuyện với bạn, người ta hay nói「〜んだって」「〜って」hơn: <span class='gd-jp'>明日、休みなんだって。</span>（Nghe nói mai được nghỉ đó）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ, tính từ な <b>quên thêm だ</b> là lỗi hay gặp nhất: phải nói <span class='gd-jp'>雨だそうです</span>、<span class='gd-jp'>元気だそうです</span>. Thiếu だ thì ý nghĩa bị lệch, hoặc câu không thành câu (sẽ nói ở dưới).<br>・Phía trước không được đặt thể ます: đúng là <span class='gd-jp'>行くそうです</span>, không phải 「行きますそうです」.<br>・Muốn nói \"nghe nói <b>trước đây</b> ~\" hay \"nghe nói <b>không</b> ~\", thì quá khứ và phủ định phải đặt ở vế trước, còn そうです giữ nguyên: <span class='gd-jp'>雨だったそうです</span>（nghe nói lúc trước trời có mưa）, không thể nói 「雨だそうでした」.<br>・Trong tiếng Việt, \"nghe nói\" có thể đứng đầu câu, còn そうです trong tiếng Nhật luôn nằm ở cuối câu.</div><div class='gd-h'>Phân biệt với mẫu trông giống hệt</div><div class='gd-sec'>「様態そうです」ở bài trước (trông có vẻ ~) cũng có hình thức y hệt, điểm khác nằm ở <b>thứ đứng phía trước</b>:<br><span class='gd-jp'>このかばんは高いそうです。</span>（Nghe nói cái túi này đắt: người khác nói cho mình biết）<br><span class='gd-jp'>このかばんは高そうです。</span>（Cái túi này trông có vẻ đắt: tự mình nhìn thấy）<br><br><span class='gd-jp'>雨が降るそうです。</span>（Nghe nói trời sẽ mưa: đã xem dự báo）<br><span class='gd-jp'>雨が降りそうです。</span>（Có vẻ sắp mưa: thấy bầu trời rất tối）<br><br><span class='gd-jp'>先生は元気だそうです。</span>（Nghe nói thầy/cô khỏe）<br><span class='gd-jp'>先生は元気そうです。</span>（Thầy/cô trông có vẻ khỏe）<br><br>「いい」khá đặc biệt: \"nghe nói tốt\" là <span class='gd-jp'>いいそうです</span>, còn \"trông có vẻ tốt\" là <span class='gd-jp'>よさそうです</span>.</div><div class='gd-warn'>Mẹo phân biệt: nếu phía trước そうです là một <b>câu hoàn chỉnh</b> (高い、降る、元気だ) thì là \"nghe nói\"; nếu phía trước là dạng <b>bị cắt bớt một đoạn</b> (高、降り、元気) thì là \"trông có vẻ\".</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜らしいです」cũng diễn đạt \"nghe nói, hình như\", và「〜と言っていました」dùng để thuật lại nguyên văn lời người khác. Bạn nên học so sánh chúng cùng với bài này.</div>","n4-33":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようです」「〜みたいです」tương đương với <b>\"hình như ~\", \"có vẻ ~\"</b> trong tiếng Việt. Bạn thấy, nghe hoặc cảm nhận được một vài manh mối, rồi tự suy đoán ra kết luận. Hai mẫu này cùng nghĩa, nhưng <b>ようです trang trọng hơn</b>, còn <b>みたいです mang tính khẩu ngữ hơn</b>; khi trò chuyện hằng ngày dùng みたい là tự nhiên nhất.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Suy đoán dựa trên manh mối</span>Đây là cách dùng phổ biến nhất. Bạn chưa chắc chắn 100%, nhưng trong tay có bằng chứng.</div><div class='gd-ex-line'>・<span class='gd-jp'>電気が消えていますね。田中さんはもう帰ったようです。</span>（Đèn tắt rồi nhỉ, hình như anh Tanaka đã về rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>外がうるさいですね。何かあったみたいです。</span>（Bên ngoài ồn quá, hình như có chuyện gì xảy ra rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪をひいたみたいです。</span>（Hình như mình bị cảm rồi）</div><div class='gd-sec'>Câu cuối dựa trên cảm giác của chính cơ thể mình, ví dụ đau họng, ớn lạnh. Những thứ này cũng được tính là manh mối nên rất hay dùng.</div><div class='gd-sec'><span class='gd-tag'>So sánh: giống như ~</span>Biết rõ không phải vậy, chỉ nói là \"rất giống\". Thường đi cùng <span class='gd-jp'>まるで</span> (cứ như là).</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢のようです。</span>（Cứ như là đang mơ vậy）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは日本語が上手で、日本人みたいです。</span>（Anh Tanaka giỏi tiếng Nhật, cứ như người Nhật vậy）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ, tính từ い: nối trực tiếp, cả hai mẫu đều giống nhau.<br><span class='gd-pair'><span class='gd-jp'>帰った</span> → <span class='gd-jp'>帰ったようです</span>／<span class='gd-jp'>帰ったみたいです</span></span><br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいようです</span>／<span class='gd-jp'>忙しいみたいです</span></span></div><div class='gd-sec'><b>Tính từ な và danh từ thì khác nhau</b> (ở thì hiện tại):<br>ようです：tính từ な thêm「な」, danh từ thêm「の」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のようです</span></span><br>みたいです：không cần thêm gì, nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生みたいです</span></span><br>Ở quá khứ, cả hai đều nối với「だった」：<span class='gd-jp'>学生だったようです</span>／<span class='gd-jp'>学生だったみたいです</span>.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Giữa bạn bè</span>Bỏ です đi, nói「〜みたい」「〜みたいだね」. <span class='gd-jp'>ようだ</span> giống văn viết hơn, khi trò chuyện rất ít dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、休みみたい。</span>（Quán đó hình như nghỉ rồi）</div><div class='gd-sec'><span class='gd-tag'>Phía sau nối danh từ</span>Thành「ような／みたいな」＋ danh từ, nghĩa là \"giống như ~ vậy\".</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんみたいな人になりたいです。</span>（Mình muốn trở thành người như anh Tanaka）</div><div class='gd-sec'><span class='gd-tag'>Phía sau nối hành động</span>Thành「ように／みたいに」, nghĩa là \"(làm) giống như ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもみたいに喜んでいます。</span>（Vui mừng như một đứa trẻ）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な là dễ nối sai nhất: đúng là <span class='gd-jp'>学生みたい</span>、<span class='gd-jp'>学生のようです</span>, không phải 「学生のみたい」; đúng là <span class='gd-jp'>静かみたい</span>, không phải 「静かなみたい」.<br>・Việc chính mắt mình đã xác nhận rồi thì đừng thêm vào: bạn đang đứng giữa mưa thì nói thẳng <span class='gd-jp'>雨が降っています</span>. Chỉ khi nghe tiếng mưa, hoặc thấy người ngoài cửa sổ che dù, mới nói <span class='gd-jp'>雨が降っているようです</span>.<br>・<span class='gd-jp'>学生みたい</span> có thể là \"hình như là sinh viên\" (suy đoán), cũng có thể là \"giống như sinh viên\" (thực ra không phải), phải xem ngữ cảnh.<br>・Khi viết báo cáo hay trong hoàn cảnh trang trọng, dùng ようです; みたい quá khẩu ngữ.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cùng chủ đề trời mưa:<br><b>そうです（様態）</b>＝nhìn bề ngoài, <b>sắp</b> như thế: <span class='gd-jp'>雨が降りそうです。</span>（Trông có vẻ sắp mưa: trên trời nhiều mây đen, chưa mưa）<br><b>ようです／みたいです</b>＝dựa trên manh mối, suy đoán là <b>đã</b> như thế: <span class='gd-jp'>雨が降っているみたいです。</span>（Hình như đang mưa: nghe thấy tiếng mưa）<br><b>らしいです</b>＝gần với việc <b>nghe người khác nói</b>: <span class='gd-jp'>東京は雨が降っているらしいです。</span>（Nghe nói Tokyo đang mưa: xem tin tức, nghe bạn kể）</div><div class='gd-sec'>Tính từ cũng vậy: <span class='gd-jp'>おいしそう</span> là \"trông có vẻ ngon\", chỉ nhìn bề ngoài; <span class='gd-jp'>おいしいみたい</span> là \"hình như ngon\", ví dụ thấy ngày nào cũng xếp hàng dài.</div><div class='gd-warn'>Mẹo phân biệt: \"chỉ nhìn bề ngoài, sắp ~\" dùng そう; \"mình có manh mối, đoán là hình như ~\" dùng よう／みたい; \"nghe người ta nói ~\" dùng らしい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo, hãy học đối chiếu <span class='gd-jp'>〜らしいです</span> cùng hai loại <span class='gd-jp'>〜そうです</span> (vẻ ngoài, nghe nói), như vậy các cách nói suy đoán của bạn sẽ đầy đủ.</div>","n4-34":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「らしい」có hai nghĩa. Nghĩa thứ nhất là <b>「nghe nói hình như ～」</b>, giống như bạn nói với bạn bè: \"Này, nghe nói anh Nakamura sắp đổi việc đấy\". Tin này bạn nghe từ nơi khác, chính bạn cũng không chắc 100%. Nghĩa thứ hai là <b>「rất ra dáng ～」</b>, giống như tiếng Việt nói \"đúng chất mùa xuân\", \"rất nam tính\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nghe nói・hình như</span>Thông tin là bạn nghe được hoặc nhìn thấy, rồi dựa vào đó bạn thấy \"chắc là như vậy\".</div><div class='gd-ex-line'>・<span class='gd-jp'>中村さんは会社をやめるらしいです。</span>（Nghe nói anh Nakamura sắp nghỉ việc）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメンはおいしいらしいよ。</span>（Nghe nói mì ramen ở quán đó ngon lắm đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは昨日休んだらしいです。</span>（Hình như hôm qua anh Tanaka nghỉ làm）</div><div class='gd-sec'><span class='gd-tag'>Rất ra dáng ～</span>Đặt sau danh từ, nghĩa là \"đúng với vai trò, đúng với vẻ mà mùa đó nên có\". Thường mang ý khen.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>（Thời tiết hôm nay đúng chất mùa xuân nhỉ）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は本当に男らしい人です。</span>（Anh ấy thật sự là người rất nam tính）</div><div class='gd-sec'>「らしい」theo nghĩa này chia giống tính từ い (tính từ kết thúc bằng い như <span class='gd-jp'>高い</span>), nên phủ định là <b>らしくない</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はなんだか田中さんらしくないですね。</span>（Hôm nay anh Tanaka có vẻ không giống anh ấy mọi khi nhỉ）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: dùng dạng không có ます, nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: bỏ「だ」trước rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → bỏ だ → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>Nếu là thì quá khứ「だった」thì giữ nguyên, không bỏ:<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'>Với người lớn tuổi hoặc trong hoàn cảnh trang trọng, thêm「です」phía sau để thành cách nói lịch sự; nói với bạn bè thì chỉ cần「らしい」là đủ.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau tính từ な và danh từ đừng để lại「だ」: phải nói <span class='gd-jp'>静からしい</span>, không được nói 静かだらしい.<br>・Dạng ます không nối thẳng với らしい: phải nói <span class='gd-jp'>行くらしいです</span>, không được nói 行きますらしい.<br>・Cùng một từ có thể có hai nghĩa: <span class='gd-jp'>あの人は学生らしい。</span>có thể là \"hình như người đó là sinh viên\". Còn <span class='gd-jp'>本当に学生らしい服ですね。</span>là \"đúng là bộ đồ rất ra dáng sinh viên\". Hãy xem ngữ cảnh để đoán; nếu phía trước có từ chỉ mức độ như「本当に」「とても」thì phần lớn là nghĩa thứ hai.<br>・Nghĩa thứ hai mang ý tích cực là \"đúng với vẻ nên có\". Nói trẻ con <span class='gd-jp'>子供らしい</span>là khen bé hồn nhiên; muốn nói người lớn trẻ con, người Nhật sẽ dùng <span class='gd-jp'>子供っぽい</span>, chứ không nói 子供らしい.<br>・Nghĩa thứ nhất dùng cho chuyện bạn nghe được mà chưa tự xác nhận. Việc chính mắt bạn thấy, rất chắc chắn thì cứ nói thẳng, đừng thêm らしい.</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Cùng nói về thời tiết ngày mai:<br><b>そうです（tin nghe lại）</b>: <span class='gd-jp'>天気予報によると、明日は雨だそうです。</span>（Theo dự báo thời tiết, ngày mai sẽ mưa）Có nguồn tin rõ ràng, bạn chỉ chuyển lời lại y nguyên.<br><b>らしいです</b>: <span class='gd-jp'>明日は雨らしいです。</span>（Hình như ngày mai sẽ mưa）Cũng là nghe lại, nhưng nguồn mơ hồ hơn, kiểu \"ai cũng nói vậy\", lại có thêm chút phán đoán của bạn nên giọng kém chắc chắn hơn.<br><b>ようです・みたいです</b>: （nhìn ra cửa sổ）<span class='gd-jp'>雨が降っているみたいです。</span>（Hình như bên ngoài đang mưa）Đây là phán đoán sau khi chính bạn nhìn thấy, cảm nhận được.</div><div class='gd-sec'>Thêm một ví dụ nhiều người hay lẫn, trên bàn có một miếng bánh:<br><span class='gd-jp'>おいしそう！</span>（Nhìn ngon quá!）Đây là cảm giác sau khi nhìn thấy, dùng「そうです（dạng vẻ ngoài）」.<br><span class='gd-jp'>このケーキ、おいしいらしいよ。</span>（Nghe nói bánh này ngon lắm đó）Đây là nghe người khác nói.</div><div class='gd-warn'>Mẹo phân biệt: nếu tin là \"người khác nói\" thì dùng らしい hoặc そうです（nghe lại）. Chỉ muốn truyền lời y nguyên thì dùng そうです; có thêm chút phỏng đoán của mình, nguồn tin hơi mơ hồ thì dùng らしい. Còn nếu là \"chính mình thấy, cảm nhận được\" thì dùng ようです、みたいです hoặc ～そう（dạng vẻ ngoài）.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Hãy ôn lại cùng lúc n4-32「～そうです（nghe lại）」và n4-33「～ようです・～みたいです」. Khi tách rõ hai nhóm \"nghe được\" và \"tự mình thấy\", bạn sẽ ít dùng sai các câu suy đoán.</div>","n4-35":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜はずです」nghĩa là <b>「theo lẽ thường thì hẳn là ～」</b>. Bạn có căn cứ, ví dụ đã xem lịch tàu, đã nghe anh ấy nói, biết anh ấy là bác sĩ, từ đó suy ra một kết luận và rất tự tin, thì dùng はず. Giống chữ \"hẳn là\" trong câu \"Anh ấy tan làm lúc sáu giờ, giờ <b>hẳn là</b> về đến nhà rồi\".</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Suy đoán có căn cứ</span>Trước có một lý do \"vì ～\", rồi suy ra \"nên hẳn là ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは6時に会社を出たから、もう家に着いたはずです。</span>（Anh Tanaka rời công ty lúc sáu giờ rồi, giờ hẳn là đã về đến nhà）</div><div class='gd-ex-line'>・<span class='gd-jp'>木村さんは医者だから、薬に詳しいはずです。</span>（Anh Kimura là bác sĩ nên hẳn là rất rành về thuốc）</div><div class='gd-sec'><span class='gd-tag'>Thảo nào</span>Thấy nguyên nhân rồi chợt hiểu ra, thường dùng「〜はずだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いている。寒いはずだ。</span>（Cửa sổ đang mở, thảo nào lạnh thế）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Cách nối giống như khi đứng trước danh từ:<br><b>Động từ</b>: dạng thông thường (tức dạng không có ます) nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くはず</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないはず</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはず</span></span><br><b>Tính từ い</b>: nối trực tiếp.<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはず</span></span><br><b>Tính từ な</b>: thêm「な」.<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなはず</span></span><br><b>Danh từ</b>: thêm「の」.<span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのはず</span></span><br>Nếu muốn nói quá khứ, tính từ な và danh từ dùng「だった」: <span class='gd-jp'>学生だったはず</span>.<br>Nói với bạn bè dùng「はずだ」, nói với thầy cô, khách hàng dùng「はずです」.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>はずがない</span>Không thể nào ～, phủ định rất mạnh.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人がうそをつくはずがありません。</span>（Người đó không thể nào nói dối）</div><div class='gd-sec'><span class='gd-tag'>はずだった</span>Lẽ ra phải ～, nhưng kết quả không như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車は10時に着くはずだったのに、30分も遅れた。</span>（Lẽ ra tàu đến lúc mười giờ, vậy mà trễ tận ba mươi phút）</div><div class='gd-sec'><span class='gd-tag'>はずなのに</span>Rõ ràng lẽ ra phải ～, sao lại thế này.</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵はかばんに入れたはずなのに、ない。</span>（Rõ ràng mình đã bỏ chìa khóa vào túi rồi mà không thấy đâu）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trong tiếng Việt có \"chắc là, hẳn là\" (suy đoán) và \"nên\" (khuyên): \"Anh ấy chắc đến rồi\" là suy đoán, \"Bạn nên ngủ sớm\" là lời khuyên. <b>はず chỉ có nghĩa suy đoán</b>. Muốn khuyên ai thì dùng <span class='gd-jp'>早く寝たほうがいいですよ</span>. Nếu nói <span class='gd-jp'>早く寝るはずです</span>, nghĩa sẽ thành \"theo lẽ thường thì bạn sẽ ngủ sớm\".<br>・Danh từ phải thêm の, tính từ な phải thêm な: phải nói <span class='gd-jp'>休みのはず</span>、<span class='gd-jp'>静かなはず</span>, không được nói「休みはず」「学生だはず」.<br>・Việc tự mình quyết định làm thì đừng dùng はず. Tiếng Việt hay nói \"mai chắc mình sẽ đi\", nhưng tiếng Nhật phải nói <span class='gd-jp'>明日は行くつもりです</span> hoặc <span class='gd-jp'>行くと思います</span>. Nếu nói <span class='gd-jp'>行くはずです</span>, nghe sẽ giống như \"theo lịch đã sắp xếp thì tôi sẽ đi\".<br>・<span class='gd-jp'>来ないはずです</span>là \"hẳn là sẽ không đến\", thuộc suy đoán; còn <span class='gd-jp'>来るはずがありません</span>là \"không thể nào đến\", giọng mạnh hơn nhiều.</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Cùng là đang đợi anh Tanaka:<br><span class='gd-jp'>田中さんは来るはずです。</span>（Anh ấy đã hẹn sẽ đến, theo lẽ thường là sẽ đến: có căn cứ, rất chắc chắn）<br><span class='gd-jp'>田中さんは来るでしょう。</span>（Chắc anh ấy sẽ đến thôi: đoán thông thường）<br><span class='gd-jp'>田中さんは来るかもしれません。</span>（Có thể anh ấy sẽ đến, cũng có thể không: khoảng năm mươi - năm mươi）</div><div class='gd-warn'>Mẹo phân biệt: nếu bạn nói được căn cứ kiểu \"vì ～ nên\" và rất chắc chắn thì dùng はず; chỉ đoán bâng quơ thì dùng でしょう; không chắc lắm thì dùng かもしれません.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Lên N3 bạn sẽ học「べき」(nên làm ～), đúng là nghĩa \"nên\" trong tiếng Việt. Hãy nhớ はず và べき tách riêng, bạn sẽ không bị lẫn nữa.</div>","n4-54":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể ば giống với <b>「chỉ cần ~ là ~」</b> trong tiếng Việt. <span class='gd-jp'>安ければ買います</span> = chỉ cần rẻ là tôi mua. Trọng tâm của nó nằm ở <b>điều kiện</b> phía trước: điều kiện thành lập thì kết quả phía sau sẽ theo đó mà đến.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Chỉ cần ~ là ~</span>Nói rằng hễ một điều kiện thành lập thì sẽ có kết quả nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>安ければ買います。</span>（Nếu rẻ thì tôi mua）</div><div class='gd-ex-line'>・<span class='gd-jp'>急げば間に合いますよ。</span>（Nhanh lên một chút thì vẫn kịp đấy）</div><div class='gd-sec'><span class='gd-tag'>Quy luật không đổi</span>Những chuyện kiểu \"lần nào cũng vậy\" như thiên nhiên, lẽ thường.</div><div class='gd-ex-line'>・<span class='gd-jp'>春になれば、桜が咲きます。</span>（Đến mùa xuân thì hoa anh đào nở）</div><div class='gd-sec'><span class='gd-tag'>Nếu không ~</span>Dạng phủ định, hay dùng để nhắc \"không làm là toi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>急がなければ、間に合いません。</span>（Không nhanh lên thì sẽ không kịp）</div><div class='gd-h'>Chia thế nào: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「え」 cùng hàng, rồi thêm 「ば」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành け → <span class='gd-jp'>行けば</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲めば</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買えば</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てば</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れば</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」 ở cuối, thêm 「れば」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きれば</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見れば</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>（くれば）</span></div><div class='gd-sec'><b>「Nếu không ~」</b>: chuyển sang thể ない trước, bỏ 「い」 của 「ない」, rồi thêm 「ければ」.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなければ</span></span><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなければ</span></span></div><div class='gd-sec'><b>Tính từ い</b>: bỏ 「い」 ở cuối, thêm 「ければ」.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒ければ</span></span><br><b>Tính từ な・danh từ</b>: không dùng ば, thêm thẳng 「なら」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なら</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>来れば</span> đọc là <b>くれば</b>, không phải きれば, cũng không phải これば.<br>・<span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よければ</span>, không có 「いければ」. Ví dụ: <span class='gd-jp'>よければ、どうぞ。</span>（Nếu bạn không phiền thì xin mời dùng）<br>・Nhóm 1 không phải cứ thêm れば: là <span class='gd-jp'>行けば</span>, không phải 行くれば.<br>・Khi vế trước là một <b>hành động</b> (đi, đến, ăn…) mà vế sau lại là \"hãy ~\" hoặc \"~ nhé\" (rủ rê), dùng ば nghe rất gượng, phải đổi sang たら:<br>×駅に着けば、電話してください。<br>○<span class='gd-jp'>駅に着いたら、電話してください。</span>（Đến ga rồi thì gọi cho tôi nhé）<br>Còn nếu vế trước là <b>trạng thái</b> (ある、いる、できる, tính từ) thì không sao: <span class='gd-jp'>時間があれば、来てください。</span>（Nếu có thời gian thì hãy đến nhé）</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Tiếng Nhật có bốn cách nói \"nếu\". Ta so sánh trong cùng một tình huống \"đi ra ga\":<br><b>ば</b> = chỉ cần ~ là ~: <span class='gd-jp'>駅まで歩けば、10分で着きます。</span>（Nếu đi bộ ra ga thì 10 phút là tới）<br><b>たら</b> = sau khi ~, vế sau có thể là lời nhờ, lời rủ: <span class='gd-jp'>駅に着いたら、電話してください。</span>（Đến ga rồi thì gọi cho tôi nhé）<br><b>と</b> = hễ ~ là chắc chắn ~, như chỉ đường, máy móc phản ứng: <span class='gd-jp'>この道をまっすぐ行くと、駅があります。</span>（Đi thẳng con đường này là thấy ga）<br><b>なら</b> = tiếp lời người kia vừa nói để đưa ra gợi ý, việc chưa xảy ra: <span class='gd-jp'>駅に行くなら、この道が近いですよ。</span>（Nếu bạn định ra ga thì đi đường này gần đấy）</div><div class='gd-warn'>Mẹo nhỏ để chọn: \"chỉ cần ~ là\" dùng ば; \"sau khi ~\" hoặc vế sau là nhờ vả, rủ rê thì dùng たら; \"hễ ~ là chắc chắn\" dùng と; \"nếu bạn nói định ~\" dùng なら. Lúc không chắc thì cứ dùng たら trước, ít sai nhất.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm 「いい」 phía sau = \"~ là được / ~ thì tốt\", rất hay dùng khi hỏi ý kiến người khác: <span class='gd-jp'>どうすればいいですか。</span>（Nên làm thế nào thì tốt?）<br>「なければ」 thêm 「なりません」 là \"nhất định phải ~\": <span class='gd-jp'>明日は早く起きなければなりません。</span>（Ngày mai nhất định phải dậy sớm）</div>","n4-55":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たら」 giống với <b>「nếu ~」「khi ~ xong thì ~」</b> trong tiếng Việt. Những câu như \"nếu có tiền thì muốn đi du lịch\", \"về đến nhà là gọi cho bạn\" đều dùng nó, là cách nói điều kiện phổ biến nhất trong đời sống hằng ngày. Nó còn có một cách dùng đặc biệt: <b>「vừa ~ thì phát hiện ra ~」</b>.</div><div class='gd-h'>Cách nối: biết thể た là biết たら</div><div class='gd-sec'>Chia thể た trước, rồi thêm 「ら」 là xong. Cách chia thể た của động từ giống thể て, chỉ là đổi て thành た, で thành だ.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したら</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来たら</span>（きたら）</span></div><div class='gd-sec'>Tính từ và danh từ cũng dùng được, vẫn là chuyển sang dạng quá khứ rồi thêm ら:<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だったら</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったら</span></span><br>Phủ định cũng vậy: <span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかったら</span></span>（nếu không đi）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nếu ~ thì</span>Chưa chắc sẽ xảy ra, chỉ là giả định.</div><div class='gd-ex-line'>・<span class='gd-jp'>お金があったら、旅行したい。</span>（Nếu có tiền thì tôi muốn đi du lịch）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だったら、行きません。</span>（Nếu ngày mai mưa thì tôi không đi）</div><div class='gd-sec'><span class='gd-tag'>Sau khi ~ thì</span>Việc chắc chắn sẽ xảy ra, nói về chuyện sẽ làm \"đến lúc đó\".</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、電話します。</span>（Về đến nhà là tôi gọi cho bạn）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着いたら、連絡してください。</span>（Đến ga rồi thì liên lạc với tôi nhé）</div><div class='gd-sec'><span class='gd-tag'>Phát hiện ra</span>Làm một việc nào đó xong thì phát hiện điều bất ngờ. Lúc này vế sau phải dùng <b>thì quá khứ</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたら、猫がいた。</span>（Vừa mở cửa sổ ra thì thấy có một con mèo）</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったら、母が来ていました。</span>（Về đến nhà thì thấy mẹ tôi đã đến）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・たら luôn là <b>vế trước xảy ra trước, vế sau mới xảy ra sau</b>. <span class='gd-jp'>日本へ行ったら、ガイドブックを買います。</span> nghĩa là \"đến Nhật rồi mới mua\". Nếu bạn muốn nói \"mua trước khi đi\" thì phải dùng なら (phần dưới sẽ nói).<br>・<span class='gd-jp'>来たら</span> đọc là <b>きたら</b>, không phải こたら.<br>・Khi kể một chuỗi việc mình đã làm trong quá khứ thì đừng dùng たら. \"Về nhà rồi ăn cơm\" là <span class='gd-jp'>家に帰って、ご飯を食べました。</span> \"たら + quá khứ\" chuyên dùng để nói \"gặp phải, phát hiện ra điều gì\", nếu vế sau là hành động mình chủ ý làm thì nghe rất gượng.<br>・Muốn thêm nghĩa \"nếu\" thì phía trước có thể đặt <span class='gd-jp'>もし</span>: <span class='gd-jp'>もし雨だったら</span>. Nhưng với việc chắc chắn sẽ xảy ra kiểu \"sau khi ~\" thì không thêm もし được, vì <span class='gd-jp'>もし家に帰ったら</span> nghe như thể không chắc mình có về được nhà hay không.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Ở N4 bạn sẽ học bốn kiểu điều kiện: たら、ば、と、なら. Hãy xem cùng một tình huống để so sánh:<br><b>たら</b> = dùng được nhiều nhất, vế sau có thể là lời nhờ, mong muốn, dự định: <span class='gd-jp'>春になったら、日本へ行きたい。</span>（Đến mùa xuân tôi muốn đi Nhật）<br><b>と</b> = lần nào cũng chắc chắn như vậy, giống hiện tượng tự nhiên: <span class='gd-jp'>春になると、桜が咲きます。</span>（Hễ đến mùa xuân là hoa anh đào nở）<br><b>ば</b> = nhấn mạnh \"chỉ cần có điều kiện này là ~\": <span class='gd-jp'>春になれば、暖かくなります。</span>（Chỉ cần đến mùa xuân là trời sẽ ấm lên）<br><b>なら</b> = nối vào lời người kia vừa nói để đưa ra gợi ý, và <b>có thể nói chuyện của vế sau trước</b>: <span class='gd-jp'>日本へ行くなら、春がいいですよ。</span>（Nếu bạn định đi Nhật thì mùa xuân là tốt đấy）</div><div class='gd-sec'>Khác biệt rõ nhất là khi \"nhờ người khác làm gì\": <span class='gd-jp'>駅に着いたら、電話してください。</span> rất tự nhiên; còn nếu đổi thành と hoặc ば, nói 「駅に着くと」「駅に着けば」 rồi nối 「電話してください」, người Nhật nghe sẽ thấy không đúng.</div><div class='gd-warn'>Mẹo nhỏ để chọn: lúc phân vân cứ dùng たら trước, phần lớn trường hợp đều ổn. Ngoại lệ là chuyện \"lần nào cũng vậy\" thì thường dùng と hơn; còn \"nghe người kia định làm gì đó rồi đưa gợi ý\" thì phải dùng なら.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm 「いいです」 phía sau sẽ thành lời gợi ý: <span class='gd-jp'>先生に聞いたらいいですよ。</span>（Bạn cứ hỏi thầy cô là được mà）</div>","n4-56":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「なら」giống với <b>「nếu là ~ thì…」</b> hay <b>「nói đến ~ thì…」</b> trong tiếng Việt. Bạn bè nói「mình muốn đi tắm onsen」, bạn đáp theo:「Nói đến onsen thì Hakone được lắm đó」. Bạn đón lấy chuyện người kia vừa nhắc, rồi mới đưa ra gợi ý hoặc ý kiến của mình. Đây là cách dùng なら phổ biến nhất.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đáp lời và đưa gợi ý</span>Người kia nhắc đến một chuyện, bạn đưa ý kiến về chính chuyện đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：週末、温泉に行きたいな。</span>（Cuối tuần mình muốn đi tắm onsen quá）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：温泉なら、箱根がいいよ。</span>（Nói đến onsen thì Hakone được lắm đó）</div><div class='gd-sec'><span class='gd-tag'>Giả định trước, rồi nói dự định</span>「Nếu là như vậy thì mình sẽ ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたが行くなら、私も行きます。</span>（Nếu bạn đi thì mình cũng đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>家賃が予算内なら、契約したいです。</span>（Nếu tiền thuê nhà nằm trong ngân sách thì tôi muốn ký hợp đồng）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ</b>：nối thẳng với thể thường (cách nói không có ます).<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くなら</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないなら</span></span><br><b>Tính từ い</b>：nối thẳng.<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いなら</span></span><br><b>Tính từ な</b>：bỏ「だ」rồi mới nối.<span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かなら</span></span><br><b>Danh từ</b>：nối thẳng.<span class='gd-pair'><span class='gd-jp'>日本語</span> → <span class='gd-jp'>日本語なら</span></span></div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋なら</span>Nghĩa là「nói đến ~ thì」, thu hẹp câu chuyện vào đúng một thứ.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーなら、駅前の店がおいしいですよ。</span>（Nói đến cà phê thì quán trước ga ngon lắm đó）</div><div class='gd-sec'><span class='gd-tag'>それなら</span>Đặt ở đầu câu, nghĩa là「vậy thì」. Trong văn nói, nhiều khi người ta chỉ nói「なら」.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は忙しいです。</span>（Ngày mai tôi bận）</div><div class='gd-ex-line'>・<span class='gd-jp'>B：それなら、あさってにしましょう。</span>（Vậy thì để ngày kia nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な <b>không thêm だ</b>: phải nói <span class='gd-jp'>学生なら</span>, không phải 学生だなら.<br>・Việc ở vế sau なら <b>có thể làm trước việc ở vế trước</b>: <span class='gd-jp'>京都へ行くなら、ホテルを早く予約したほうがいいですよ。</span>（Nếu đi Kyoto thì nên đặt khách sạn sớm）Đặt khách sạn là việc làm trước khi đi. Điểm này ngược hẳn với たら.<br>・Sau なら thường là lời khuyên, yêu cầu, dự định hoặc phán đoán của chính bạn. Chuyện chắc chắn sẽ xảy ra như「Xuân đến là hoa nở」thì không dùng なら mà dùng と: <span class='gd-jp'>春になると、桜が咲きます。</span>（Cứ đến mùa xuân là hoa anh đào nở）</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>なら và たら đều có thể dịch là「nếu ~ thì」nên dễ nhầm nhất. Khác nhau ở <b>việc ở vế sau được làm lúc nào</b>. Cùng là đi Nhật:<br><b>なら</b>＝phải làm từ trước khi đi:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行くなら、日本語を勉強しておいたほうがいいよ。</span>（Nếu đi Nhật thì nên học trước chút tiếng Nhật）</div><div class='gd-sec'><b>たら</b>＝sau khi đến nơi mới làm:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行ったら、ラーメンを食べたい。</span>（Đến Nhật rồi thì mình muốn ăn ramen）</div><div class='gd-sec'>Nếu đổi câu đầu thành「行ったら」, nghĩa sẽ thành「đến Nhật rồi mới bắt đầu học tiếng Nhật」, không đúng ý bạn muốn nói. Ngược lại,「Đến ga rồi thì gọi cho tôi」chắc chắn là đến nơi rồi mới gọi, nên phải dùng たら: <span class='gd-jp'>駅に着いたら、電話してください。</span>（Đến ga rồi thì gọi điện cho tôi nhé）</div><div class='gd-warn'>Mẹo phân biệt nhanh:「chưa làm, đưa gợi ý trước」dùng なら;「làm xong, đến nơi rồi mới xảy ra」dùng たら. Khi người kia vừa nhắc đến một chuyện và bạn đáp lại bằng ý kiến, gần như luôn là なら.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếng Nhật có bốn kiểu「nếu」: と、ば、たら、なら. Học xong なら, bạn có thể đem <span class='gd-jp'>〜ば</span>（n4-54）và <span class='gd-jp'>〜と</span>（n4-57）ra so sánh cùng, xem mỗi mẫu dùng khi nào.</div>","n4-59":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể bị động (受身形) giống với <b>「bị / được ~」</b> trong tiếng Việt: <span class='gd-jp'>先生に褒められた</span> là「được thầy cô khen」. Có điều tiếng Nhật dùng bị động nhiều hơn tiếng Việt, và còn hay mang cảm giác <b>「mình bị làm cho xui xẻo, khó chịu」</b>, giống như tiếng Việt nói「bị anh ta làm thế, tôi đau đầu quá」.</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>：đổi âm cuối sang âm hàng「あ」cùng hàng, rồi thêm「れる」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br>Động từ kết thúc bằng「う」cần chú ý: う không đổi thành あ mà đổi thành <b>わ</b>:<br><span class='gd-pair'><span class='gd-jp'>言う</span> → đổi う thành わ → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>誘う</span> → <span class='gd-jp'>誘われる</span></span><br>Nghĩ từ thể ます cũng được: 「き」của <span class='gd-jp'>書きます</span> đổi thành「か」, rồi thêm「れます」→<span class='gd-jp'>書かれます</span>.</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>：bỏ「る」ở cuối, thêm「られる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Sau khi chia xong,「〜れる／〜られる」được coi như động từ nhóm 2 và chia tiếp: <span class='gd-jp'>叱られます</span>、<span class='gd-jp'>叱られた</span>、<span class='gd-jp'>叱られて</span>.</div><div class='gd-h'>Ba kiểu bị động hay gặp nhất</div><div class='gd-sec'>Dù là kiểu nào, <b>người làm hành động luôn đi với「に」</b>.</div><div class='gd-sec'><span class='gd-tag'>Mình bị người khác làm gì đó</span>（私は）人に＋bị động. Giống「bị / được」của tiếng Việt nhất, việc tốt hay xấu đều dùng được.<br><span class='gd-jp'>先生が私を褒めた。</span>（Thầy cô khen tôi）→ đổi sang bị động:</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に褒められた。</span>（Tôi được thầy cô khen）</div><div class='gd-ex-line'>・<span class='gd-jp'>母に叱られました。</span>（Tôi bị mẹ mắng）</div><div class='gd-sec'><span class='gd-tag'>Đồ của mình bị làm sao đó</span>（私は）人に＋đồ vật を＋bị động. Tiếng Nhật quen lấy「người bị thiệt」làm chủ ngữ, còn đồ vật đi với「を」.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（Trên tàu điện bị giẫm vào chân）</div><div class='gd-ex-line'>・<span class='gd-jp'>弟にケーキを食べられた。</span>（Bánh bị em trai ăn mất rồi）</div><div class='gd-sec'><span class='gd-tag'>Bị làm cho phiền phức</span>Việc người khác làm vốn không liên quan đến bạn, nhưng bạn lại chịu thiệt vì nó. Ngay cả những hành động như「mưa」「khóc」cũng có thể chia bị động, và tiếng Việt thường diễn đạt kiểu「gặp phải ~」「bị ~ làm phiền」.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨に降られて、びしょびしょになった。</span>（Gặp mưa nên ướt sũng cả người）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に子供に泣かれて、寝られなかった。</span>（Nửa đêm con khóc mãi nên tôi không ngủ được）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Bị động của <span class='gd-jp'>言う</span> là <span class='gd-jp'>言われる</span>, không phải「言あれる」cũng không phải「言られる」. <span class='gd-jp'>買う</span>、<span class='gd-jp'>使う</span> cũng đổi sang わ như vậy.<br>・Người làm hành động dùng「に」: phải nói <span class='gd-jp'>先生に褒められた</span>, không phải「先生が褒められた」, vì câu đó sẽ thành「thầy cô được khen」.<br>・Tiếng Việt nói「chân tôi bị giẫm」, nhưng tiếng Nhật đừng dịch thẳng thành「私の足が踏まれた」. Cách nói tự nhiên là <span class='gd-jp'>足を踏まれた</span>.<br>・Tiếng Việt thường dùng「bị」cho chuyện xấu và「được」cho chuyện tốt, còn tiếng Nhật chỉ có một thể bị động cho cả hai: <span class='gd-jp'>褒められた</span>（được khen）、<span class='gd-jp'>誘われた</span>（được rủ）đều rất hay gặp.<br>・Gặp câu bị động, hãy tự hỏi trước:「nhân vật chính có phải là người bị ảnh hưởng, thậm chí bị thiệt không?」Như vậy bạn sẽ bắt được sắc thái của câu.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>受身形 vs 可能形</b>：với động từ nhóm 2 và 来る, hai thể này giống hệt nhau.<br><span class='gd-jp'>犬にパンを食べられた。</span>（Bánh mì bị chó ăn mất: bị động）<br><span class='gd-jp'>このパンはまだ食べられる。</span>（Cái bánh mì này vẫn ăn được: khả năng）<br>Nếu phía trước có「người + に」và câu nói về ai bị làm sao thì là bị động; nếu câu nói về「có thể hay không」thì là thể khả năng.</div><div class='gd-sec'><b>〜られる vs 〜てもらう</b>：cùng là người khác đến chỗ bạn.<br><span class='gd-jp'>友達に来られて困った。</span>（Bạn tự dưng đến, tôi thấy phiền）<br><span class='gd-jp'>友達に来てもらって助かった。</span>（Bạn đến giúp, đúng là cứu tôi một bàn）<br>Bị động thường mang cảm giác「bị làm phiền」; còn てもらう là「nhờ người ta giúp mình」, mang ý biết ơn.</div><div class='gd-warn'>Mẹo phân biệt nhanh: trong lòng nghĩ「bị ~, xui quá」thì dùng 〜れる／〜られる; nghĩ「người ta giúp mình, thật tốt」thì dùng 〜てもらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thể sai khiến (bảo người khác làm): <span class='gd-jp'>書かせる</span>; tiếp theo là sai khiến bị động (bị ép phải làm): <span class='gd-jp'>母に野菜を食べさせられた。</span>（Bị mẹ ép ăn rau）. Ngoài ra, 〜れる／〜られる còn dùng để bày tỏ sự kính trọng với bề trên, ví dụ <span class='gd-jp'>先生が書かれた本</span>（cuốn sách do thầy cô viết）. Bạn sẽ gặp lại khi học thể tôn kính.</div>","n4-60":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể sai khiến (使役形) giống với <b>“bắt ~ làm”, “cho ~ làm”, “để ~ làm”</b> trong tiếng Việt. Ví dụ như “mẹ bắt con ăn rau”, “quản lý cho bạn làm part-time tan ca trước”. Trong tiếng Nhật, các câu này đều biến động từ thành 「〜せる／〜させる」. Nó có thể là <b>ép đối phương làm (cưỡng chế)</b>, cũng có thể là <b>đối phương muốn làm và bạn đồng ý cho làm (cho phép)</b>. Bạn phải dựa vào ngữ cảnh để phán đoán nhé.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Ép buộc</span>Bất kể đối phương có muốn hay không, vẫn bắt họ làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせます。</span>(Mẹ bắt con ăn rau)</div><div class='gd-sec'><span class='gd-tag'>Cho phép</span>Đối phương muốn làm, bạn cho họ làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供が遊びたがっていたので、公園で遊ばせました。</span>(Con rất muốn chơi nên tôi cho con chơi ở công viên)</div><div class='gd-sec'><span class='gd-tag'>Làm người khác có cảm xúc nào đó</span>Làm người khác lo lắng, làm người khác vui… cũng dùng thể sai khiến.</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>(Tôi không muốn làm bố mẹ lo lắng)</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「あ」 cùng hàng, rồi thêm 「せる」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><br>Động từ kết thúc bằng 「う」 thì đổi thành <b>わ</b>: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わせる</span></span><br>Mẹo nhỏ: dùng cùng âm với thể ない. Lấy <span class='gd-jp'>書かない</span> bỏ ない đi, thêm せる, ta được <span class='gd-jp'>書かせる</span>.</div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」 ở cuối, thêm 「させる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きさせる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>（こさせる）</span><br>Những từ như <span class='gd-jp'>勉強する</span>、<span class='gd-jp'>残業する</span> cũng chia giống vậy: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強させる</span></span></div><div class='gd-sec'>Chia xong, nó là một động từ nhóm 2 bình thường, bạn chia tiếp như thường: <span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせない</span>.</div><div class='gd-h'>Người bị sai khiến dùng に hay を</div><div class='gd-sec'>Cấu trúc câu: <b>người sai khiến</b>は　<b>người làm việc</b>に／を　〜させる<br>Cách phán đoán: trước hết xem trong câu <b>có 「を」 nào khác không</b> (ăn cái gì, viết cái gì).</div><div class='gd-sec'><span class='gd-tag'>Có を khác</span>Người làm việc chỉ có thể dùng <b>に</b>. Trong một câu tiếng Nhật, người ta không thích để hai chữ 「を」 xuất hiện.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は生徒に作文を書かせます。</span>(Thầy cô bắt học sinh viết văn)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供に日本語を勉強させています。</span>(Tôi cho con học tiếng Nhật)</div><div class='gd-sec'><span class='gd-tag'>Không có を khác</span>Dùng <b>を</b> hay <b>に</b> đều được. Khi dùng を, cảm giác ép buộc rõ hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生を立たせました。</span>(Thầy cô bắt học sinh đứng lên)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私を残業させます。</span>(Trưởng phòng ngày nào cũng bắt tôi tăng ca)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は毎日私に残業させます。</span>(Trưởng phòng ngày nào cũng bắt tôi tăng ca)</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>させてください</span>“Xin hãy cho tôi ~”: bản thân muốn làm, xin đối phương đồng ý.</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休ませてください。</span>(Xin cho tôi nghỉ một chút)</div><div class='gd-ex-line'>・<span class='gd-jp'>私にやらせてください。</span>(Để tôi làm cho)</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>“Để người khác phải chờ”, cực kỳ hay dùng khi xin lỗi.</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>(Xin lỗi đã để quý khách phải chờ lâu)</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめんね。</span>(Xin lỗi vì để bạn phải chờ nhé)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Động từ kết thúc bằng 「う」 đổi thành <b>わ</b>: là <span class='gd-jp'>買わせる</span>、<span class='gd-jp'>言わせる</span>, không phải 「買あせる」.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span> là nhóm 1: là <span class='gd-jp'>帰らせる</span>, không phải 「帰させる」.<br>・<span class='gd-jp'>来させる</span> đọc là <b>こさせる</b>, không phải きさせる.<br>・Thể sai khiến là cách nói từ trên xuống dưới, <b>không dùng để sai bảo người bề trên</b>. Nếu muốn nói “tôi nhờ thầy giải thích” mà nói <span class='gd-jp'>先生に説明させる</span> thì rất thất lễ, phải nói <span class='gd-jp'>先生に説明してもらう</span> (lịch sự hơn nữa là <span class='gd-jp'>説明していただく</span>).</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>させる vs てもらう</b>: Tiếng Việt cũng phân biệt “bắt bạn chụp ảnh” với “nhờ bạn chụp ảnh giúp”, tiếng Nhật cũng tách bạch như vậy.<br><span class='gd-jp'>友達に写真を撮らせた。</span>(Tôi bắt bạn chụp ảnh: nghe như đang sai bảo người ta)<br><span class='gd-jp'>友達に写真を撮ってもらった。</span>(Tôi nhờ bạn chụp ảnh giúp: bạn giúp mình, có sắc thái biết ơn)</div><div class='gd-sec'><b>させる vs される (bị động)</b>: chỉ khác một chữ mà hướng nghĩa hoàn toàn ngược nhau.<br><span class='gd-jp'>友達を1時間待たせた。</span>(Tôi để bạn phải chờ một tiếng: là lỗi của tôi)<br><span class='gd-jp'>友達に1時間待たされた。</span>(Tôi bị bạn bắt chờ một tiếng: tôi là người chịu thiệt)</div><div class='gd-warn'>Mẹo phán đoán nhanh: thấy 「<b>せ</b>」 là mình bắt người khác làm; thấy 「<b>れ</b>」 là mình bị người khác làm gì đó; còn muốn nhờ người ta giúp thì dùng 「てもらう」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Sai khiến + bị động = bị bắt phải làm (使役受身形): <span class='gd-jp'>母に野菜を食べさせられた。</span>(Tôi bị mẹ bắt ăn rau)<br>Còn có <span class='gd-jp'>〜させていただきます</span> thường nghe trong ngành dịch vụ, cũng bắt nguồn từ thể sai khiến.</div>","n4-61":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể sai khiến bị động (使役受身形) giống với <b>“bị bắt phải ~”, “bị bắt đi ~”</b> trong tiếng Việt. Điểm mấu chốt: <b>hành động do chính bạn làm, nhưng bạn không muốn làm</b>, là do người khác ép. Ví dụ “hồi nhỏ bị mẹ bắt ăn ớt chuông”: người ăn là bạn, người ép là mẹ, và giọng nói có chút than phiền.</div><div class='gd-h'>Nó từ đâu ra</div><div class='gd-sec'>Tên nghe dài, nhưng thật ra là hai thứ chồng lên nhau: <b>sai khiến</b> (bắt người khác làm gì đó) + <b>bị động</b> (bị ~).<br>Trước hết xem từ góc nhìn của mẹ:</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私にピーマンを食べさせた。</span>(Mẹ bắt tôi ăn ớt chuông)</div><div class='gd-sec'>Chuyển sang nói từ góc nhìn của “tôi”, ta được thể sai khiến bị động:</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母にピーマンを食べさせられた。</span>(Tôi bị mẹ bắt ăn ớt chuông)</div><div class='gd-sec'>Người bị ép (tôi) dùng <span class='gd-jp'>は</span> hoặc <span class='gd-jp'>が</span>, người ép bạn dùng <b><span class='gd-jp'>に</span></b>.</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」, thêm 「させられる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させられる</span></span></div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「あ」 cùng hàng, rồi thêm 「される」. Đây là dạng người Nhật dùng nhiều nhất.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành か → <span class='gd-jp'>行かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → đổi う thành わ → <span class='gd-jp'>買わされる</span></span><br>Thêm 「せられる」 cũng đúng (<span class='gd-jp'>行かせられる</span>), chỉ là dài hơn và ít nghe hơn.</div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>（こさせられる）</span></div><div class='gd-sec'>Cách nói lịch sự: đổi る ở cuối thành ます: <span class='gd-pair'><span class='gd-jp'>待たされる</span> → <span class='gd-jp'>待たされます</span></span></div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で30分も待たされた。</span>(Bị bắt chờ tới 30 phút ở nhà ga)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長にお酒を飲まされました。</span>(Bị trưởng phòng ép uống rượu)</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃、毎日ピアノを練習させられた。</span>(Hồi nhỏ ngày nào cũng bị ép tập đàn piano)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Động từ nhóm 1 kết thúc bằng 「す」 <b>không được</b> dùng される: <span class='gd-jp'>話す</span> phải chia thành <span class='gd-jp'>話させられる</span>, không phải 話さされる.<br>・Động từ kết thúc bằng 「う」 thì đổi thành 「わ」 chứ không phải 「あ」: <span class='gd-jp'>買わされる</span>, không phải 買あされる.<br>・Thể sai khiến bị động của <span class='gd-jp'>来る</span> đọc là <b>こさせられる</b>, không phải きさせられる.<br>・<span class='gd-jp'>食べさせる</span> là “bắt người khác ăn”, còn <span class='gd-jp'>食べさせられる</span> là “bản thân bị ép ăn”. Thiếu 「られる」 là nghĩa đảo ngược hoàn toàn.<br>・Nó mang cảm giác “không tình nguyện”, nên đừng dùng cho chuyện vui. Khi đàn anh mời bạn đi ăn, phải nói <span class='gd-jp'>先輩におごってもらった</span>; nếu nói <span class='gd-jp'>先輩におごらされた</span> thì nghĩa thành “bị đàn anh ép phải mời”.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Thể bị động</b> = hành động do <b>đối phương</b> làm, bạn là người bị tác động: <span class='gd-jp'>先生に叱られた。</span>(Bị thầy cô mắng: người mắng là thầy cô)<br><b>Thể sai khiến bị động</b> = hành động do <b>chính bạn</b> làm, chỉ là bị ép: <span class='gd-jp'>先生に立たされた。</span>(Bị thầy cô phạt đứng: người đứng là tôi)<br><b>てもらう</b> = đối phương làm giúp bạn, bạn biết ơn: <span class='gd-jp'>先生に作文を直してもらった。</span>(Thầy cô sửa bài văn giúp tôi)</div><div class='gd-warn'>Mẹo phán đoán nhanh: tự hỏi “Ai đang làm hành động này?”. Đối phương làm lên người bạn là bị động; chính bạn làm một cách không tự nguyện là sai khiến bị động; đối phương giúp bạn và bạn biết ơn thì dùng てもらう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói lịch sự “xin cho phép tôi ~”, dùng thể て của thể sai khiến rồi thêm <span class='gd-jp'>いただきます</span> (<span class='gd-jp'>〜させていただきます</span>): <span class='gd-jp'>発表する</span> → <span class='gd-jp'>発表させる</span> → <span class='gd-jp'>発表させていただきます。</span>(Xin phép cho tôi được trình bày)</div>","n4-62":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Kính ngữ (尊敬語) dùng khi nói về <b>việc mà đối phương, bề trên hay cấp trên đang làm</b>: bạn đổi động từ sang cách nói trang trọng hơn. Giống tiếng Việt, thay vì nói「bạn ăn cơm chưa」thì nói「mời quý khách dùng bữa」, thay vì「thầy đến rồi」thì nói「thầy đã quang lâm」: hành động vẫn vậy, chỉ là cách dùng từ kính trọng hơn.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Người thực hiện hành động là người bạn cần tôn trọng như thầy cô, sếp, khách hàng, người lớn tuổi. Nói trực tiếp với họ hay nhắc đến họ trước mặt người khác đều dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はもうお帰りになりました。</span>（Thầy đã về rồi ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は何をなさいますか。</span>（Cuối tuần này anh/chị định làm gì ạ?）</div><div class='gd-h'>Cách biến đổi: nghĩ theo hai bước</div><div class='gd-sec'><b>Bước 1: xem động từ đó có \"dạng kính ngữ riêng\" không</b><br>Những động từ rất hay dùng có dạng kính ngữ riêng. Nếu có thì thường ưu tiên dùng dạng đó:<br><span class='gd-pair'><span class='gd-jp'>いる・行く・来る</span> → <span class='gd-jp'>いらっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>おっしゃる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む</span> → <span class='gd-jp'>召し上がる</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>ご覧になる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>なさる</span></span><br><span class='gd-pair'><span class='gd-jp'>くれる</span> → <span class='gd-jp'>くださる</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>ご存じだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>社長は明日大阪へいらっしゃいます。</span>（Ngày mai giám đốc sẽ đi Osaka）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、もうご覧になりましたか。</span>（Cuốn sách này anh/chị xem rồi ạ?）</div><div class='gd-sec'><b>Bước 2: không có dạng riêng thì áp công thức「お＋ます形＋になる」</b><br>Đổi động từ sang ます形, bỏ ます, thêm お ở trước và になる ở sau.<br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span> → bỏ ます → <span class='gd-jp'>お待ちになる</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>お帰りになる</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>お書きになる</span></span><br>Với động từ dạng「từ Hán + する」thì thường dùng ご：<span class='gd-pair'><span class='gd-jp'>利用する</span> → <span class='gd-jp'>ご利用になる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部長は何時にお戻りになりますか。</span>（Mấy giờ trưởng phòng quay lại ạ?）</div><div class='gd-sec'>Những động từ như <b>見る・言う・する・いる・来る</b> bắt buộc dùng dạng riêng, không được cứng nhắc áp công thức. Còn một số ít động từ như <span class='gd-jp'>飲む</span> thì cả hai cách đều đúng: <span class='gd-jp'>何を召し上がりますか。</span>、<span class='gd-jp'>何をお飲みになりますか。</span>（Anh/chị dùng gì ạ?）đều rất tự nhiên.</div><div class='gd-sec'>Ngoài ra còn một kiểu kính ngữ nhẹ hơn là「れる・られる」（ví dụ: <span class='gd-jp'>社長が帰られました</span>）, sẽ được giảng riêng ở n4-74.</div><div class='gd-h'>Những câu bạn nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Trong cửa hàng</span><span class='gd-jp'>いらっしゃいませ。</span>（Xin chào quý khách）thực ra chính là biến từ いらっしゃる mà ra.<br><span class='gd-tag'>Xin mời anh/chị～</span>お＋ます形＋ください：<span class='gd-jp'>少々お待ちください。</span>（Xin quý khách vui lòng chờ một chút）<br><span class='gd-tag'>Hỏi đối phương có biết không</span><span class='gd-jp'>このお店、ご存じですか。</span>（Anh/chị có biết quán này không ạ?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Kính ngữ <b>tuyệt đối không dùng cho bản thân</b>. Muốn nói \"ngày mai tôi sẽ đi\" thì không được nói <span class='gd-jp'>私がいらっしゃいます</span>, mà phải dùng cách nói thường hoặc khiêm nhường ngữ: <span class='gd-jp'>私が参ります</span>。<br>・Các động từ sau không áp công thức một cách máy móc: không nói お見になる、お言いになる、おしになる, mà phải nói <span class='gd-jp'>ご覧になる</span>、<span class='gd-jp'>おっしゃる</span>、<span class='gd-jp'>なさる</span>。<br>・ます形 rất dễ viết sai: đúng là <span class='gd-jp'>いらっしゃいます</span>、<span class='gd-jp'>おっしゃいます</span>、<span class='gd-jp'>なさいます</span>、<span class='gd-jp'>くださいます</span>, chứ không phải いらっしゃります、おっしゃります。<br>・Khi nói với khách bên ngoài về cấp trên của công ty mình, không dùng kính ngữ mà phải hạ người của công ty mình xuống. Ví dụ khách gọi điện tìm trưởng phòng thì trả lời <span class='gd-jp'>田中は今おりません。</span>, không nói「部長はいらっしゃいません」。</div><div class='gd-h'>Phân biệt với dạng dễ nhầm</div><div class='gd-sec'>Khiêm nhường ngữ (n4-63) cũng là kính ngữ, nhưng hướng ngược lại: kính ngữ <b>nâng đối phương lên</b>, còn khiêm nhường ngữ <b>hạ bản thân xuống</b>. Hãy xem trong cùng một đoạn hội thoại:<br><span class='gd-jp'>A：この資料、ご覧になりましたか。</span>（Tài liệu này anh/chị xem rồi ạ?: đối phương xem, dùng kính ngữ）<br><span class='gd-jp'>B：はい、拝見しました。</span>（Vâng, tôi đã xem rồi ạ: mình xem, dùng khiêm nhường ngữ）<br><span class='gd-jp'>A：何を召し上がりますか。</span>（Anh/chị dùng gì ạ?）<br><span class='gd-jp'>B：じゃ、ケーキをいただきます。</span>（Vậy tôi xin phép dùng bánh ngọt ạ）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: trước hết xem <b>ai là người làm hành động</b>. Đối phương hoặc bề trên/cấp trên làm → kính ngữ; chính mình (hoặc người phía mình) làm → khiêm nhường ngữ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp khiêm nhường ngữ (n4-63), nhớ cả hai cùng lúc sẽ ít bị lẫn nhất; sau đó xem cách dùng kính ngữ của「れる・られる」(n4-74).</div>","n4-63":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Khiêm nhường ngữ (謙譲語) là <b>nói hành động của mình thấp xuống một chút, nhờ vậy đối phương tự nhiên được nâng lên</b>. Tiếng Việt cũng có kiểu này: nói \"em xin phép\", \"con xin được\", \"xin được đọc bài của thầy\", \"xin được đến thăm nhà\". Khiêm nhường ngữ tiếng Nhật cũng là ý tưởng đó, chỉ là dùng nhiều hơn tiếng Việt rất nhiều.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'>Dùng khi nói về <b>việc mình sẽ làm</b> với những người cần tôn trọng như khách hàng, thầy cô, cấp trên. Đi làm thêm, đi làm, viết thư cho thầy cô, gần như ngày nào bạn cũng gặp.</div><div class='gd-h'>Cách 1: お＋động từ＋します</div><div class='gd-sec'>Bỏ「ます」của ます形, thêm「お」ở trước và「します」ở sau.<br><span class='gd-pair'><span class='gd-jp'>持ちます</span> → bỏ ます → <span class='gd-jp'>お持ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>待ちます</span> → <span class='gd-jp'>お待ちします</span></span><br><span class='gd-pair'><span class='gd-jp'>送ります</span> → <span class='gd-jp'>お送りします</span></span><br>Những từ Hán như「案内」「連絡」thì thường thêm「ご」ở trước:<br><span class='gd-pair'><span class='gd-jp'>案内します</span> → <span class='gd-jp'>ご案内します</span></span><br><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>ご連絡します</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、お持ちします。</span>（Để tôi xách hành lý giúp anh/chị ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までお送りします。</span>（Tôi xin tiễn anh/chị đến ga ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>あとでご連絡します。</span>（Lát nữa tôi sẽ liên lạc với anh/chị ạ）</div><div class='gd-sec'>Cách này chỉ dùng cho hành động <b>làm cho đối phương hoặc có liên quan đến đối phương</b>. Mình tự ăn cơm, tự đi ngủ thì không liên quan đến đối phương, nên không áp công thức này được.</div><div class='gd-h'>Cách 2: đổi hẳn sang động từ đặc biệt</div><div class='gd-sec'>Một số động từ hay dùng có dạng khiêm nhường riêng, <b>thay hẳn cả từ</b>, không dùng お～します. Ở N4, bạn học thuộc mấy từ này trước:<br><span class='gd-pair'><span class='gd-jp'>行く・来る</span> → <span class='gd-jp'>参ります</span></span><br><span class='gd-pair'><span class='gd-jp'>いる</span> → <span class='gd-jp'>おります</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>申します</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>いたします</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる・飲む・もらう</span> → <span class='gd-jp'>いただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>拝見します</span></span><br><span class='gd-pair'>hỏi, đến chỗ đối phương thăm hỏi → <span class='gd-jp'>伺います</span></span><br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>存じております</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>お目にかかります</span></span><br>Câu「いただきます」nói trước bữa ăn thực ra chính là いただく khiêm nhường này.</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と申します。</span>（Rất hân hạnh được gặp, tôi họ Lâm ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>資料、拝見しました。</span>（Tôi đã xem tài liệu rồi ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>では、お先に失礼いたします。</span>（Vậy tôi xin phép về trước ạ）</div><div class='gd-sec'>Khi nói với người ngoài về hành động của <b>người nhà mình</b> cũng dùng khiêm nhường ngữ, vì người nhà được tính là \"phía mình\".</div><div class='gd-ex-line'>・<span class='gd-jp'>父は今、出かけております。</span>（Bố tôi bây giờ đang ra ngoài ạ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khiêm nhường ngữ chỉ dùng cho <b>bản thân (và phía mình)</b>. Mời thầy cô ăn mà nói <span class='gd-jp'>いただいてください</span> là sai, phải nói <span class='gd-jp'>召し上がってください</span>; hỏi thầy có đi không thì không được nói <span class='gd-jp'>先生も参りますか</span>, phải nói <span class='gd-jp'>先生もいらっしゃいますか</span>。<br>・Động từ nào có dạng riêng thì dùng dạng riêng: không nói お見します mà nói <span class='gd-jp'>拝見します</span>; không nói お行きします mà nói <span class='gd-jp'>参ります</span> hoặc <span class='gd-jp'>伺います</span>。<br>・<span class='gd-jp'>お待ちします</span> là \"tôi đợi anh/chị\", còn <span class='gd-jp'>お待ちください</span> là \"xin anh/chị chờ\", chủ thể khác nhau. Nhân viên nói <span class='gd-jp'>少々お待ちください</span> là nhờ bạn chờ, còn nói <span class='gd-jp'>お待ちしております</span> là họ đang đợi bạn.<br>・<span class='gd-jp'>参ります</span> chỉ là nói \"đi, đến\" một cách lịch sự; còn <span class='gd-jp'>伺います</span> là \"đến chỗ đối phương\". <span class='gd-jp'>来週、大阪へ参ります。</span>（Tuần sau tôi sẽ đi Osaka）／<span class='gd-jp'>明日、先生のお宅に伺います。</span>（Ngày mai tôi sẽ đến thăm nhà thầy）</div><div class='gd-h'>Phân biệt với dạng dễ nhầm</div><div class='gd-sec'>Dễ lẫn nhất là với <b>kính ngữ (尊敬語)</b>. Cùng một việc, nếu chủ thể là đối phương thì dùng kính ngữ (nâng đối phương lên), nếu chủ thể là mình thì dùng khiêm nhường ngữ (hạ mình xuống).</div><div class='gd-ex-line'>・<span class='gd-jp'>先生も召し上がりますか。</span>（Thầy cũng dùng ạ?: đối phương ăn, kính ngữ）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、私もいただきます。</span>（Vâng, em cũng xin phép dùng ạ: mình ăn, khiêm nhường ngữ）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生、傘をお持ちになりましたか。</span>（Thầy ơi, thầy có mang ô không ạ?: đối phương mang）</div><div class='gd-ex-line'>・<span class='gd-jp'>傘、お持ちします。</span>（Để em cầm ô giúp thầy ạ: mình cầm）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: trước hết hỏi \"hành động này do ai làm?\" Đối phương làm → kính ngữ (お～になる、いらっしゃる、召し上がる); mình làm → khiêm nhường ngữ (お～します、参ります、いただきます)。</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp「〜させていただきます」, cách nói rất khiêm tốn khi muốn nói \"tôi xin phép làm ～\" (nghĩa đen là \"nhờ ơn anh/chị cho phép tôi làm ～\"), ví dụ <span class='gd-jp'>本日は休ませていただきます。</span>（Hôm nay xin phép cho tôi được nghỉ ạ）Đi làm thêm, đi làm, ngày nào bạn cũng nghe thấy.</div>","n4-7":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ので」nghĩa là <b>「vì ～ nên ～」</b>, giống「から」, đều dùng để nêu lý do. Điểm khác là「ので」nghe <b>lịch sự hơn, như đang giải thích tình hình</b>. Trong tiếng Việt, kiểu \"vì… nên…\" nói thẳng thì giống から hơn, còn \"do… nên…\" nghe trang trọng, mềm mỏng hơn thì giống ので. Khi nói lý do với thầy cô, cấp trên hay khách hàng, dùng ので là an toàn nhất.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nêu lý do một cách lịch sự</span>Hay dùng nhất khi đi làm, đi học, hoặc nói chuyện với người chưa thân.</div><div class='gd-ex-line'>・<span class='gd-jp'>用事があるので、お先に失礼します。</span>(Vì có việc bận nên tôi xin phép về trước)</div><div class='gd-ex-line'>・<span class='gd-jp'>道が混んでいたので、遅れました。</span>(Vì đường đang kẹt xe nên tôi đến trễ)</div><div class='gd-sec'><span class='gd-tag'>Nhờ vả người khác</span>Nói lý do trước rồi mới nhờ giúp, nghe rất lịch sự.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いので、窓を閉めてください。</span>(Vì trời lạnh nên làm ơn đóng cửa sổ lại)</div><div class='gd-sec'><span class='gd-tag'>Từ chối khéo</span>Người Nhật thường chỉ nói lý do rồi bỏ lửng câu, đối phương nghe là hiểu ngay.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はちょっと用事があるので…。</span>(Ngày mai mình hơi bận chút việc nên…)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くので</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったので</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いので</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: ở giữa phải thêm「な」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなので</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨なので</span></span><br>Khi nói về chuyện trong quá khứ thì dùng「だった」: <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だったので</span></span></div><div class='gd-sec'>Muốn trang trọng hơn nữa, bạn có thể nối sau ます、です. Cách này nghe rất nhiều ở cửa hàng và nơi làm việc:<br><span class='gd-jp'>雨が降っていますので、お気をつけください。</span>(Vì trời đang mưa nên xin hãy cẩn thận)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ và tính từ な không được thêm だ trực tiếp: <span class='gd-jp'>雨だので</span> là sai, phải nói <span class='gd-jp'>雨なので</span>.<br>・Tính từ い thì ngược lại, <b>không thêm な</b>: đúng là <span class='gd-jp'>痛いので</span>, không phải 痛いなので.<br>・Khi trả lời câu hỏi \"Tại sao?\", cuối câu có thể nói <span class='gd-jp'>電車が遅れたからです</span>, nhưng <b>không thể</b> nói 遅れたのでです.<br>・ので không hợp với mệnh lệnh gay gắt. Câu như 「うるさいので、黙れ」nghe rất kỳ, những trường hợp này phải dùng から.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'><b>から vs ので</b>: cùng là xin nghỉ vì bị sốt.<br><span class='gd-jp'>熱があるから、休む。</span>(Mình bị sốt nên nghỉ: nói với bạn bè, khá thẳng)<br><span class='gd-jp'>熱があるので、休ませてください。</span>(Vì bị sốt nên xin cho tôi nghỉ: nói với cấp trên, lịch sự hơn)<br>Khi quát mắng hay cảnh báo thì chỉ dùng được から: <span class='gd-jp'>危ないから、触るな！</span>(Nguy hiểm đấy, đừng sờ vào!)</div><div class='gd-sec'><b>ので vs のに</b>: chỉ khác một chữ nhưng nghĩa khác xa.<br><span class='gd-jp'>薬を飲んだので、治った。</span>(Vì đã uống thuốc nên khỏi bệnh)<br><span class='gd-jp'>薬を飲んだのに、治らない。</span>(Rõ ràng đã uống thuốc rồi mà vẫn chưa khỏi)</div><div class='gd-warn'>Mẹo nhỏ để chọn: nêu lý do, muốn nói lịch sự thì dùng ので; muốn nhấn mạnh, nói mạnh hay ra lệnh thì dùng から; còn \"rõ ràng… mà lại…\" là のに.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi có nhiều lý do, bạn có thể dùng「し」để liệt kê từng cái một: <span class='gd-jp'>雨も降っているし、寒いし、今日は出かけない。</span>(Vừa mưa vừa lạnh, hôm nay mình không ra ngoài nữa)</div>","n4-5":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜やすい」nghĩa là <b>\"dễ ～\"</b>, còn「〜にくい」nghĩa là <b>\"khó ～\"</b>. Cây bút này viết dễ, cái tên này khó nhớ, tiếng Nhật đều dùng hai mẫu này để nói.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chuyển động từ sang thể ます, bỏ「ます」đi, rồi thêm やすい hoặc にくい.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書きます</span> → bỏ ます → <span class='gd-jp'>書きやすい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べにくい</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話しやすい</span></span><span class='gd-pair'><span class='gd-jp'>覚える</span> → <span class='gd-jp'>覚えにくい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しやすい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来やすい</span>（きやすい）</span></div><div class='gd-sec'>Nối xong, cả cụm từ được <b>dùng như một tính từ い</b>, chia giống như「おいしい」:<br><span class='gd-pair'><span class='gd-jp'>書きやすい</span> → <span class='gd-jp'>書きやすかった</span></span>(hồi đó thấy dễ viết)<br><span class='gd-pair'><span class='gd-jp'>わかりやすい</span> → <span class='gd-jp'>わかりやすくて</span></span>(dễ hiểu, mà còn…)<br>Bạn cũng có thể đặt thẳng trước danh từ: <span class='gd-jp'>使いやすいアプリ</span>(app dễ dùng)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm thấy nhẹ nhàng / vất vả</span>Khi người ta làm việc đó thì có thuận tay hay không.</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は軽くて歩きやすいです。</span>(Đôi giày này nhẹ, đi rất dễ chịu)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の説明はわかりやすいです。</span>(Cách giải thích của thầy/cô rất dễ hiểu)</div><div class='gd-ex-line'>・<span class='gd-jp'>この魚は骨が多くて食べにくいです。</span>(Con cá này nhiều xương, ăn rất khó)</div><div class='gd-sec'><span class='gd-tag'>Dễ / khó xảy ra</span>Không phải do người ta cố ý làm, mà là đồ vật hay con người <b>vốn dễ trở nên như vậy</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>白い服は汚れやすいです。</span>(Quần áo màu trắng rất dễ bẩn)</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきやすいです。</span>(Mùa đông dễ bị cảm)</div><div class='gd-ex-line'>・<span class='gd-jp'>このコップは割れにくいです。</span>(Cái cốc này khó vỡ)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với <b>thể ます bỏ ます</b>, không phải thể từ điển: đúng là <span class='gd-jp'>書きやすい</span>, không phải 書くやすい.<br>・<span class='gd-jp'>食べやすい</span> không có nghĩa là \"ngon\"! Nó nghĩa là \"dễ ăn, ăn tiện\". Muốn nói ngon thì dùng <span class='gd-jp'>おいしい</span>. Tương tự, <span class='gd-jp'>食べにくい</span> là \"khó ăn, ăn rắc rối\", không phải \"dở\" (dở là <span class='gd-jp'>まずい</span>).<br>・Muốn nói \"khó viết\", người Nhật thường nói thẳng <span class='gd-jp'>書きにくい</span>, tự nhiên hơn <span class='gd-jp'>書きやすくない</span>.<br>・<span class='gd-jp'>割れやすい</span> là \"dễ vỡ\", nói về tính chất của đồ vật, không phải \"dễ đập vỡ\".</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'>「〜そうです」(trông có vẻ sắp ～) cũng nối với thể ます bỏ ます nên rất dễ lẫn với やすい:<br><b>割れそう</b> = nhìn bề ngoài rồi <b>đoán ngay lúc đó</b> là nó sẽ vỡ: <span class='gd-jp'>このお皿、薄くて割れそう。</span>(Cái đĩa này mỏng quá, trông như sắp vỡ)<br><b>割れやすい</b> = vốn biết nó <b>dễ vỡ</b>, đó là đặc tính của nó: <span class='gd-jp'>このお皿は割れやすいから、気をつけて。</span>(Cái đĩa này dễ vỡ lắm, cẩn thận nhé)</div><div class='gd-warn'>Mẹo nhỏ để chọn: \"trông có vẻ sắp ～\" thì dùng そう; \"vốn dễ ～, làm thì dễ ～\" thì dùng やすい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là \"thể ます bỏ ます\" rồi thêm từ khác, còn có <span class='gd-jp'>食べすぎる</span>(ăn quá nhiều) và <span class='gd-jp'>書き方</span>(cách viết). Học cách nối này một lần là dùng được cho cả mấy mẫu đó.</div>","n4-10":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たことがあります」tương đương với <b>「đã từng ～」</b> trong tiếng Việt, dùng để nói <b>bạn có kinh nghiệm này hay không</b> trong đời. 「Tôi đã từng đến Nhật」là <span class='gd-jp'>日本へ行ったことがあります。</span>, còn 「Tôi chưa từng ăn rau mùi」là <span class='gd-jp'>パクチーを食べたことがありません。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước tiên chuyển động từ sang <b>thể た</b> (thể quá khứ thông thường, dạng 「đã ăn」「đã đi」), rồi nối <span class='gd-jp'>ことがあります</span> ở phía sau.<br>Cách chia thể た giống hệt thể て, chỉ cần đổi て thành た, で thành だ:<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗った</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」rồi thêm た. <span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><br><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span><br>Sau đó ghép cả cụm lại: <span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたことがあります</span></span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Đã từng</span>Kể về kinh nghiệm của mình. Phía trước có thể thêm số lần.</div><div class='gd-ex-line'>・<span class='gd-jp'>着物を着たことがあります。</span>（Tôi đã từng mặc kimono）</div><div class='gd-ex-line'>・<span class='gd-jp'>大阪には二回行ったことがあります。</span>（Osaka thì tôi đã đến hai lần rồi）</div><div class='gd-sec'><span class='gd-tag'>Chưa từng</span>Đổi あります thành <b>ありません</b>. Thêm「一度も」sẽ thành「chưa một lần nào」.</div><div class='gd-ex-line'>・<span class='gd-jp'>一度も雪を見たことがありません。</span>（Tôi chưa một lần nào được thấy tuyết）</div><div class='gd-sec'><span class='gd-tag'>Hỏi người khác</span>Thêm か ở cuối câu. Khi trả lời không cần nhắc lại cả câu, chỉ cần nói あります／ありません là đủ.</div><div class='gd-ex-line'>・<span class='gd-jp'>馬に乗ったことがありますか。</span>（Bạn đã từng cưỡi ngựa chưa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>／<span class='gd-jp'>いいえ、ありません。</span>（Rồi／Chưa）</div><div class='gd-sec'><span class='gd-tag'>Kiểu nói với bạn bè</span>Nói với bạn bè thì dùng <span class='gd-jp'>ことがある</span>／<span class='gd-jp'>ことがない</span>, và khi nói chuyện thường bỏ luôn が.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山、登ったことある？</span>（Bạn đã từng leo núi Phú Sĩ chưa?）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Mẫu này nói về việc「trong đời có kinh nghiệm này hay không」, nên <b>không dùng cho chuyện vừa mới xảy ra như lúc nãy hay hôm qua</b>: <span class='gd-jp'>さっき食べたことがある</span> là sai, phải nói thẳng <span class='gd-jp'>さっき食べた</span>. Còn những mốc thời gian xa và rộng như「hồi nhỏ」thì dùng được: <span class='gd-jp'>子どものころ、日本に住んだことがあります。</span>（Hồi nhỏ tôi đã từng sống ở Nhật）<br>・<b>Đừng dùng cho việc ai cũng chắc chắn đã làm</b>: nếu nói「tôi đã ăn cơm rồi」thành <span class='gd-jp'>ご飯を食べたことがあります</span>, người Nhật sẽ thấy rất lạ, như thể ăn cơm là một trải nghiệm hiếm có vậy.<br>・「Chưa từng làm」là <span class='gd-jp'>食べたことがありません</span>, không phải <span class='gd-jp'>食べなかったことがあります</span>, vì câu sau nghĩa là「đã từng có một lần không ăn」.<br>・Phía trước nhất định phải là <b>thể た</b>. Nếu đổi sang thể từ điển thì nghĩa đổi hẳn, xem phần dưới.<br>・Chữ 来 trong <span class='gd-jp'>来たことがあります</span> đọc là <b>き</b>, không phải く hay こ.</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'><b>Thể た＋ことがあります</b>＝đã từng ～ (kinh nghiệm)<br><span class='gd-jp'>納豆を食べたことがあります。</span>（Tôi đã từng ăn natto）<br><b>Thể từ điển＋ことがあります</b>＝thỉnh thoảng có ～ (đôi khi xảy ra)<br><span class='gd-jp'>納豆を食べることがあります。</span>（Thỉnh thoảng tôi có ăn natto）</div><div class='gd-sec'>Ngoài ra, tiếng Việt có kiểu hỏi「đã ～ chưa?」nghĩa là hỏi việc đã xong hay chưa. Trường hợp này tiếng Nhật <b>không dùng</b> ことがある:<br><span class='gd-jp'>もう食べましたか。</span>（Bạn ăn chưa? ＝ đã ăn rồi chứ?）<br><span class='gd-jp'>食べたことがありますか。</span>（Bạn đã từng ăn chưa? ＝ có kinh nghiệm này không）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu nói được「đã từng ～ chưa」thì dùng たことがある; nếu nghĩa là「đã ～ xong chưa」thì dùng <span class='gd-jp'>もう〜ました</span>; còn nếu phía trước là thể từ điển thì nghĩa là「thỉnh thoảng có」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Dùng chung với「〜てみたい」(muốn thử xem), rất tiện khi tự giới thiệu hay trò chuyện:<br><span class='gd-jp'>温泉に入ったことがないので、一度入ってみたいです。</span>（Tôi chưa từng tắm onsen, nên muốn thử đi tắm một lần xem sao）</div>","n4-45":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜んです」gần giống với <b>「là vì ～ đó」「thật ra là thế này ～」「có chuyện gì à?」</b> trong tiếng Việt. Ý của câu không đổi, chỉ có thêm một sắc thái: <b>tôi đang giải thích bối cảnh cho bạn</b>, hoặc <b>tôi thấy một tình huống và muốn biết chuyện gì đang xảy ra</b>. Người Nhật dùng rất thường xuyên, khi nói chuyện hầu như đều dùng「んです」, còn「のです」là dạng dùng trong văn viết hoặc diễn thuyết.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Giải thích lý do</span>Khi người khác hỏi tại sao, hoặc khi bạn thấy nên nói rõ nguyên nhân.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして昨日休んだんですか。</span>（Sao hôm qua bạn nghỉ vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったんです。</span>（Vì tôi bị sốt đó ạ）</div><div class='gd-sec'><span class='gd-tag'>Thấy tình huống nên muốn hỏi</span>Thấy một tình huống ngay trước mắt và muốn biết đằng sau là chuyện gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうしたんですか。</span>（Có chuyện gì vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っているんですか。</span>（Bên ngoài đang mưa à? Khi thấy người kia bước vào với cây dù ướt）</div><div class='gd-sec'><span class='gd-tag'>Dẫn dắt trước khi nói</span>Dùng「〜んですが」「〜んですけど」để nêu tình huống trước, rồi mới nhờ vả hoặc hỏi. Đây là cách mở lời rất tự nhiên của người Nhật.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですが…。</span>（Xin lỗi, tôi muốn đến nhà ga ạ…）</div><div class='gd-sec'><span class='gd-tag'>Báo tin, nói cảm xúc</span>Chủ động báo cho đối phương một chuyện, hoặc nhấn mạnh cảm xúc của mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>実は来月結婚するんです。</span>（Thật ra tháng sau tôi sẽ kết hôn đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>本当に困っているんです。</span>（Tôi thật sự đang rất khó xử đó）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: thêm んです thẳng vào thể thông thường (cách nói không có ます, です).<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くんです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないんです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったんです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いんです</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: khi ở dạng khẳng định hiện tại, ở giữa phải thêm <b>な</b>.<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなんです</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なんです</span></span><br>Với quá khứ hoặc phủ định thì nối theo thể thông thường, không thêm な: <span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったんです</span></span><span class='gd-pair'><span class='gd-jp'>好きじゃない</span> → <span class='gd-jp'>好きじゃないんです</span></span></div><div class='gd-sec'>Khi nói với bạn bè, câu giải thích dùng「〜んだ」hoặc「〜の」, câu hỏi dùng「〜の？」: <span class='gd-jp'>どうしたの？</span>（Sao thế?）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Quên thêm な với tính từ な và danh từ: không phải 学生んです, cũng không phải 学生だんです, mà là <span class='gd-jp'>学生なんです</span>.<br>・Không được nối sau ます hay です: không phải 行きますんです、高いですんです, mà là <span class='gd-jp'>行くんです</span>、<span class='gd-jp'>高いんです</span>.<br>・Đừng thêm vào mọi câu. Nói sự thật đơn thuần thì dùng ます là đủ, câu nào cũng んです thì nghe như bạn cứ giải thích và biện minh mãi.<br>・Khi hỏi「〜んですか」về hành động của người khác, nếu giọng điệu và hoàn cảnh không hợp thì có thể nghe như đang truy hỏi, chất vấn. Ví dụ <span class='gd-jp'>何をしているんですか</span> mà nói giọng gắt thì thành「Bạn đang làm cái gì đấy!」; <span class='gd-jp'>どうして遅れたんですか</span> cũng có thể nghe như đang quở trách. Khi hỏi người lớn tuổi hơn thì nên nói nhẹ nhàng, có thể mở đầu bằng <span class='gd-jp'>あのう</span>.</div><div class='gd-h'>Phân biệt với mẫu trông rất giống</div><div class='gd-sec'>Cùng một tình huống: lịch trình ngày mai của đồng nghiệp.<br><b>〜ますか</b>＝hỏi đơn thuần, chưa có manh mối nào:<br><span class='gd-jp'>明日、どこかへ行きますか。</span>（Ngày mai bạn có đi đâu không?）<br><b>〜んですか</b>＝thấy đồng nghiệp kéo vali, muốn biết chuyện gì đang xảy ra:<br><span class='gd-jp'>どこかへ行くんですか。</span>（Bạn sắp đi đâu à?）<br>Khi trả lời cũng vậy, muốn giải thích lý do thì dùng んです: <span class='gd-jp'>大阪に出張なんです。</span>（Tôi đi công tác ở Osaka ạ）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu bạn đã thấy điều gì đó và muốn biết lý do đằng sau thì dùng んですか; nếu chỉ hỏi một việc đơn thuần thì dùng ますか.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Sau「〜んですが」nối cách nói nhờ vả thì sẽ thành một lời đề nghị rất lịch sự: <span class='gd-jp'>日本語がよくわからないんですが、ゆっくり話していただけませんか。</span>（Tiếng Nhật của tôi chưa tốt lắm, anh/chị có thể nói chậm lại một chút được không ạ?）</div>","n4-47":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cả hai đều nói về 「quyết định」, khác nhau ở chỗ <b>ai là người chốt</b>.<br><b>ことにする</b>＝「Tôi quyết định là ～」, tự mình làm chủ.<br><b>ことになる</b>＝「Kết quả là sẽ ～」, có thể do công ty hay trường học sắp xếp, cũng có thể là sự việc tự diễn biến thành như vậy. Giống như trong tiếng Việt, 「Tôi quyết định chuyển nhà」 khác với 「Tôi bị điều vào Đà Nẵng rồi」.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Việc sẽ làm: thể từ điển＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くことにする</span></span><br>Việc sẽ không làm: thể ない＋ことにする／ことになる<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないことにする</span></span><br>Quyết định thường là đã chốt xong rồi, nên hay dùng nhất là thì quá khứ: <b>ことにした</b>、<b>ことになった</b>.</div><div class='gd-h'>Bốn dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>Quyết định bạn vừa tự đưa ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本に留学することにしました。</span>（Tôi quyết định sang Nhật du học vào năm sau）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はどこにも行かないことにした。</span>（Tôi quyết định hôm nay sẽ không đi đâu cả）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>Người khác quyết định, hoặc sự việc tự diễn biến thành như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになりました。</span>（Từ tháng sau tôi sẽ được điều chuyển đến Osaka）</div><div class='gd-ex-line'>・<span class='gd-jp'>6月に結婚することになりました。</span>（Tháng 6 tôi sẽ kết hôn）</div><div class='gd-sec'>Kết hôn rõ ràng là do mình quyết định, sao lại dùng なる? Vì dùng なる nghe như 「mọi chuyện đã đi đến bước này」, nên <b>khiêm tốn, lịch sự</b> hơn. Người Nhật rất hay nói vậy khi báo với đồng nghiệp hay cấp trên.</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>Quy tắc bạn tự đặt cho mình và vẫn luôn giữ.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（Tôi tự đặt quy tắc là trước khi ngủ không xem điện thoại）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>Quy định hay thông lệ của tập thể, không phải do bạn tự đặt.</div><div class='gd-ex-line'>・<span class='gd-jp'>この寮では、10時までに帰ることになっている。</span>（Ở ký túc xá này có quy định phải về trước 10 giờ）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ thì nối thẳng にする, không cần thêm こと: khi gọi món nói <span class='gd-jp'>コーヒーにします</span>（Tôi lấy cà phê）; còn động từ thì phải thêm こと rồi mới nối にする: <span class='gd-jp'>コーヒーをやめることにします</span>（Tôi quyết định bỏ cà phê）.<br>・Trợ từ là <b>に</b>, không phải を: <span class='gd-jp'>行くことにした</span>, không phải 「行くことをした」.<br>・Khi nói với người khác chuyện mình nghỉ việc, <span class='gd-jp'>辞めることにしました</span> nghe như 「tôi tự quyết định」, thái độ rất rõ ràng; còn <span class='gd-jp'>辞めることになりました</span> nhẹ nhàng hơn, không quá thẳng.<br>・ことにしている là 「tự mình đặt ra」, ことになっている là 「quy định vốn dĩ là vậy」, đừng nói quy định ký túc xá bằng ことにしている.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về 「đi bộ mỗi ngày」:<br><b>ことにする</b>＝khoảnh khắc đưa ra quyết định: <span class='gd-jp'>毎日歩くことにした。</span>（Tôi quyết định đi bộ mỗi ngày）<br><b>ようにする</b>＝cố gắng làm được, đang nỗ lực: <span class='gd-jp'>毎日歩くようにしている。</span>（Tôi cố gắng đi bộ mỗi ngày）<br><b>つもり</b>＝dự định trong đầu, chưa chốt hẳn: <span class='gd-jp'>毎日歩くつもりだ。</span>（Tôi định đi bộ mỗi ngày）</div><div class='gd-sec'>Ngoài ra, <b>ことになる</b> và <b>ようになる</b> cũng hay bị nhầm:<br><span class='gd-jp'>日本で働くことになった。</span>（Tôi sắp đi làm ở Nhật: được sắp xếp, mọi việc đã chốt）<br><span class='gd-jp'>日本語が話せるようになった。</span>（Tôi đã nói được tiếng Nhật: năng lực, thói quen dần thay đổi）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: 「Tôi quyết định」 dùng ことにする, 「mọi việc đã được định」 dùng ことになる, 「cố gắng」 dùng ようにする, 「dự định」 dùng つもり.</div>","n4-48":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜まま」 nghĩa là <b>「cứ để nguyên… mà…」「cứ thế mà…」</b>: một trạng thái <b>không hề thay đổi</b>, và bạn làm luôn việc tiếp theo. Ví dụ như để máy lạnh bật mà ra khỏi nhà, hay mang nguyên giày mà đi vào phòng. Mẫu này thường mang cảm giác 「lẽ ra phải chỉnh lại trước, vậy mà không làm」.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ thể た＋まま</b>: dùng nhiều nhất. Làm một hành động trước, để lại một trạng thái, rồi trạng thái đó cứ giữ nguyên.<br><span class='gd-pair'><span class='gd-jp'>開けた</span> → <span class='gd-jp'>開けたまま</span>（để mở, không đóng）</span><br><span class='gd-pair'><span class='gd-jp'>つけた</span> → <span class='gd-jp'>つけたまま</span>（đèn, TV cứ bật, không tắt）</span><br><b>Động từ thể ない＋まま</b>: trạng thái cứ 「không làm」 một việc nào đó.<br><span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わないまま</span>（cứ không nói）</span><br><b>Danh từ＋の＋まま</b>: <span class='gd-pair'><span class='gd-jp'>昔</span> → <span class='gd-jp'>昔のまま</span>（vẫn như ngày xưa）</span><br><b>この・その・あの＋まま</b>: <span class='gd-jp'>このまま</span>（cứ thế này）、<span class='gd-jp'>そのまま</span>（cứ thế đó）<br>Tính từ cũng nối được: tính từ い nối thẳng, như <span class='gd-jp'>若いまま</span>（cứ trẻ mãi）; tính từ な thì thêm な, như <span class='gd-jp'>きれいなまま</span>（giữ nguyên sạch sẽ）.</div><div class='gd-h'>Những dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Lỡ để nguyên như vậy</span>Dùng cùng 「〜てしまう」, diễn tả sự tiếc nuối, hỏng chuyện.</div><div class='gd-ex-line'>・<span class='gd-jp'>眼鏡をかけたままシャワーを浴びてしまった。</span>（Tôi lỡ đeo nguyên kính mà đi tắm mất rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけたまま寝てしまった。</span>（Tôi lỡ để nguyên TV bật mà ngủ quên mất）</div><div class='gd-sec'><span class='gd-tag'>Quy định, nhắc nhở</span>Bảo người khác đừng 「để nguyên như vậy mà…」.</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を履いたまま部屋に入らないでください。</span>（Xin đừng mang nguyên giày vào phòng）</div><div class='gd-sec'><span class='gd-tag'>Cứ không làm</span>Dùng thể ない, nói một việc từ đầu đến cuối đều không làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>何も言わないまま帰ってしまった。</span>（Cậu ấy chẳng nói gì mà đã về mất rồi）</div><div class='gd-sec'><span class='gd-tag'>このまま・そのまま</span>Nghe cực nhiều trong đời sống, nhân viên cửa hàng và tổng đài rất hay nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>そのままお待ちください。</span>（Xin cứ giữ máy và chờ một chút）</div><div class='gd-ex-line'>・<span class='gd-jp'>袋はいりません。このままで大丈夫です。</span>（Không cần túi đâu, cứ cầm thế này là được）</div><div class='gd-sec'><span class='gd-tag'>Đặt cuối câu</span>Dùng 「〜のままだ／のままです」 để nói 「vẫn như cũ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は昔のままだ。</span>（Thị trấn này vẫn y như ngày xưa）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Chữ た ở đây <b>không phải 「quá khứ」</b>, mà là 「đã trở thành trạng thái đó」. Nói về hiện tại hay tương lai vẫn dùng thể た: <span class='gd-jp'>靴を履いたまま入ってもいいですよ。</span>（Cứ mang nguyên giày vào cũng không sao đâu）<br>・Khi nói 「giữ nguyên một trạng thái」, đừng nối với thể từ điển: ×<span class='gd-jp'>眼鏡をかけるまま</span>, phải nói ○<span class='gd-jp'>眼鏡をかけたまま</span>.<br>・Sau danh từ nhất định phải thêm の: ×<span class='gd-jp'>昔まま</span>, phải nói ○<span class='gd-jp'>昔のまま</span>.<br>・Không phải cứ 「vừa… vừa…」 là まま. Nếu chỉ là hai việc cùng lúc (vừa ăn vừa xem), tiếng Nhật dùng ながら, xem bên dưới.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>〜ながら</b>＝hai hành động <b>diễn ra cùng lúc</b>, cả hai đều do bạn chủ động làm:<br><span class='gd-jp'>テレビを見ながら勉強した。</span>（Vừa xem TV vừa học bài）<br><b>〜たまま</b>＝một trạng thái <b>cứ để yên không đụng đến</b>, rồi làm việc tiếp theo:<br><span class='gd-jp'>テレビをつけたまま勉強した。</span>（Để nguyên TV bật mà học bài）<br>Câu đầu bạn thật sự có xem TV; câu sau TV chỉ đang bật, có thể bạn chẳng xem chút nào.</div><div class='gd-sec'><b>〜て</b>＝cách nói 「làm… trong khi…」 rất bình thường, không có cảm giác 「lẽ ra phải đổi mà không đổi」:<br><span class='gd-jp'>帽子をかぶって出かけた。</span>（Đội mũ rồi ra ngoài）<br><b>〜たまま</b>＝người nghe sẽ thấy 「lẽ ra phải bỏ ra trước chứ」:<br><span class='gd-jp'>帽子をかぶったまま教室に入った。</span>（Đội nguyên mũ mà vào lớp, nghe như lẽ ra nên bỏ xuống trước）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: hai việc làm cùng lúc là ながら; một trạng thái cứ để nguyên không đụng đến mà làm việc tiếp theo là たまま.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm 「にしておく」 phía sau＝<b>cố ý để nó giữ nguyên như vậy</b>: <span class='gd-jp'>窓を開けたままにしておいてください。</span>（Xin cứ để cửa sổ mở nhé, đừng đóng lại）</div>","n4-13":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てもいいです」nghĩa là <b>「được phép ~」「~ cũng không sao」</b>. Thêm「か」phía sau thành 「~ được không?」, đây là cách nói phổ biến nhất khi <b>xin phép người khác</b> ở Nhật. Muốn chụp ảnh trong tiệm, muốn ngồi vào chỗ trống, muốn thử đồ… đều mở lời bằng mẫu này.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chuyển động từ sang thể て trước, rồi thêm「もいいです」.<br><span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使って</span> → <span class='gd-jp'>使ってもいいです</span></span></div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: nhìn âm cuối.<br>う、つ、る → って：<span class='gd-pair'><span class='gd-jp'>座る</span> → <span class='gd-jp'>座って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><br>む、ぶ、ぬ → んで：<span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んで</span></span><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → <span class='gd-jp'>呼んで</span></span><br>く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>(chỉ có <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span> là ngoại lệ)<br>ぐ → いで：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」rồi thêm て.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span></div><div class='gd-h'>Những cách nói bạn hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Hỏi xin phép</span>Thêm「か」ở cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>この椅子を使ってもいいですか。</span>(Tôi dùng cái ghế này được không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに座ってもいいですか。</span>(Tôi ngồi ở đây được không?)</div><div class='gd-sec'><span class='gd-tag'>Cách trả lời</span>Được: <span class='gd-jp'>はい、どうぞ。</span>(Vâng, mời bạn)、<span class='gd-jp'>いいですよ。</span>(Được chứ)<br>Không được: <span class='gd-jp'>すみません、ちょっと…。</span>(Xin lỗi, hơi bất tiện một chút…)</div><div class='gd-sec'><span class='gd-tag'>Nói cho người khác biết là được</span>Cuối câu thường thêm「よ」, nghe thân thiện hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休んでもいいですよ。</span>(Ngày mai bạn nghỉ cũng được nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆で書いてもいいです。</span>(Viết bằng bút chì cũng được)</div><div class='gd-sec'><span class='gd-tag'>Giữa bạn bè</span>Bỏ です, trong văn nói thậm chí còn lược cả「も」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、食べていい？</span>(Cái này ăn được không?)</div><div class='gd-sec'>Với cấp trên, khách hàng, muốn hỏi lịch sự hơn thì đổi いい thành <span class='gd-jp'>よろしい</span>：<span class='gd-jp'>写真を撮ってもよろしいですか。</span>(Xin phép cho tôi chụp ảnh được không ạ?)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Thể て kết thúc bằng「で」thì phía sau nối「でもいい」：<span class='gd-jp'>休んでもいい</span>, đừng viết thành 休んてもいい.<br>・Khi bị hỏi「〜てもいいですか」mà muốn từ chối, sách giáo khoa dạy <span class='gd-jp'>いいえ、いけません</span>, nhưng trong hội thoại thật nghe rất cứng, như đang mắng người ta. Ngoài đời người ta thường nói <span class='gd-jp'>すみません、ちょっと…</span>.<br>・「〜てもいいですよ」là <b>cho phép người khác</b>, giọng hơi kiểu người trên nói với người dưới. Nói <span class='gd-jp'>帰ってもいいですよ</span> với thầy cô hay cấp trên là rất bất lịch sự.<br>・Tiếng Việt dùng 「có thể」 cũng để nói về khả năng, ví dụ 「Tôi có thể nói tiếng Nhật」 thực ra là 「Tôi nói được」, tiếng Nhật phải nói <span class='gd-jp'>日本語が話せます</span>. Nếu nói <span class='gd-jp'>日本語を話してもいいです</span> thì nghĩa sẽ thành 「được phép nói tiếng Nhật」.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Bốn mẫu 「được phép, không được phép, không cần, bắt buộc」 trông rất giống nhau, hãy xem qua cùng một việc:<br><span class='gd-tag'>Làm, OK</span><span class='gd-jp'>明日は来てもいいです。</span>(Ngày mai đến cũng được)<br><span class='gd-tag'>Làm, NG</span><span class='gd-jp'>明日は来てはいけません。</span>(Ngày mai không được đến)<br><span class='gd-tag'>Không làm, OK</span><span class='gd-jp'>明日は来なくてもいいです。</span>(Ngày mai không đến cũng không sao)<br><span class='gd-tag'>Không làm, NG</span><span class='gd-jp'>明日は来なくてはいけません。</span>(Ngày mai nhất định phải đến)<br>Ô cuối cũng hay được nói thành <span class='gd-jp'>来なければなりません</span>, nghĩa giống nhau.</div><div class='gd-warn'>Mẹo phân biệt: nhìn phía trước là「て」hay「なくて」, rồi nhìn phía sau là「いい」hay「いけない」.</div><div class='gd-sec'>Ngoài ra đừng nhầm với <b>ことができます</b>:<br><span class='gd-jp'>ここで泳いでもいいですか。</span>(Bơi ở đây được không?: hỏi xin phép)<br><span class='gd-jp'>泳ぐことができますか。</span>(Bạn biết bơi không?: hỏi về khả năng)</div><div class='gd-warn'>Mẹo phân biệt: hỏi 「được phép hay không」 dùng てもいい; nói về 「biết hay không, làm được hay không」 dùng ことができる.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học nốt ba ô còn lại trong bảng trên: 「〜てはいけません」(cấm đoán), 「〜なくてもいいです」(không cần thiết), 「〜なければなりません」(nghĩa vụ).</div>","n4-14":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てはいけません」nghĩa là <b>「không được ~」「cấm ~」</b>. Thầy cô thông báo quy định, giới thiệu nội quy nơi nào đó, hoặc bố mẹ dặn con 「không được nói dối」, đều dùng đến mẫu này. (Biển báo thực tế phần lớn viết là 「<span class='gd-jp'>撮影禁止</span>」hoặc「<span class='gd-jp'>〜ないでください</span>」, ít khi viết nguyên cả câu.)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Giải thích quy định</span>Quy định của trường học, công ty, địa điểm, nói trực tiếp bằng lời cho đối phương nghe.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってはいけません。</span>(Ở đây không được chụp ảnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業中に寝てはいけません。</span>(Trong giờ học không được ngủ)</div><div class='gd-sec'><span class='gd-tag'>Dạy trẻ, nói lẽ phải</span>Người lớn nói với trẻ con, hoặc nói về điều ai cũng nên tuân thủ, thường dùng 「〜てはいけない」không có ます.</div><div class='gd-ex-line'>・<span class='gd-jp'>うそをついてはいけないよ。</span>(Không được nói dối đâu nhé)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước hết chuyển động từ sang <b>thể て</b> (chính là dạng dùng với「〜てください」), rồi thêm thẳng「はいけません」.<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → <span class='gd-jp'>撮って</span> → <span class='gd-jp'>撮ってはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてはいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはいけません</span></span><br>Một số động từ nhóm 1 (ngũ đoạn) có thể て là「で」, khi đó thành「ではいけません」：<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んではいけません</span></span><br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んではいけません</span></span></div><div class='gd-h'>Những cách nói bạn hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>〜てはいけません</span>Cách nói lịch sự, dùng khi giải thích quy định.<br><span class='gd-tag'>〜てはいけない</span>Cách nói thông thường, dùng với người nhà, bạn bè, trẻ con.<br><span class='gd-tag'>〜ちゃいけない</span>Dạng rút gọn trong văn nói: 「ては」thành「ちゃ」, 「では」thành「じゃ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないから、ここで遊んじゃいけないよ。</span>(Nguy hiểm lắm, không được chơi ở đây đâu nhé)</div><div class='gd-sec'><span class='gd-tag'>〜ちゃだめ</span>Đổi「いけない」thành「だめ」, khẩu ngữ hơn, bố mẹ mắng con rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ食べちゃだめ。</span>(Chưa được ăn đâu)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・「は」trong「ては」đọc là <b>wa</b>, không phải ha.<br>・Sau「飲んで」「遊んで」phải nối <b>では</b>, đừng viết thành 飲んてはいけません. Khi rút gọn cũng đổi thành「じゃ」：<span class='gd-jp'>飲んじゃだめ</span>.<br>・Cách nói này <b>giọng rất cứng</b>, như đang ra quy định. Đừng dùng thẳng với cấp trên, khách hàng, người lớn tuổi; hãy đổi sang <span class='gd-jp'>〜ないでください</span> (xin đừng ~), hoặc câu cửa hàng hay dùng là <span class='gd-jp'>〜はご遠慮ください</span>.<br>・Sách giáo khoa hay dạy「<span class='gd-jp'>〜てもいいですか</span>」→「<span class='gd-jp'>いいえ、〜てはいけません</span>」, nhưng ngoài đời trả lời vậy nghe rất gắt. Người Nhật thường nói <span class='gd-jp'>すみません、ここはちょっと…</span>, dùng「ちょっと」để từ chối khéo.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Bốn mẫu 「được phép / không được phép / không cần / bắt buộc」 rất dễ rối, hãy xem cùng một tình huống (bác sĩ dặn uống thuốc):<br><b>てもいい</b>＝được phép làm: <span class='gd-jp'>この薬は飲んでもいいです。</span>(Thuốc này uống cũng được)<br><b>てはいけない</b>＝không được làm: <span class='gd-jp'>この薬は飲んではいけません。</span>(Thuốc này không được uống)<br><b>なくてもいい</b>＝không làm cũng được: <span class='gd-jp'>この薬は飲まなくてもいいです。</span>(Thuốc này không uống cũng không sao)<br><b>なければならない</b>＝nhất định phải làm: <span class='gd-jp'>この薬は飲まなければなりません。</span>(Thuốc này nhất định phải uống)</div><div class='gd-sec'>Cần cẩn thận nhất là「<b>なくてはいけません</b>」: nó cũng có「いけません」nhưng nghĩa lại là <b>bắt buộc</b>, giống「なければなりません」:<br><span class='gd-jp'>飲んではいけません</span>(không được uống)<br><span class='gd-jp'>飲まなくてはいけません</span>(nhất định phải uống)<br>Chỉ khác vài chữ mà nghĩa hoàn toàn trái ngược.</div><div class='gd-warn'>Mẹo phân biệt: nhìn phần đứng trước「はいけません」. Nếu là thể て thông thường (<span class='gd-jp'>飲んで</span>) → không được; nếu là「なくて」(<span class='gd-jp'>飲まなくて</span>) → nhất định phải.</div>","n4-2":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜つもりです」nghĩa là <b>“tôi định ～”</b> trong tiếng Việt. Bạn đã nghĩ kỹ là sẽ làm một việc gì đó, và khi nói kế hoạch của mình cho người khác nghe thì dùng mẫu này.<br>Ví dụ bạn bè hỏi hè này bạn làm gì, bạn trả lời “Mình định đi Nhật”, tức là <span class='gd-jp'>日本へ行くつもりです</span>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Định làm</span><b>Thể từ điển</b> của động từ (dạng gốc tra được trong từ điển) ＋つもりです<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くつもりです</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買うつもりです</span></span><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強するつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学するつもりです。</span>(Năm sau mình định đi Nhật du học)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家でゆっくりするつもりです。</span>(Cuối tuần mình định ở nhà nghỉ ngơi thoải mái)</div><div class='gd-sec'><span class='gd-tag'>Định không làm</span><b>Thể ない</b> của động từ ＋つもりです<br><span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わない</span> → <span class='gd-jp'>吸わないつもりです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>もうタバコは吸わないつもりです。</span>(Mình định không hút thuốc nữa)</div><div class='gd-sec'>Khi nói chuyện với bạn bè, bạn đổi です thành <b>だ</b>, hoặc nói thẳng đến つもり là đủ: <span class='gd-jp'>夏休み、どうするつもり？</span>(Kỳ nghỉ hè bạn định làm gì?)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>つもりはありません</span>Nghĩa là “hoàn toàn không có ý định đó”, dứt khoát hơn 「〜ないつもりです」, thường dùng để từ chối.</div><div class='gd-ex-line'>・<span class='gd-jp'>会社をやめるつもりはありません。</span>(Tôi hoàn toàn không có ý định nghỉ việc ở công ty)</div><div class='gd-sec'><span class='gd-tag'>つもりでした</span>Nghĩa là “vốn định ～”, phía sau thường là kết quả “nhưng đã không làm được”.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝るつもりでしたが、ゲームをしてしまいました。</span>(Vốn định đi ngủ sớm, nhưng rồi lại chơi game mất)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước つもり là <b>thể từ điển</b>, không được dùng thể ます: đúng là <span class='gd-jp'>行くつもりです</span>, không phải “行きますつもりです”.<br>・Mẫu này nói về <b>dự định của con người</b>, những việc bản thân không kiểm soát được thì không dùng. Câu kiểu “ngày mai định sẽ nắng” thì tiếng Nhật không nói bằng つもり.<br>・Chủ yếu dùng để nói về dự định của <b>chính mình</b>. Khi nói về dự định của người khác, thường thêm「そうです」hoặc「と言っていました」: <span class='gd-jp'>田中さんは留学するつもりだそうです。</span>(Nghe nói anh Tanaka định đi du học)<br>・Hỏi thẳng thầy cô hay cấp trên「<span class='gd-jp'>どうするつもりですか</span>」nghe giống đang chất vấn “rốt cuộc bạn định làm gì đây”. Muốn hỏi kế hoạch của bề trên thì nói <span class='gd-jp'>ご予定は？</span> sẽ lịch sự hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là “năm sau đi Nhật”, nhưng mỗi cách nói cho thấy mức độ chắc chắn khác nhau:<br><b>ようと思っています</b>＝trong đầu có ý nghĩ đó, đang cân nhắc (N4-42)<br><span class='gd-jp'>来年、日本へ行こうと思っています。</span>(Mình đang nghĩ đến chuyện năm sau đi Nhật)<br><b>つもりです</b>＝dự định bạn đã quyết, chắc chắn hơn câu trên<br><span class='gd-jp'>来年、日本へ行くつもりです。</span>(Mình định năm sau đi Nhật)<br><b>予定です</b>＝lịch trình đã được sắp xếp cụ thể, ví dụ vé máy bay đã đặt, ngày đã chốt<br><span class='gd-jp'>来年3月に日本へ行く予定です。</span>(Mình dự kiến tháng 3 năm sau đi Nhật)</div><div class='gd-warn'>Mẹo phân biệt nhanh: “vẫn đang nghĩ” dùng ようと思う, “mình đã quyết rồi” dùng つもり, “đã xếp vào lịch” dùng 予定.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói “mình đã quyết định ～”, bạn có thể học tiếp <span class='gd-jp'>〜ことにします</span> (N4-47): <span class='gd-jp'>来年留学することにしました。</span>(Mình đã quyết định năm sau đi du học)</div>","n4-3":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜かもしれません」nghĩa là <b>“có thể ～”, “biết đâu ～”</b> trong tiếng Việt. Bạn không chắc chắn, thấy có khả năng đó nhưng cũng có thể không. Giống như khi bạn nói “Mai có thể trời sẽ mưa đó”, tiếng Nhật là <span class='gd-jp'>明日は雨が降るかもしれません</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Phỏng đoán</span>Bạn không chắc về một việc, và nói ra tình huống mà bạn thấy “có khả năng”.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>(Ngày mai có thể trời sẽ mưa)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店、今日は休みかもしれない。</span>(Quán đó hôm nay biết đâu nghỉ bán)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう帰ったかもしれない。</span>(Anh ấy có thể đã về rồi)</div><div class='gd-sec'><span class='gd-tag'>Báo trước cho nhẹ nhàng</span>Khi nói về chuyện của chính mình cũng rất hay dùng, giúp lời nói mềm hơn và để người nghe chuẩn bị tinh thần trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、少し遅れるかもしれません。</span>(Xin lỗi, có thể tôi sẽ đến trễ một chút)</div><div class='gd-ex-line'>・<span class='gd-jp'>土曜日はちょっと行けないかもしれない。</span>(Thứ Bảy có thể mình không đi được)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: không cần biến đổi, ghép trực tiếp. Dạng phủ định và quá khứ cũng ghép thẳng như vậy.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないかもしれない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったかもしれない</span></span></div><div class='gd-sec'><b>Tính từ い</b>: ghép trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いかもしれない</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: bỏ「だ」rồi mới ghép.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → bỏ だ → <span class='gd-jp'>静かかもしれない</span></span><br><span class='gd-pair'><span class='gd-jp'>雨だ</span> → bỏ だ → <span class='gd-jp'>雨かもしれない</span></span><br>Nhưng với quá khứ「だった」thì phải giữ lại: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったかもしれない</span></span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>かもしれません</span>Dạng lịch sự, dùng với thầy cô, đồng nghiệp, khách hàng.<br><span class='gd-tag'>かもしれない</span>Dùng giữa bạn bè, người nhà.<br><span class='gd-tag'>かも</span>Dạng rút gọn khẩu ngữ hơn nữa, giới trẻ và bạn bè nói chuyện với nhau nghe rất thường xuyên.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、財布忘れたかも。</span>(A, hình như mình quên mang ví rồi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ và tính từ な không được giữ lại「だ」: phải nói <span class='gd-jp'>雨かもしれない</span>, không phải “雨だかもしれない”.<br>・「ない」ở cuối「かもしれない」<b>không phải phủ định</b>. <span class='gd-jp'>来るかもしれない</span> nghĩa là “có thể sẽ đến”. Muốn nói “có thể không đến” thì phải chuyển động từ phía trước sang phủ định: <span class='gd-jp'>来ないかもしれない</span>.<br>・Mức độ chắc chắn của mẫu này rất thấp, khoảng năm ăn năm thua, thậm chí thấp hơn. Việc bạn rất chắc chắn thì đừng dùng, kẻo nghe thiếu trách nhiệm. Ví dụ đã hẹn với người ta rồi mà lại nói <span class='gd-jp'>行くかもしれません</span>, đối phương sẽ nghĩ bạn có thể không đến.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là đoán xem “Suzuki có đến không”, nhưng mức độ chắc chắn khác nhau:<br><b>かもしれない</b>＝có thể đến, cũng có thể không, trong lòng không chắc: <span class='gd-jp'>鈴木さんは来るかもしれません。</span>(Biết đâu Suzuki sẽ đến)<br><b>でしょう</b>＝chắc là sẽ đến, thấy khá có khả năng: <span class='gd-jp'>鈴木さんは来るでしょう。</span>(Chắc là Suzuki sẽ đến)<br><b>はず</b>＝theo lẽ thường thì sẽ đến, có căn cứ, ví dụ hôm qua anh ấy đích thân nói sẽ đến: <span class='gd-jp'>鈴木さんは来るはずです。</span>(Suzuki lẽ ra phải đến mới đúng)</div><div class='gd-warn'>Mẹo phân biệt nhanh: mức độ chắc chắn từ thấp đến cao là かもしれない ＜ でしょう ＜ はず. Trong lòng không chắc, chỉ là “biết đâu” thì dùng かもしれない; có lý do, thấy “theo lẽ thường là vậy” thì dùng はず.</div>","n4-15":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なくてもいいです」nghĩa là <b>\"không cần ～\"</b> hoặc <b>\"không ～ cũng không sao\"</b>. Giống như khi nhân viên cửa hàng nói với bạn \"Không cần cởi giày đâu nhé\": việc này <b>không làm cũng được, mà làm cũng không sao</b>.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nói với người khác là không cần làm</span>Để đối phương yên tâm, đỡ phải làm việc thừa.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来なくてもいいです。</span>(Ngày mai không cần đến)</div><div class='gd-ex-line'>・<span class='gd-jp'>全部食べなくてもいいですよ。</span>(Không cần ăn hết đâu nhé)</div><div class='gd-sec'><span class='gd-tag'>Hỏi đối phương có cần không</span>Thêm 「か」 vào cuối câu, nghĩa là \"không ～ cũng được à?\".</div><div class='gd-ex-line'>・<span class='gd-jp'>靴を脱がなくてもいいですか。</span>(Không cần cởi giày à?)</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、脱がなくてもいいですよ。</span>(Vâng, không cần cởi đâu)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Đầu tiên chuyển động từ sang thể ない (dạng \"không ～\"), sau đó đổi 「い」 ở cuối thành 「くて」, rồi thêm 「もいい」 phía sau.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → đổi い thành くて → <span class='gd-jp'>行かなくて</span></span> → thêm もいい → <span class='gd-pair'><span class='gd-jp'>行かなくてもいい</span></span><br>Muốn nói lịch sự thì thêm 「です」 ở cuối.</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>: đổi âm cuối sang âm hàng 「あ」 cùng cột, thêm ない, rồi đổi thành なくてもいい.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かなくてもいい</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らなくてもいい</span></span><br>Động từ kết thúc bằng 「う」 thì phải đổi thành <b>わ</b>: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなくてもいい</span></span><br>Ngoại lệ: thể ない của <span class='gd-jp'>ある</span> chính là 「ない」, nên là <span class='gd-jp'>なくてもいい</span>, không phải あらなくてもいい.</div><div class='gd-ex-line'>・<span class='gd-jp'>予約がなくてもいいですか。</span>(Không có đặt trước cũng được ạ?)</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ 「る」, rồi thêm なくてもいい.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>慌てる</span> → <span class='gd-jp'>慌てなくてもいい</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなくてもいい</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なくてもいい</span>(こなくても)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は残業しなくてもいいです。</span>(Hôm nay không cần làm thêm giờ)</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Giữa bạn bè</span>Đổi 「です」 thành 「よ」, thường còn lược luôn cả 「も」.</div><div class='gd-ex-line'>・<span class='gd-jp'>無理しなくていいよ。</span>(Đừng cố quá nha, không cần gắng sức đâu)</div><div class='gd-sec'><span class='gd-tag'>Cách nói khác</span>Đổi 「いい」 thành 「大丈夫」, ý nghĩa giống nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>返事しなくても大丈夫です。</span>(Không cần trả lời cũng không sao)</div><div class='gd-sec'><span class='gd-tag'>Lịch sự hơn</span>Ở công ty, cửa hàng, hay thông báo chính thức bạn sẽ nghe 「なくてもかまいません」.</div><div class='gd-ex-line'>・<span class='gd-jp'>印鑑は持ってこなくてもかまいません。</span>(Không cần mang theo con dấu cũng không sao)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không được nối ても trực tiếp sau ない: nói 「行かないてもいい」 là sai, phải đổi い thành くて, thành <span class='gd-jp'>行かなくてもいい</span>.<br>・<span class='gd-jp'>買う</span> là <span class='gd-jp'>買わない</span>, không phải 買あない; <span class='gd-jp'>ある</span> là <span class='gd-jp'>ない</span>, không phải あらない.<br>・Trong tiếng Việt, \"không cần đến\" và \"đừng đến\" nghe gần giống nhau, nhưng tiếng Nhật thì khác hẳn. <span class='gd-jp'>来なくてもいい</span> nghĩa là \"không đến cũng được, đến cũng không sao\", không hề có ý bảo bạn đừng đến.<br>・Khi người khác hỏi bạn 「<span class='gd-jp'>〜なくてもいいですか</span>」, nếu câu trả lời là \"bắt buộc phải làm\", hãy trả lời bằng <span class='gd-jp'>いいえ、〜なければなりません</span>, đừng chỉ nói いいえ rồi dừng lại.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng một việc \"ngày mai đến công ty\", có bốn cách nói:<br><b>てもいい</b> = được phép làm: <span class='gd-jp'>明日、会社に行ってもいいです。</span>(Ngày mai được đến công ty)<br><b>なくてもいい</b> = không làm cũng được: <span class='gd-jp'>明日、会社に行かなくてもいいです。</span>(Ngày mai không cần đến công ty)<br><b>てはいけない</b> = không được làm: <span class='gd-jp'>明日、会社に行ってはいけません。</span>(Ngày mai không được đến công ty)<br><b>なければならない</b> = nhất định phải làm: <span class='gd-jp'>明日、会社に行かなければなりません。</span>(Ngày mai nhất định phải đến công ty)</div><div class='gd-sec'>Ngoài ra, mẫu hay bị nhầm với nó là 「ないでください」:<br><span class='gd-jp'>来ないでください。</span>(Xin đừng đến: bảo đối phương đừng làm)<br><span class='gd-jp'>来なくてもいいです。</span>(Không cần đến: làm hay không đều được)</div><div class='gd-warn'>Mẹo phân biệt: muốn nói \"không cần, khỏi\" thì dùng なくてもいい; muốn nói \"đừng làm, cấm\" thì dùng ないでください hoặc てはいけない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tính từ và danh từ cũng dùng được với ý nghĩa tương tự: <span class='gd-jp'>高くなくてもいいです。</span>(Không đắt cũng không sao), <span class='gd-jp'>上手じゃなくてもいいです。</span>(Không giỏi cũng không sao). Tiếp theo hãy học 「<span class='gd-jp'>〜なければなりません</span>」, bạn sẽ nói rõ được cả \"không cần làm\" lẫn \"nhất định phải làm\".</div>","n4-16":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なければなりません」nghĩa là <b>\"nhất định phải ～\"</b> hoặc <b>\"không ～ không được\"</b>. Cách nghĩ của tiếng Nhật khá thú vị: thật ra câu này là \"nếu không làm thì không được\". Không làm thì không được, tức là nhất định phải làm.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Quy định・nghĩa vụ</span>Dùng cho quy định và nghĩa vụ: việc trường học, công ty quy định, hoặc việc hoàn cảnh buộc bạn phải làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにレポートを出さなければなりません。</span>(Trước ngày mai nhất định phải nộp báo cáo)</div><div class='gd-ex-line'>・<span class='gd-jp'>学校では制服を着なければなりません。</span>(Ở trường nhất định phải mặc đồng phục)</div><div class='gd-sec'><span class='gd-tag'>Tự thấy mình phải làm</span>Không ai quy định, chính bạn thấy \"đến lúc phải làm rồi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だ。帰らなければならない。</span>(Đã 11 giờ rồi, mình phải về nhà thôi)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を毎日飲まなければなりません。</span>(Mỗi ngày tôi đều phải uống thuốc)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Ba bước: chuyển sang thể ない (dạng \"không ～\"), bỏ 「ない」 ở cuối, rồi nối <b>なければなりません</b>.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span> → bỏ ない → <span class='gd-pair'><span class='gd-jp'>行か</span> → <span class='gd-jp'>行かなければなりません</span></span></div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>:<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わなければなりません</span></span>(động từ kết thúc bằng う thì đổi thành わ, không phải あ)</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きなければなりません</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しなければなりません</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来なければなりません</span>(こなければ)</span></div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>なければなりません</span>Cách nói lịch sự, dùng với thầy cô, cấp trên, khách hàng.<br><span class='gd-tag'>なければならない</span>Thể thường, dùng khi tự nói với mình hoặc khi viết văn.<br><span class='gd-tag'>なきゃ／ないと</span>Khẩu ngữ giữa bạn bè: 「なければ」 rút gọn thành 「なきゃ」, hoặc nói đến 「ないと」 là dừng luôn.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、もう行かなきゃ。</span>(A, mình phải đi đây)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日早いから、早く寝ないと。</span>(Mai phải dậy sớm, phải đi ngủ sớm thôi)</div><div class='gd-sec'>Muốn nói quá khứ \"lúc đó bắt buộc phải ～\", đổi phần cuối thành <b>なりませんでした</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は遅くまで働かなければなりませんでした。</span>(Hôm qua tôi phải làm việc đến khuya)</div><div class='gd-sec'>Ngoài ra bạn cũng sẽ nghe 「<span class='gd-jp'>〜なければいけません</span>」, nghĩa gần như giống hệt, rất hay dùng trong hội thoại hằng ngày.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với thể ない, không phải thể từ điển (dạng gốc trong từ điển): không phải 行くなければ, mà là <span class='gd-jp'>行かなければ</span>.<br>・Cụm này dài nên dễ đọc sai, hãy tách thành 「な・け・れ・ば」 + 「なりません」 để nhớ, không phải なくれば hay なけば.<br>・Đừng thấy 「ません」 ở cuối mà tưởng là \"không làm\". Cả câu có nghĩa là <b>nhất định phải làm</b>.<br>・<span class='gd-jp'>来る</span> đọc là <b>こなければ</b>, không phải きなければ.<br>・「なきゃ」「ないと」 là cách nói giữa bạn bè; với cấp trên, thầy cô phải nói đầy đủ なければなりません.<br>・Khi nhờ người khác làm việc, nói thẳng \"bạn phải ～\" nghe rất cứng và gay gắt, thông thường dùng 「〜てください」 sẽ lịch sự hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Bốn mẫu này hay xuất hiện cùng nhau trong đề thi, so sánh qua cùng một việc \"ngày mai đến trường\":<br><span class='gd-jp'>明日、学校に行かなければなりません。</span>(Ngày mai <b>nhất định phải</b> đến trường)<br><span class='gd-jp'>明日、学校に行かなくてもいいです。</span>(Ngày mai <b>không đến cũng được</b>)<br><span class='gd-jp'>明日、学校に行ってもいいです。</span>(Ngày mai <b>được phép</b> đến trường)<br><span class='gd-jp'>明日、学校に行ってはいけません。</span>(Ngày mai <b>không được</b> đến trường)</div><div class='gd-sec'>Đặc biệt lưu ý: khi bị hỏi 「<span class='gd-jp'>〜なければなりませんか</span>」 (nhất định phải ～ à?), nếu muốn trả lời \"không cần\", hãy nói <b>なくてもいいです</b>, không phải dạng phủ định của なければなりません.</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を書かなければなりませんか。</span>(Nhất định phải viết tên à?)</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、書かなくてもいいです。</span>(Không, không viết cũng được)</div><div class='gd-sec'>Một mẫu nữa hay bị nhầm là <b>ほうがいい</b>, nó chỉ là \"lời khuyên\", không bắt buộc:<br><span class='gd-jp'>薬を飲んだほうがいいです。</span>(Tốt nhất là nên uống thuốc)<br><span class='gd-jp'>薬を飲まなければなりません。</span>(Nhất định phải uống thuốc)</div><div class='gd-warn'>Mẹo phân biệt: \"nhất định phải\" là なければなりません, \"không cần\" là なくてもいい, \"tốt nhất nên\" là ほうがいい.</div>","n4-21":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「し」giống như <b>「vừa ~ vừa ~」「với lại ~」「mà còn ~」</b> trong tiếng Việt. Khi giải thích \"tại sao\", bạn xếp từng lý do chồng lên nhau, rồi đưa ra kết luận ở cuối. Ví dụ như \"quán này rẻ, lại ngon nữa, nên mình hay đến\". Tiếng Nhật dùng し để nối \"rẻ\" và \"ngon\" lại với nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（Quán này vừa rẻ vừa ngon, nên mình hay đến）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>thể thường</b> (cách nói không có ます、です), phía sau thêm し trực tiếp.<br><b>Động từ</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るし</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>ないし</span></span><span class='gd-pair'><span class='gd-jp'>疲れた</span> → <span class='gd-jp'>疲れたし</span></span><br><b>Tính từ い</b>：<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いし</span></span><span class='gd-pair'><span class='gd-jp'>遠くない</span> → <span class='gd-jp'>遠くないし</span></span><br><b>Tính từ な</b>：phải thêm「だ」rồi mới thêm し。<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだし</span></span><br><b>Danh từ</b>：cũng phải thêm「だ」。<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だし</span></span><br>Khi nói với người lớn tuổi hơn hoặc khách, bạn cũng có thể dùng cách nói lịch sự：<span class='gd-jp'>便利ですし</span>、<span class='gd-jp'>あまり時間もありませんし</span>。</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Xếp chồng lý do để dẫn đến kết luận</span>Đây là cách dùng phổ biến nhất. Trước mỗi lý do thường đi kèm「も」, tạo cảm giác \"cái này cũng ~, cái kia cũng ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>お金もないし、時間もないし、旅行は無理です。</span>（Tiền cũng không có, thời gian cũng không có, đi du lịch là không thể rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨も降っているし、疲れているし、タクシーで帰りましょう。</span>（Trời đang mưa, lại mệt nữa, mình đi taxi về nhé）</div><div class='gd-sec'><span class='gd-tag'>Nói về ưu điểm, nhược điểm của người hay vật</span>Dùng để miêu tả một người hay một nơi có những nét đặc trưng nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは優しいし、おもしろいし、みんなに人気がある。</span>（Anh Tanaka vừa dịu dàng vừa thú vị, được mọi người yêu mến）</div><div class='gd-sec'><span class='gd-tag'>Chỉ nói một lý do</span>Chỉ nói một lý do cũng được. Nghe như \"(còn lý do khác nữa, nhưng) chỉ riêng điều này thôi cũng ~\", giọng nhẹ nhàng hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう遅いし、そろそろ帰ります。</span>（Muộn rồi, mình sắp về đây）</div><div class='gd-sec'>Thậm chí bạn có thể bỏ lửng phần kết luận để đối phương tự hiểu, rất tiện khi muốn từ chối ai đó：<br><span class='gd-jp'>今日はちょっと疲れてるし…</span>（Hôm nay mình hơi mệt nên……）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ な và danh từ <b>nhất định phải thêm だ</b>：phải nói <span class='gd-jp'>静かだし</span>、<span class='gd-jp'>雨だし</span>, không được nói「静かし」「雨し」。<br>・Các lý do xếp chồng phải <b>cùng một hướng</b>, cùng ủng hộ một kết luận. Ví dụ muốn nói \"mình thích quán này\" thì xếp \"rẻ\", \"ngon\"; đừng trộn lẫn một lý do tốt với một lý do xấu.<br>・し mang sắc thái \"không chỉ có điều này\". Nếu bạn chỉ có một nguyên nhân rất rõ ràng và muốn nói cho rõ ràng, mạnh mẽ, thì dùng「から」hoặc「ので」sẽ trực tiếp hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>し</b>＝xếp chồng nhiều lý do, giọng điệu là \"vừa ~ vừa ~, nên…\"：<br><span class='gd-jp'>この店は安いし、おいしいし、よく来ます。</span>（Vừa rẻ vừa ngon, nên mình hay đến）<br><b>から・ので</b>＝nói rõ \"chính vì điều này\"：<br><span class='gd-jp'>この店は安いから、よく来ます。</span>（Vì rẻ nên mình hay đến）</div><div class='gd-sec'><b>たり</b>cũng liệt kê nhiều thứ cùng lúc, nhưng nó liệt kê <b>những việc đã làm</b> làm ví dụ, không phải lý do：<br><span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（Cuối tuần mình xem phim, đi mua sắm này nọ）<br><span class='gd-jp'>週末は暇だし、天気もいいし、出かけよう。</span>（Cuối tuần rảnh, thời tiết lại đẹp, mình đi chơi thôi）</div><div class='gd-warn'>Mẹo phân biệt nhanh：đang nói \"tại sao\" và muốn xếp nhiều lý do thì dùng し; chỉ có một nguyên nhân rõ ràng thì dùng から・ので; đang nói \"đã làm những việc gì\" thì dùng たり。</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nói xong lý do mà muốn bổ sung thêm một lý do nữa, bạn có thể dùng「それに」(hơn nữa, với lại) để nối sang câu tiếp theo：<span class='gd-jp'>この部屋は広いし、駅にも近い。それに家賃も安い。</span>（Căn phòng này rộng, lại gần ga, với lại tiền thuê cũng rẻ）</div>","n4-36":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜でしょう」giống như <b>「chắc là ~ nhỉ」「có lẽ ~」</b> trong tiếng Việt. Cuối câu xuống giọng là đang <b>đoán</b>; cuối câu lên giọng thì thành \"~ đúng không?\", là đang <b>xác nhận với đối phương</b>. 「だろう」là dạng thường của nó, nghĩa giống nhau, chỉ là không có sắc thái lịch sự.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Phỏng đoán (xuống giọng)</span>Không chắc chắn, nhưng trong lòng nghĩ có lẽ là như vậy. Bản tin dự báo thời tiết rất thích dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るでしょう。</span>（Ngày mai chắc là trời sẽ mưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう家に帰ったでしょう。</span>（Anh Tanaka chắc đã về nhà rồi nhỉ）</div><div class='gd-sec'>Thường đi cùng「<span class='gd-jp'>たぶん</span>」(có lẽ)：<span class='gd-jp'>たぶん大丈夫でしょう。</span>（Chắc là không sao đâu）</div><div class='gd-sec'><span class='gd-tag'>Xác nhận (lên giọng)</span>Bạn nghĩ đối phương cũng biết và sẽ đồng ý, nên hỏi để họ gật đầu. Trong văn nói thường rút gọn thành「<span class='gd-jp'>でしょ？</span>」。</div><div class='gd-ex-line'>・<span class='gd-jp'>これ、おいしいでしょう？</span>（Món này ngon đúng không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょ？</span>（Thấy chưa, mình đã nói rồi mà?）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước đặt <b>thể thường</b> (cách nói không có です、ます), phía sau thêm でしょう hoặc だろう。<br>Động từ：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったでしょう</span></span><br>Tính từ い：thêm trực tiếp。<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いでしょう</span></span><br>Danh từ, tính từ な：<b>bỏ だ đi</b> rồi mới thêm。<span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>元気だ</span> → <span class='gd-jp'>元気でしょう</span></span><br>「だった」ở quá khứ thì phải giữ lại：<span class='gd-pair'><span class='gd-jp'>学生だった</span> → <span class='gd-jp'>学生だったでしょう</span></span></div><div class='gd-h'>Chọn でしょう hay だろう</div><div class='gd-sec'><b>でしょう</b>：lịch sự, dùng với người không thân, trong hoàn cảnh trang trọng, trên bản tin và dự báo thời tiết.<br><b>だろう</b>：cách nói thường, hay xuất hiện nhất khi <b>nghĩ thầm, tự nói với mình, hoặc trong văn viết</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるだろう。</span>（Ngày mai chắc trời sẽ quang đãng: tự mình nghĩ）</div><div class='gd-sec'>Nói「<span class='gd-jp'>だろう</span>」「<span class='gd-jp'>だろ？</span>」trực tiếp với người khác nghe thiên về giọng nam, khá cộc. Khi trò chuyện với bạn bè, nhiều người (nhất là con gái) nói「<span class='gd-jp'>でしょ？</span>」。</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ, tính từ な đừng giữ だ：nói <span class='gd-jp'>学生でしょう</span>, không phải「学生だでしょう」。<br>・「Sẽ」trong tiếng Việt không phải lúc nào cũng là でしょう. \"Ngày mai mình sẽ đi\" là việc do chính mình quyết định, cứ nói thẳng <span class='gd-jp'>明日行きます</span>. Dùng「行くでしょう」nghe như đang đoán xem mình có đi hay không, rất kỳ.<br>・「<span class='gd-jp'>でしょう？</span>」dùng để xác nhận mang sắc thái \"chắc bạn biết rồi chứ\", nói với thầy cô, cấp trên sẽ hơi thiếu lịch sự, đổi thành「<span class='gd-jp'>〜ですよね</span>」sẽ an toàn hơn.<br>・でしょう phải đọc kéo dài (でしょー), còn「でしょ」ngắn là dạng rút gọn trong văn nói.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng một việc: hôm nay anh Tanaka có đến hay không?<br>・<span class='gd-jp'>田中さんは来るでしょう。</span>（Anh Tanaka chắc sẽ đến nhỉ）→ Mình thấy <b>khả năng cao là sẽ đến</b>.<br>・<span class='gd-jp'>田中さんは来るかもしれません。</span>（Anh Tanaka có thể sẽ đến）→ <b>Năm ăn năm thua</b>, không đến cũng chẳng bất ngờ.<br>・<span class='gd-jp'>田中さんは来るはずです。</span>（Anh Tanaka lẽ ra sẽ đến）→ <b>Có căn cứ</b>, ví dụ hôm qua chính anh ấy nói sẽ đến.</div><div class='gd-warn'>Mẹo phân biệt nhanh：\"có thể\" dùng かもしれない, \"chắc là\" dùng でしょう, \"theo lẽ thường thì nên\" dùng はずだ。</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「と思います」phía sau sẽ mềm mại hơn, cả nam lẫn nữ đều hay dùng：<span class='gd-jp'>明日は寒くなるだろうと思います。</span>（Mình nghĩ ngày mai chắc trời sẽ lạnh hơn）<br>Biến でしょう thành câu hỏi「でしょうか」sẽ khách sáo hơn「ですか」：<span class='gd-jp'>すみません、駅はどこでしょうか。</span>（Xin lỗi, cho mình hỏi ga ở đâu ạ?）</div>","n4-11":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ほうがいい」 tương đương với <b>「bạn nên ～」「tốt nhất là ～」「không nên ～」</b> trong tiếng Việt. Bạn của bạn bị sốt, bạn nói \"Bạn nên đi khám bác sĩ nhé\", tiếng Nhật sẽ là <span class='gd-jp'>病院に行ったほうがいいよ</span>. Đây là cách đưa ra lời khuyên, kèm sắc thái \"không làm vậy thì có thể không ổn đâu nhé\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Nên làm ～</span>Động từ <b>thể た</b> + ほうがいい<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休んだほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ったほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>したほうがいい</span></span><br>Nếu chưa quen thể た, bạn có thể nghĩ từ thể て: đổi 「て」 thành 「た」, 「で」 thành 「だ」 là xong.<span class='gd-pair'><span class='gd-jp'>休んで</span> → <span class='gd-jp'>休んだ</span></span></div><div class='gd-sec'><span class='gd-tag'>Không nên ～</span>Động từ <b>thể ない</b> + ほうがいい<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないほうがいい</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないほうがいい</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないほうがいい</span>（こない）</span></div><div class='gd-sec'>Cuối câu tùy vào đối tượng: với bạn bè thì nói 「〜ほうがいいよ」, muốn lịch sự hơn thì nói 「〜ほうがいいです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていったほうがいいよ。</span>（Trời có vẻ sắp mưa, bạn nên mang theo ô nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前にコーヒーを飲まないほうがいいです。</span>（Trước khi ngủ không nên uống cà phê）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Dùng thể た nhưng <b>không phải quá khứ</b>. <span class='gd-jp'>行ったほうがいい</span> là khuyên bạn đi ngay bây giờ hoặc sau này, chứ không phải \"đã đi rồi\".<br>・Theo trực giác, bạn có thể muốn dùng thể nguyên dạng và nói 「行くほうがいい」. Khi khuyên ai đó một việc cụ thể, người Nhật quen nói <span class='gd-jp'>行ったほうがいい</span>, cứ nhớ như vậy là an toàn nhất.<br>・Phủ định chỉ cần dùng thể ない, <b>không đổi thêm sang thể た</b>: đúng là <span class='gd-jp'>行かないほうがいい</span>, đừng nói thành 「行かなかったほうがいい」.<br>・Sắc thái của mẫu này thật ra không nhẹ đâu. Nói thẳng 「〜たほうがいいですよ」 với cấp trên hay thầy cô thì nghe hơi giống đang dạy họ làm việc. Muốn khách sáo hơn, hãy thêm 「と思います」 phía sau: <span class='gd-jp'>少し休んだほうがいいと思います。</span>（Tôi nghĩ anh/chị nên nghỉ ngơi một chút）<br>・「ほう」 viết bằng kanji là 「方」, ở đây đọc là <b>ほう</b>, không phải かた như trong 「〜方（cách làm）」.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Cùng là tình huống đau họng:<br><b>たほうがいい</b> = đưa ra lời khuyên, không làm cũng được, chỉ là không ổn lắm: <span class='gd-jp'>のどが痛いなら、薬を飲んだほうがいいですよ。</span>（Nếu đau họng thì bạn nên uống thuốc nhé）<br><b>なければなりません</b> = quy định, bắt buộc phải làm: <span class='gd-jp'>この薬は一日三回飲まなければなりません。</span>（Thuốc này một ngày nhất định phải uống ba lần）<br><b>たらいい</b> = gợi ý một cách làm, giọng nhẹ nhàng hơn: <span class='gd-jp'>のどが痛いときは、温かいお茶を飲んだらいいですよ。</span>（Khi đau họng, bạn uống chút trà nóng là được）</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"nên ～ (không thì không ổn)\" dùng ほうがいい, \"nhất định phải ～\" dùng なければなりません, \"làm thế này là ổn rồi\" dùng たらいい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi いい thành よかった thì thành nỗi tiếc nuối kiểu \"biết thế đã ～\": <span class='gd-jp'>傘を持ってきたほうがよかった。</span>（Biết thế đã mang ô theo）</div>","n4-12":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜すぎる」 tương đương với <b>「quá ～」「～ quá mức」</b> trong tiếng Việt. Ăn quá nhiều, uống quá nhiều, quá đắt, quá khó… hễ <b>vượt quá mức vừa phải</b> thì thêm 「すぎる」 vào sau. Nói lịch sự thì dùng 「すぎます」.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、ゲームをやりすぎました。</span>（Hôm qua mình chơi game quá đà）</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは高すぎます。</span>（Cái túi này đắt quá）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Chuyển sang thể ます, bỏ 「ます」 rồi ghép すぎる. Cả ba nhóm động từ đều giống nhau.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べすぎる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しすぎる</span></span>（ví dụ: <span class='gd-jp'>心配しすぎる</span> = lo lắng quá mức）</div><div class='gd-sec'><span class='gd-tag'>Tính từ い</span>Bỏ 「い」 ở cuối rồi ghép すぎる.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高すぎる</span></span><span class='gd-pair'><span class='gd-jp'>難しい</span> → <span class='gd-jp'>難しすぎる</span></span></div><div class='gd-sec'><span class='gd-tag'>Tính từ な</span>Ghép trực tiếp, <b>không thêm な</b>.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かすぎる</span></span><span class='gd-pair'><span class='gd-jp'>派手</span> → <span class='gd-jp'>派手すぎる</span></span></div><div class='gd-h'>Bản thân すぎる cũng biến đổi</div><div class='gd-sec'>すぎる biến đổi giống <b>động từ nhóm 2 (động từ một đoạn)</b>: bỏ 「る」 rồi ghép thêm đuôi:<br><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎます</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎた</span></span><span class='gd-pair'><span class='gd-jp'>すぎる</span> → <span class='gd-jp'>すぎて</span></span><br>Hay gặp nhất là dùng 「すぎて」 để nêu nguyên nhân của kết quả phía sau:</div><div class='gd-ex-line'>・<span class='gd-jp'>食べすぎて、お腹が痛いです。</span>（Ăn quá nhiều nên đau bụng）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は静かすぎて、ちょっとこわいです。</span>（Căn phòng này yên tĩnh quá, hơi đáng sợ）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Thành danh từ</span>Động từ thể ます + すぎ, không thêm る phía sau, sẽ thành danh từ mang nghĩa \"sự ～ quá mức\".</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みすぎに気をつけてください。</span>（Hãy cẩn thận đừng uống quá nhiều）</div><div class='gd-sec'><span class='gd-tag'>Xin lỗi</span>Rất hay nghe sau khi cãi nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきは言いすぎました。ごめんなさい。</span>（Lúc nãy mình nói quá lời rồi, xin lỗi bạn）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・「い」 của tính từ い nhất định phải bỏ: đúng là <span class='gd-jp'>高すぎる</span>, không phải 高いすぎる.<br>・Tính từ な không thêm な: đúng là <span class='gd-jp'>静かすぎる</span>, không phải 静かなすぎる.<br>・<b>「いい」 phải đổi thành 「よ」</b>: <span class='gd-jp'>よすぎる</span> (tốt quá). Nếu viết thành <span class='gd-jp'>いいすぎる</span>, người Nhật sẽ nghe thành <span class='gd-jp'>言いすぎる</span> (nói quá lời).<br>・「ない (không có)」 phải đổi thành <span class='gd-jp'>なさすぎる</span>: <span class='gd-jp'>時間がなさすぎる</span> (thời gian ít quá). Nhưng <span class='gd-jp'>少ない</span> thì theo quy tắc thường, là <span class='gd-jp'>少なすぎる</span>.<br>・すぎる thường mang cảm giác \"vượt quá mức, không hay lắm\". Giới trẻ trong văn nói có dùng <span class='gd-jp'>かわいすぎる</span> để khen người khác, nhưng bình thường muốn nói \"ngon lắm\", \"đẹp lắm\" thì dùng <span class='gd-jp'>とても</span> sẽ an toàn hơn.</div><div class='gd-h'>Phân biệt với các mẫu na ná</div><div class='gd-sec'>Trong tiếng Việt, \"quá\" đôi khi chỉ mang nghĩa \"rất\" (ví dụ \"tuyệt quá\", \"đẹp quá\"), nên rất dễ dịch hết thành すぎる. Hãy xem cùng một tình huống:<br><span class='gd-jp'>このかばんはとても高いです。</span>（Cái túi này rất đắt）: chỉ đang mô tả là nó đắt.<br><span class='gd-jp'>このかばんは高すぎます。</span>（Cái túi này đắt quá）: đã vượt quá mức bạn chấp nhận được, ngụ ý là \"mình sẽ không mua\".</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu phía sau nối được với \"nên không được / nên có vấn đề\" thì mới dùng すぎる; chỉ muốn nói mức độ cao thì dùng とても.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Kết hợp với 「〜ないようにする」 sẽ ra câu mà bác sĩ rất hay nói: <span class='gd-jp'>飲みすぎないようにしてください。</span>（Hãy chú ý đừng uống quá nhiều）</div>","n4-1":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜までに」nghĩa là <b>「chậm nhất là trước ~ (phải làm xong)」</b>, tức là thời hạn chót. Ví dụ trên giấy báo thanh toán ghi “Vui lòng thanh toán trước ngày 10 tháng 5”, chữ “trước” đó chính là までに. Điểm mấu chốt là <b>phải làm xong một việc trước mốc thời gian đó</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói về thời hạn</span>Thầy cô, cấp trên hay cửa hàng nói với bạn “chậm nhất khi nào phải xong”.</div><div class='gd-ex-line'>・<span class='gd-jp'>レポートは金曜日までに出してください。</span>（Báo cáo hãy nộp trước thứ Sáu nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにお願いします。</span>（Nhờ bạn làm xong trước ngày mai nhé）</div><div class='gd-sec'><span class='gd-tag'>Mục tiêu của bản thân</span>Tự đặt cho mình một thời hạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに駅に着きたい。</span>（Mình muốn đến ga trước 5 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏までに5キロやせたい。</span>（Mình muốn giảm 5 ký trước mùa hè）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Giờ giấc, ngày tháng, sự kiện</b> thì thêm までに trực tiếp:<br><span class='gd-pair'><span class='gd-jp'>3時</span> → <span class='gd-jp'>3時までに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験までに</span></span><br><b>Động từ</b> dùng dạng nguyên mẫu như trong từ điển (辞書形) rồi thêm までに, nghĩa là “trước khi ~ xảy ra”:<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るまでに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>母が帰るまでに部屋を片付けます。</span>（Mình sẽ dọn xong phòng trước khi mẹ về）</div><div class='gd-h'>Phân biệt với cặp dễ nhầm</div><div class='gd-sec'>Chỉ khác một chữ「に」mà nghĩa khác khá nhiều.<br><b>まで</b>＝hành động <b>diễn ra liên tục</b> cho đến mốc đó thì mới dừng.<br><b>までに</b>＝<b>làm xong</b> một việc <b>trước</b> mốc đó, làm xong là kết thúc.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（Mình đợi đến 5 giờ: đợi liên tục từ giờ cho tới 5 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>5時までに来てください。</span>（Hãy đến trước 5 giờ: 4 giờ hay 4 rưỡi đến đều được）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時まで勉強します。</span>（Mình học đến 10 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時までにお風呂に入ります。</span>（Mình sẽ đi tắm trước 10 giờ）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu nói được “liên tục ~ cho đến …” thì dùng <b>まで</b>; nếu nói được “chậm nhất trước … phải ~ xong” thì dùng <b>までに</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi muốn nói “làm liên tục cho đến thời điểm đó” (như đợi đến 5 giờ, học đến 10 giờ) thì phải dùng まで, không dùng までに. Ví dụ <span class='gd-jp'>5時までに待ちます</span> là sai, phải nói <span class='gd-jp'>5時まで待ちます</span>. Nhưng nếu là “làm xong trước một thời điểm” thì dùng までに được, như <span class='gd-jp'>試験までに勉強しておきます</span> (học xong bài trước kỳ thi), người Nhật nói câu kiểu này rất thường xuyên.<br>・<span class='gd-jp'>金曜日までに</span> thường bao gồm cả ngày thứ Sáu, nên nộp vào thứ Sáu vẫn đúng hạn, không nhất thiết phải nộp hôm thứ Năm.<br>・Phía trước là động từ thì phải dùng dạng nguyên mẫu: nói <span class='gd-jp'>日本に来るまでに</span>, không nói「来たまでに」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「は」phía sau thành <span class='gd-jp'>までには</span>, sắc thái trở thành “ít nhất là trước ~”: <span class='gd-jp'>夜までには帰ります。</span>（Chậm nhất là tối thì mình chắc chắn sẽ về）</div>","n4-4":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AはBより～」nghĩa là <b>「A ~ hơn B」</b>. <span class='gd-jp'>東京は大阪より人が多い。</span> nghĩa là “Tokyo đông người hơn Osaka”.<br>Khác biệt lớn nhất nằm ở <b>thứ tự</b>: tiếng Việt đặt “hơn B” <b>sau</b> tính từ, còn tiếng Nhật thì <span class='gd-jp'>より</span> dính ngay <b>sau B</b> và B～より đứng <b>trước</b> tính từ, giống như nói “so với B thì A ~” vậy.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chủ thể A thêm <span class='gd-jp'>は</span>, B được đem ra so sánh thêm <span class='gd-jp'>より</span>, cuối cùng đặt tính từ.<br><span class='gd-tag'>Tính từ い</span>thêm です ngay phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は昨日より暑いです。</span>（Hôm nay nóng hơn hôm qua）</div><div class='gd-sec'><span class='gd-tag'>Tính từ な</span>thêm です ngay phía sau; nói với bạn bè thì đổi thành だ hoặc bỏ luôn.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車はバスより便利です。</span>（Tàu điện tiện hơn xe buýt）</div><div class='gd-sec'><span class='gd-tag'>So sánh một khía cạnh</span>Khi muốn nói so sánh “về mặt nào”, dùng「～が＋tính từ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄は私より背が高いです。</span>（Anh trai cao hơn mình）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は私より料理が上手です。</span>（Chị gái nấu ăn giỏi hơn mình）</div><div class='gd-sec'><span class='gd-tag'>Cũng nối được với hành động</span>Phía sau không nhất thiết là tính từ, cũng có thể là “làm như thế nào”.</div><div class='gd-ex-line'>・<span class='gd-jp'>弟は私よりよく食べます。</span>（Em trai ăn nhiều hơn mình）</div><div class='gd-sec'>Bạn cũng sẽ nghe thấy <span class='gd-jp'>よりも</span>, nghĩa giống nhau, chỉ là sắc thái nhấn mạnh hơn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>より dính sau ai thì người đó là bên bị so sánh (kém hơn).</b> Nếu dịch thẳng theo thứ tự tiếng Việt rất dễ đặt sai chỗ: <span class='gd-jp'>東京より大阪は人が多い</span> thành “Osaka đông người hơn Tokyo”, nghĩa bị đảo ngược hoàn toàn.<br>・Tính từ <b>không cần biến đổi</b>, cũng không cần cố thêm “hơn”, “còn … hơn”. Tiếng Việt hay nói “cao hơn”, nhưng tiếng Nhật chỉ cần <span class='gd-jp'>高いです</span> là đủ. Nếu thêm <span class='gd-jp'>もっと</span> thì nghĩa lại thành “cả hai đều cao, A còn cao hơn nữa”.<br>・So sánh về khía cạnh nào thì dùng <span class='gd-jp'>が</span>: nói <span class='gd-jp'>背が高い</span>, <span class='gd-jp'>気温が高い</span>, đừng viết thành を.<br>・Muốn nói “A không ~ bằng B”, người Nhật thường dùng <span class='gd-jp'>ほど…ない</span>, ít khi nói「より～くない」.</div><div class='gd-h'>Phân biệt với cặp dễ nhầm</div><div class='gd-sec'>Cùng là so sánh dân số Tokyo và Osaka:<br><b>AはBより</b>＝đang giới thiệu A là chủ thể, tiện thể lấy B ra so: <span class='gd-jp'>東京は大阪より人が多いです。</span>（Tokyo đông người hơn Osaka）<br><b>BよりAのほうが</b>＝đặt hai bên cạnh nhau rồi <b>chọn A</b>, thường dùng để trả lời câu hỏi “bên nào ~ hơn?”: <span class='gd-jp'>大阪より東京のほうが人が多いです。</span>（So với Osaka thì Tokyo đông người hơn）<br><b>BほどAない</b>＝nói ngược lại là “không ~ bằng”: <span class='gd-jp'>大阪は東京ほど人が多くないです。</span>（Osaka không đông người bằng Tokyo）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: chỉ đơn thuần mô tả “A ~ hơn B” thì dùng <span class='gd-jp'>AはBより</span>; cần chọn một trong hai thì dùng <span class='gd-jp'>のほうが</span>; muốn nói “không ~ bằng” thì dùng <span class='gd-jp'>ほど…ない</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hỏi người khác “bên nào ~ hơn?”: <span class='gd-jp'>電車とバスとどちらが便利ですか。</span>（Tàu điện và xe buýt, bên nào tiện hơn?）Khi trả lời thì dùng <span class='gd-jp'>～より…ほうが</span>. Nếu có từ ba đối tượng trở lên và muốn chọn số một, hãy học tiếp <span class='gd-jp'>～でいちばん</span>.</div>","n4-6":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜方」tương đương với <b>「cách ~」</b> trong tiếng Việt: cách viết, cách đọc, cách dùng, cách ăn. Nó biến một động tác thành «cách làm việc đó», và rất hay dùng khi hỏi «cái này dùng thế nào», «đi đến đó bằng cách nào».</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Đổi động từ sang dạng ます, <b>bỏ ます đi</b>, rồi thêm <b>方（かた）</b>.<br><b>Nhóm 1 (động từ 五段) và nhóm 2 (động từ 一段)</b> đều làm giống nhau:<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → bỏ ます → <span class='gd-jp'>書き方</span></span>（cách viết）<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読み方</span></span>（cách đọc）<span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使い方</span></span>（cách dùng）<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べ方</span></span>（cách ăn）<span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見方</span></span>（cách nhìn）</div><div class='gd-sec'><b>Nhóm 3 (する・来る) cần nhớ riêng</b>:<br>・<span class='gd-jp'>する</span> đổi thành <span class='gd-jp'>仕方</span>（しかた）.<br>・Với động từ dạng «danh từ＋する», bạn nói <b>danh từ＋の＋仕方</b>: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強の仕方</span></span><span class='gd-pair'><span class='gd-jp'>掃除する</span> → <span class='gd-jp'>掃除の仕方</span></span><br>・<span class='gd-jp'>来る</span> là <span class='gd-jp'>来方</span>（きかた）, nhưng thường nghe <span class='gd-jp'>行き方</span> hơn.</div><div class='gd-h'>Những cách dùng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Hỏi cách làm</span>Bạn không biết làm thế nào nên nhờ người khác chỉ.</div><div class='gd-ex-line'>・<span class='gd-jp'>この漢字の読み方を教えてください。</span>（Xin hãy chỉ tôi cách đọc chữ Hán này）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅への行き方がわかりません。</span>（Tôi không biết đi đến ga bằng cách nào）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の勉強の仕方を教えてください。</span>（Xin hãy chỉ tôi cách học tiếng Nhật）</div><div class='gd-sec'><span class='gd-tag'>Nói về cách làm của ai đó</span>Không nhất định là «phương pháp», mà còn có thể là <b>dáng vẻ, thói quen</b> khi người đó làm việc này.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は話し方がやさしいです。</span>（Anh ấy có cách nói chuyện rất dịu dàng）</div><div class='gd-ex-line'>・<span class='gd-jp'>箸の持ち方がきれいですね。</span>（Bạn cầm đũa đẹp ghê, rất chuẩn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>を phải đổi thành の</b>. 「〜方」đã thành danh từ rồi nên phía trước không dùng を nữa: <span class='gd-pair'><span class='gd-jp'>本を読む</span> → <span class='gd-jp'>本の読み方</span></span>, không phải 「本を読み方」.<br>・「に／へ」thường đổi thành「への」: <span class='gd-pair'><span class='gd-jp'>駅に行く</span> → <span class='gd-jp'>駅への行き方</span></span>.<br>・Đã là danh từ thì phía sau nối với <span class='gd-jp'>が</span>、<span class='gd-jp'>を</span>: <span class='gd-jp'>使い方がわかりません</span>、<span class='gd-jp'>書き方を教えてください</span>.<br>・Ở đây 方 đọc là <b>かた</b>, không biến thành がた: <span class='gd-jp'>書き方</span> đọc là かきかた.<br>・Với các động từ như 勉強する、掃除する, đừng làm theo công thức để ra 「勉強し方」, hãy nói <span class='gd-jp'>勉強の仕方</span>.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'>Cùng một chữ Hán「方」, trong <span class='gd-jp'>〜ほうがいいです</span> lại đọc là <b>ほう</b> và nghĩa hoàn toàn khác.<br><span class='gd-jp'>書き方を教えてください。</span>（Xin hãy chỉ tôi cách viết: phương pháp）<br><span class='gd-jp'>名前を書いたほうがいいです。</span>（Bạn nên viết tên vào: lời khuyên）</div><div class='gd-warn'>Mẹo nhận biết: phía trước là «dạng ます bỏ ます» (書き、読み) thì đọc かた ＝ cách ~; phía trước là dạng た, dạng ない hoặc dạng từ điển (書いた、書かない) thì đọc ほう ＝ so sánh, khuyên nhủ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜やすい・〜にくい」cũng ghép bằng cách bỏ ます của dạng ます rồi nối vào, nên bạn có thể nhớ chung luôn: <span class='gd-jp'>このペンは書きやすいです。</span>（Cây bút này dễ viết）</div>","n4-9":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ことができます」tương đương với <b>«biết ~», «có thể ~», «được ~»</b> trong tiếng Việt. Cách làm rất đơn giản: thêm「こと」vào động từ để biến thành «việc đó», rồi phía sau nói «làm được (できます)».</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Năng lực</span>Bạn đã học, đã luyện nên biết làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話すことができます。</span>（Tôi biết nói tiếng Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノを弾くことができます。</span>（Tôi biết chơi piano）</div><div class='gd-sec'><span class='gd-tag'>Hoàn cảnh cho phép</span>Không phải bạn biết hay không, mà là nơi đó, quy định đó cho phép bạn làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>この図書館ではWi-Fiを使うことができます。</span>（Thư viện này có thể dùng Wi-Fi）</div><div class='gd-ex-line'>・<span class='gd-jp'>このカードはコンビニでも使うことができます。</span>（Thẻ này dùng được cả ở cửa hàng tiện lợi）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Động từ dùng <b>dạng từ điển</b> (dạng bạn tra thấy trong từ điển), phía sau thêm「ことができます」. Cả ba nhóm động từ đều giống nhau, không cần biến đổi riêng.<br>Nếu bạn chỉ nhớ dạng ます thì hãy đổi về dạng từ điển trước: <span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span> → <span class='gd-jp'>書くことができます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができます</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができます</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができます</span>（くる）</span></div><div class='gd-sec'>«Không biết, không thể»: đổi ます thành ません; «(lúc đó) đã làm được»: đổi thành ました:<br><span class='gd-jp'>漢字を書くことができません。</span>（Tôi không biết viết chữ Hán）<br><span class='gd-jp'>昨日はゆっくり休むことができました。</span>（Hôm qua tôi đã được nghỉ ngơi thoải mái）</div><div class='gd-sec'>Với danh từ chỉ <b>kỹ năng, thể thao, ngôn ngữ</b>, bạn cũng có thể nối thẳng「ができます」: <span class='gd-jp'>日本語ができます。</span>（Tôi biết tiếng Nhật）、<span class='gd-jp'>テニスができます。</span>（Tôi biết chơi tennis）<br>Danh từ thông thường thì không nối như vậy được, ví dụ không nói 「電車ができます」, mà phải nói <span class='gd-jp'>電車に乗ることができます</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước nhất định là dạng từ điển, không dùng thẳng dạng ます: không nói 「行きますことができます」, mà là <span class='gd-jp'>行くことができます</span>.<br>・「を」ban đầu vẫn giữ nguyên: <span class='gd-jp'>ピアノを弾くことができます</span>. Không cần đổi thành が.<br>・Đừng nhầm với «sẽ» chỉ dự đoán tương lai trong tiếng Việt, kiểu «Ngày mai trời sẽ mưa»: trường hợp này không dùng ことができます. Hãy nói <span class='gd-jp'>明日は雨が降るでしょう</span> hoặc <span class='gd-jp'>雨が降るかもしれません</span>.<br>・Bản thân <span class='gd-jp'>わかる</span> đã mang nghĩa «hiểu, nắm được» nên đừng thêm ことができます nữa: nói thẳng <span class='gd-jp'>日本語がわかります</span>.<br>・Muốn hỏi ngay tại chỗ «Tôi có thể ~ không?» để xin phép người kia, thường dùng <span class='gd-jp'>〜てもいいですか</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với mẫu trông giống</div><div class='gd-sec'><b>Thể khả năng</b> (話せる、書ける) có nghĩa gần như giống ことができます:<br><span class='gd-jp'>日本語を話すことができます。</span>（Tôi biết nói tiếng Nhật: trang trọng, hơi cứng）<br><span class='gd-jp'>日本語が話せます。</span>（Tôi biết nói tiếng Nhật: thường dùng trong hội thoại hằng ngày）<br>Thông báo, sách hướng dẫn, phần tự giới thiệu trang trọng hay gặp ことができます; trò chuyện với bạn bè thì phần lớn dùng thể khả năng. Khi bạn chưa biết đổi sang thể khả năng, dùng ことができます chắc chắn không sai.</div><div class='gd-sec'><b>〜てもいいです</b> là «(tôi) cho phép bạn làm»:<br><span class='gd-jp'>ここで写真を撮ることができます。</span>（Ở đây có thể chụp ảnh: giới thiệu quy định, mô tả tình huống）<br><span class='gd-jp'>ここで写真を撮ってもいいですよ。</span>（Bạn cứ chụp ảnh ở đây nhé: người nói cho phép bạn）</div><div class='gd-warn'>Mẹo nhận biết: nói về «biết hay không, có thể hay không» thì dùng ことができます hoặc thể khả năng; nói về «được phép hay không, có cho làm hay không» thì dùng てもいいです.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói khẩu ngữ hơn có cùng ý nghĩa: thể khả năng, ví dụ <span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span>.</div>","n4-38":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AはBほど～ない」tương đương với <b>「A không ～ bằng B」</b> trong tiếng Việt. Chỉ khác một chút về thứ tự: tiếng Nhật đặt B (vế so sánh) lên trước tính từ. <span class='gd-jp'>京都は東京ほど人が多くない</span>＝Kyoto <b>không</b> đông người <b>bằng</b> Tokyo. <span class='gd-jp'>ほど</span> mang nghĩa \"đến mức đó\", và phía sau nó <b>nhất định</b> phải là phủ định.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>A (chủ thể) は B (đối tượng so sánh) ほど ＋ dạng phủ định<br>Bạn cần chia dạng phủ định trước:</div><div class='gd-sec'><span class='gd-tag'>Tính từ い</span>Đổi 「い」 ở cuối thành 「くない」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → đổi い thành くない → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くない</span></span><br><b>Ngoại lệ:</b><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくない</span></span>(không được nói いくない)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の料理は前ほどよくない。</span>(Đồ ăn của quán này không ngon bằng trước đây)</div><div class='gd-sec'><span class='gd-tag'>Tính từ な</span>Thêm 「じゃない」 phía sau; trang trọng hơn thì dùng 「ではない」.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利じゃない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは前のほど便利じゃない。</span>(App này không tiện bằng cái trước)</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Dùng thể ない là được.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>私は兄ほど食べない。</span>(Mình không ăn khỏe bằng anh trai)</div><div class='gd-sec'>Muốn nói lịch sự, chỉ cần thêm です ở cuối:<span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないです</span></span></div><div class='gd-h'>Những dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>思ったほど～ない</span>「không ～ như mình nghĩ」, cực kỳ hay dùng hằng ngày.</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは思ったほど難しくなかった。</span>(Bài thi không khó như mình nghĩ)</div><div class='gd-sec'><span class='gd-tag'>前ほど～ない</span>「không ～ bằng trước đây」.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近は前ほど忙しくないです。</span>(Dạo này không bận bằng trước)</div><div class='gd-sec'><span class='gd-tag'>それほど～ない</span>Không nhắc đến B, nói thẳng 「không ～ đến mức đó」, rất tiện khi trả lời người khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語、難しい？</span>(Tiếng Nhật có khó không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>いや、それほど難しくないよ。</span>(Không, đâu có khó đến vậy)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau mẫu câu này <b>nhất định là phủ định</b>. <span class='gd-jp'>京都は東京ほど人が多いです</span> là sai; muốn nói \"đông hơn\" thì phải đổi sang dùng より.<br>・Trước <span class='gd-jp'>ほど</span> là vế <b>nổi trội hơn</b>. <span class='gd-jp'>今日は昨日ほど暑くない</span> nghĩa là hôm qua nóng hơn, đừng đọc ngược nhé.<br>・Phủ định của <span class='gd-jp'>いい</span> là <span class='gd-jp'>よくない</span>, viết いくない là sai.<br>・Cách nói này nhẹ nhàng, tế nhị hơn: <span class='gd-jp'>私の部屋は田中さんの部屋ほど広くない</span> (phòng mình không rộng bằng phòng của Tanaka) nghe lịch sự hơn là nói thẳng \"nhỏ hơn\".</div><div class='gd-h'>Phân biệt với mẫu dễ nhầm</div><div class='gd-sec'>Cùng một tình huống: hôm qua rất nóng, hôm nay mát hơn một chút.<br><b>より（～ほうが）</b>＝nói thẳng ai \"hơn\" ai, có thể đi với khẳng định:<br><span class='gd-jp'>昨日より今日のほうが涼しい。</span>(Hôm nay mát hơn hôm qua)<br><span class='gd-jp'>今日は昨日より涼しい。</span>(Hôm nay mát hơn hôm qua)<br><b>ほど～ない</b>＝nói A \"chưa đạt đến mức của B\", nhất định đi với phủ định:<br><span class='gd-jp'>今日は昨日ほど暑くない。</span>(Hôm nay không nóng bằng hôm qua)</div><div class='gd-warn'>Mẹo nhỏ: muốn nói \"hơn\" thì dùng より; muốn nói \"không ... bằng\" thì dùng ほど＋phủ định.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>So sánh hai đối tượng xong, bạn có thể học tiếp cách nói \"nhất trong một nhóm\": <span class='gd-jp'>クラスでいちばん背が高い。</span>(Cao nhất lớp)</div>","n4-39":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜でいちばん」tương đương với <b>「trong ～ thì ～ nhất」</b>. Trước tiên dùng 「で」 khoanh phạm vi lại (trong lớp, ở Nhật, trong nhà), rồi dùng 「いちばん」 để nói \"nhất\". Giống như tiếng Việt nói \"cao nhất lớp là Minh\", tiếng Nhật sẽ là <span class='gd-jp'>クラスでいちばん背が高いのは田中さんです</span>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phạm vi＋<b>で</b>＋<b>いちばん</b>＋tính từ<br><span class='gd-pair'><span class='gd-jp'>高い山</span> → <span class='gd-jp'>日本でいちばん高い山</span></span>(ngọn núi cao nhất Nhật Bản)</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山は日本でいちばん高い山です。</span>(Núi Phú Sĩ là ngọn núi cao nhất Nhật Bản)</div><div class='gd-ex-line'>・<span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span>(Trong lớp, bạn Tanaka cao nhất)</div><div class='gd-sec'>Sau 「いちばん」 không chỉ đi với tính từ mà còn đi với động từ, nghĩa là \"làm ～ nhất\":</div><div class='gd-ex-line'>・<span class='gd-jp'>家族で父がいちばん早く起きます。</span>(Trong nhà, bố dậy sớm nhất)</div><div class='gd-sec'>Nếu phạm vi là \"một loại đồ vật\" hoặc bạn đã liệt kê vài lựa chọn trước, thường dùng <b>の中で</b> (trong số ～):</div><div class='gd-ex-line'>・<span class='gd-jp'>スポーツの中で、サッカーがいちばん好きです。</span>(Trong các môn thể thao, mình thích bóng đá nhất)</div><div class='gd-h'>Những dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Hỏi 「cái nào ～ nhất」</span>Phạm vi＋で＋từ nghi vấn＋が＋いちばん～ですか。Từ nghi vấn đổi theo đối tượng: đồ vật dùng <span class='gd-jp'>何</span> (khi liệt kê lựa chọn thì dùng <span class='gd-jp'>どれ</span>), người dùng <span class='gd-jp'>だれ</span>, nơi chốn dùng <span class='gd-jp'>どこ</span>, thời gian dùng <span class='gd-jp'>いつ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>一年でいつがいちばん好きですか。</span>(Trong một năm, bạn thích khoảng thời gian nào nhất?)</div><div class='gd-ex-line'>・<span class='gd-jp'>夏がいちばん好きです。</span>(Mình thích mùa hè nhất)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でどこがいちばんよかったですか。</span>(Ở Nhật, bạn thấy nơi nào tuyệt nhất?)</div><div class='gd-sec'><span class='gd-tag'>「～ nhất là X」</span>Đặt đáp án ở cuối câu, nghe nhấn mạnh hơn:</div><div class='gd-ex-line'>・<span class='gd-jp'>家族でいちばん料理が上手なのは母です。</span>(Người nấu ăn giỏi nhất nhà là mẹ)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phạm vi phải dùng <b>で</b>, không dùng に: là <span class='gd-jp'>日本でいちばん</span>, không phải 日本にいちばん.<br>・Trong câu hỏi, sau từ nghi vấn phải dùng <b>が</b>, không dùng は: là <span class='gd-jp'>何がいちばん好きですか</span>, không phải 何はいちばん. Khi trả lời cũng quen dùng が: <span class='gd-jp'>夏がいちばん好きです</span>.<br>・Đối tượng của 「好き」「上手」 vẫn dùng が: <span class='gd-jp'>料理がいちばん上手です</span>, không phải 料理をいちばん上手.<br>・Bản thân 「いちばん」 đã có nghĩa \"nhất\", nên đừng thêm とても ở phía trước.<br>・Viết bằng kanji là <span class='gd-jp'>一番</span> cũng là cùng một từ, đọc giống hệt.</div><div class='gd-h'>Phân biệt với mẫu dễ nhầm</div><div class='gd-sec'>Mấu chốt là <b>so sánh mấy đối tượng</b>. Cùng là hỏi thích uống gì:<br><b>So sánh hai đối tượng</b> dùng 「どちら」＋「ほうが」（〜より…ほうが）:<br><span class='gd-jp'>コーヒーと紅茶とどちらが好きですか。</span>(Cà phê và trà đen, bạn thích cái nào hơn?)<br><span class='gd-jp'>コーヒーのほうが好きです。</span>(Mình thích cà phê hơn)<br><b>So sánh từ ba đối tượng trở lên</b> dùng 「どれ／何」＋「いちばん」:<br><span class='gd-jp'>コーヒーと紅茶とジュースの中で、どれがいちばん好きですか。</span>(Trong cà phê, trà đen và nước ép, bạn thích cái nào nhất?)<br><span class='gd-jp'>コーヒーがいちばん好きです。</span>(Mình thích cà phê nhất)</div><div class='gd-warn'>Mẹo nhỏ: tiếng Việt nói \"～ hơn\" là so sánh hai đối tượng, dùng ほうが; nói \"～ nhất\" là so sánh từ ba đối tượng trở lên hoặc cả một phạm vi, dùng いちばん.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「今まで～た中で、いちばん…」＝cái ～ nhất mà mình từng ～ cho đến giờ: <span class='gd-jp'>今まで食べた中で、これがいちばんおいしいです。</span>(Đây là món ngon nhất mà mình từng ăn cho đến giờ)</div>","n4-26":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てくる」「〜ていく」khá giống các từ chỉ hướng trong tiếng Việt như <b>“…tới / …lại đây”</b> và <b>“…đi / …tiếp”</b>. “Chạy tới” là <span class='gd-jp'>走ってくる</span>, “mang đi” là <span class='gd-jp'>持っていく</span>. Nói về thời gian cũng vậy: “trời lạnh dần lên” dùng てくる, “cứ làm tiếp” dùng ていく.<br>Bạn nhớ một câu này trước nhé: <b>くる＝hướng về phía mình, kéo dài đến tận bây giờ; いく＝rời xa mình, từ bây giờ trở về sau</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Chia động từ sang thể て, rồi nối với くる hoặc いく.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降って</span> → <span class='gd-jp'>降ってきた</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持って</span> → <span class='gd-jp'>持っていきます</span></span><br>Chữ くる phía sau chia giống như 「来る」 bình thường: <span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきました</span>、<span class='gd-jp'>てこない</span>. Trong mẫu câu này, nó thường được viết bằng hiragana.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Về phía này / về phía kia</span>Hành động tiến lại gần người nói thì dùng てくる, rời xa người nói thì dùng ていく.</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が走ってきた。</span>（Em trai chạy tới rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていきます。</span>（Có vẻ sắp mưa, nên mình mang ô theo）</div><div class='gd-sec'><span class='gd-tag'>Đi một lát rồi quay lại</span>てくる còn có thể mang nghĩa “đi làm xong một việc rồi quay lại chỗ này”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと飲み物を買ってきます。</span>（Mình đi mua chút đồ uống rồi về ngay）</div><div class='gd-sec'><span class='gd-tag'>Biến đổi dần cho đến bây giờ</span>Nói về sự thay đổi từ trước đến nay, thường dùng thể quá khứ <span class='gd-jp'>てきました</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が面白くなってきました。</span>（Dạo này mình thấy tiếng Nhật ngày càng thú vị）</div><div class='gd-sec'><span class='gd-tag'>Từ bây giờ trở đi</span>Tiếp tục từ lúc này về sau, hoặc ngày càng ～.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強していきます。</span>（Từ nay mình cũng sẽ tiếp tục học tiếng Nhật）</div><div class='gd-sec'><span class='gd-tag'>Bỗng xuất hiện, cảm nhận được</span>Một thay đổi bắt đầu xuất hiện và bạn nhận ra nó, như trời mưa, đói bụng, buồn ngủ.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（A, mưa rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（Bụng bắt đầu đói rồi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>行ってきます</span> khi ra khỏi nhà có nghĩa là “đi rồi sẽ quay về”, nên mới dịch là “Tôi đi đây nhé”.<br>・Dùng “đến” hay “đi” phải xem <b>người nói đang ở đâu</b>. Khi mang đồ đến nhà người khác, tiếng Việt hay nói “mình mang qua cho bạn”, còn tiếng Nhật thường nói <span class='gd-jp'>持っていきます</span>, vì đồ vật đang rời xa chỗ của bạn.<br>・<span class='gd-jp'>雨が降ってきた</span> nghĩa là “trời bắt đầu mưa”, không phải “mưa bay về phía mình”.<br>・Chữ 「きた」 trong <span class='gd-jp'>てきた</span> đọc là きた, còn thể phủ định <span class='gd-jp'>てこない</span> đọc là こない.<br>・Khi nói chuyện thường ngày, <span class='gd-jp'>ていく</span> hay được rút gọn thành <span class='gd-jp'>てく</span>, ví dụ <span class='gd-jp'>持ってく</span>. Đây là cách nói khẩu ngữ.</div><div class='gd-h'>Phân biệt với những mẫu nhìn giống nhau</div><div class='gd-sec'>Cùng nói về thời tiết trở lạnh:<br>・<span class='gd-jp'>寒くなった。</span>（Trời lạnh rồi: chỉ nói kết quả）<br>・<span class='gd-jp'>寒くなってきた。</span>（Trời dần lạnh lên: cảm nhận được nó đang thay đổi dần）<br>・<span class='gd-jp'>これから寒くなっていく。</span>（Sắp tới sẽ càng ngày càng lạnh: nhìn về phía sau này）<br><br>Cùng nói về việc bắt đầu mưa:<br>・<span class='gd-jp'>雨が降り始めた。</span>（Trời bắt đầu mưa: chỉ đơn thuần nói là bắt đầu）<br>・<span class='gd-jp'>雨が降ってきた。</span>（Mưa rồi đây: mang cảm giác “mình vừa nhận ra”, ngẩng lên thấy mưa thì hay nói thế này nhất）</div><div class='gd-warn'>Mẹo nhỏ để chọn: chỉ nói kết quả thì dùng 「なった」; cảm giác “đã dần thay đổi đến bây giờ” thì dùng 「てきた」; hướng mắt về “phía sau” thì dùng 「ていく」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Kết hợp với 「ようになる」 bạn có thể nói về khả năng được hình thành dần dần: <span class='gd-jp'>日本語が少し話せるようになってきた。</span>（Mình dần nói được một chút tiếng Nhật rồi）</div>","n4-27":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Ba từ này giống như <b>“bắt đầu ～”, “cứ ～ mãi”, “～ xong”</b> trong tiếng Việt. Một hành động được chia thành ba đoạn: vừa bắt đầu, đang tiếp diễn, đã làm xong.<br><span class='gd-jp'>読みはじめる</span>＝bắt đầu đọc<br><span class='gd-jp'>読み続ける</span>＝đọc mãi, đọc tiếp<br><span class='gd-jp'>読み終わる</span>＝đọc xong</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước tiên chia động từ sang thể ます, <b>bỏ ます đi</b>, rồi gắn trực tiếp phần còn lại với <span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span> hoặc <span class='gd-jp'>終わる</span>.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読みます</span></span> → bỏ ます → <span class='gd-pair'><span class='gd-jp'>読み</span> → <span class='gd-jp'>読みはじめる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span> → bỏ ます → <span class='gd-pair'><span class='gd-jp'>食べ</span> → <span class='gd-jp'>食べ続ける</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span> → bỏ ます → <span class='gd-pair'><span class='gd-jp'>勉強し</span> → <span class='gd-jp'>勉強し終わる</span></span></div><div class='gd-sec'>Sau khi gắn xong, từ phía sau chia theo quy tắc riêng của nó:<br><span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span> là nhóm 2 (động từ một đoạn): <span class='gd-pair'><span class='gd-jp'>読みはじめる</span> → <span class='gd-jp'>読みはじめました</span></span><br><span class='gd-jp'>終わる</span> là nhóm 1 (động từ năm đoạn): <span class='gd-pair'><span class='gd-jp'>読み終わる</span> → <span class='gd-jp'>読み終わりました</span></span><br>「はじめる」 viết bằng kanji <span class='gd-jp'>始める</span> cũng được, nhưng khi đứng sau động từ thì thường viết bằng hiragana.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>はじめる: bắt đầu</span>Một hành động bắt đầu từ khoảnh khắc này. Việc do người làm hay hiện tượng tự nhiên như thời tiết đều dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年から日本語を勉強しはじめました。</span>（Mình bắt đầu học tiếng Nhật từ năm ngoái）</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降りはじめた。</span>（A, trời bắt đầu mưa rồi）</div><div class='gd-sec'><span class='gd-tag'>続ける: cứ ~ mãi, tiếp tục</span>Hành động không dừng lại mà cứ tiếp diễn. Thường đi cùng 「ずっと」 hoặc khoảng thời gian.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は1時間も話し続けた。</span>（Anh ấy nói liền một tiếng đồng hồ）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語を勉強し続けたいです。</span>（Sau này mình cũng muốn tiếp tục học tiếng Nhật）</div><div class='gd-sec'><span class='gd-tag'>終わる: làm xong</span>Một việc có điểm kết thúc đã được làm đến cùng, như đọc xong một cuốn sách, ăn xong một bữa cơm.</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、やっと読み終わった。</span>（Cuốn sách này cuối cùng mình cũng đọc xong rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ終わったら、お皿を洗ってね。</span>（Ăn xong thì rửa đĩa nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nhất định phải nối với <b>thể ます đã bỏ ます</b>. <span class='gd-jp'>読むはじめる</span>、<span class='gd-jp'>読んではじめる</span> đều sai, phải nói <span class='gd-jp'>読みはじめる</span>.<br>・Dù chủ ngữ là hiện tượng tự nhiên như mưa, gió thì vẫn dùng <span class='gd-jp'>はじめる</span>: <span class='gd-jp'>雨が降りはじめた</span>, không nói 「降りはじまった」.<br>・<span class='gd-jp'>終わる</span> dùng cho hành động có điểm kết thúc là “làm xong”, như đọc, ăn, viết, xem. Mưa tạnh thì không nói 「降り終わった」, mà dùng <span class='gd-jp'>雨がやんだ</span>.<br>・<span class='gd-jp'>終わる</span> là nhóm 1, thể ます là <span class='gd-jp'>終わります</span>; còn <span class='gd-jp'>はじめる</span>、<span class='gd-jp'>続ける</span> là nhóm 2, thể ます là <span class='gd-jp'>はじめます</span>、<span class='gd-jp'>続けます</span>, đừng chia lẫn lộn.</div><div class='gd-h'>Phân biệt với những mẫu nhìn giống nhau</div><div class='gd-sec'><b>〜ている và 〜続けている</b><br><span class='gd-jp'>子どもが泣いている。</span>（Đứa bé đang khóc）: chỉ tả việc đang khóc lúc này.<br><span class='gd-jp'>子どもがずっと泣き続けている。</span>（Đứa bé cứ khóc mãi không thôi）: nhấn mạnh đã khóc rất lâu mà vẫn chưa dừng.</div><div class='gd-sec'><b>〜終わる và 〜てしまう</b><br>Dịch sang tiếng Việt đều có thể thành “ăn hết rồi”, nhưng trọng tâm khác nhau.<br><span class='gd-jp'>ケーキを食べ終わった。</span>（Ăn xong bánh rồi）: chỉ nói hành động ăn đã kết thúc, giọng trung tính.<br><span class='gd-jp'>弟のケーキを食べてしまった。</span>（Mình lỡ ăn mất bánh của em trai rồi）: mang cảm giác “ăn sạch rồi” hoặc “chết rồi, lỡ tay mất”.</div><div class='gd-warn'>Mẹo nhỏ để chọn: chỉ nói “đang làm” thì dùng ている, muốn nhấn mạnh “không hề dừng” thì dùng 続ける; chỉ nói “làm xong rồi” thì dùng 終わる, còn mang tâm trạng “ăn sạch rồi” hay “ôi hỏng rồi” thì dùng てしまう.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói những thời điểm chi tiết hơn như “sắp bắt đầu”, “đang làm”, “vừa làm xong”, bạn có thể học tiếp <span class='gd-jp'>〜ところです</span>: <span class='gd-jp'>今から食べるところです。</span>（Mình sắp bắt đầu ăn đây）</div>","n4-40":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜と言います」nghĩa là <b>「ai đó nói rằng ～」</b>. <span class='gd-jp'>言う</span> là \"nói\", còn <span class='gd-jp'>と</span> đứng trước nó là dấu hiệu báo cho người nghe biết \"nội dung lời nói kết thúc ở đây\", tác dụng giống dấu ngoặc kép trong tiếng Việt.</div><div class='gd-h'>Hai cách nói: dẫn nguyên văn và thuật lại bằng lời của mình</div><div class='gd-sec'><span class='gd-tag'>Dẫn nguyên văn</span>Đặt lời người ta nói vào trong 「」 mà không sửa một chữ nào, rồi thêm <span class='gd-jp'>と言いました</span> phía sau. Nếu lời gốc có ます thì giữ nguyên ます.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は「明日テストをします」と言いました。</span>(Thầy/cô nói: \"Ngày mai sẽ có bài kiểm tra.\")</div><div class='gd-sec'><span class='gd-tag'>Thuật lại bằng lời của mình</span>Không dùng 「」, mà đổi nội dung sang <b>thể thường</b> (cách nói thân mật giữa bạn bè, không có ます hay です) rồi mới nối với <span class='gd-jp'>と</span>.<br><span class='gd-pair'><span class='gd-jp'>テストをします</span> → <span class='gd-jp'>テストをする</span></span><br><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は明日テストをすると言いました。</span>(Thầy/cô nói ngày mai sẽ có bài kiểm tra)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は行かないと言いました。</span>(Anh ấy nói là anh ấy không đi)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Khi thuật lại, động từ và tính từ đuôi い ở thể thường thì nối thẳng với <span class='gd-jp'>と</span>; còn <b>danh từ và tính từ đuôi な phải thêm \"だ\"</b>.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>好きです</span> → <span class='gd-jp'>好きだと言いました</span></span><br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だと言いました</span></span></div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>と言っていました</span>Rất tự nhiên khi nhắn lại lời của người khác. Nghĩa là \"(lúc trước) người ấy có nói là ～ đấy\".</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日は来ないと言っていました。</span>(Anh Tanaka nói hôm nay anh ấy sẽ không đến)</div><div class='gd-sec'><span class='gd-tag'>Tự giới thiệu</span>Dùng để nói tên của mình.</div><div class='gd-ex-line'>・<span class='gd-jp'>はじめまして、林と言います。</span>(Rất vui được gặp bạn, tôi tên là Lâm/Hayashi)</div><div class='gd-sec'><span class='gd-tag'>Hỏi \"nói thế nào\"</span>Học tiếng Nhật thì chắc chắn bạn sẽ dùng đến.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本語で何と言いますか。</span>(Cái này nói bằng tiếng Nhật là gì?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi dẫn <b>nội dung</b> lời nói (một câu, một đoạn), phía sau dùng <b>と</b>, không dùng を: × <span class='gd-jp'>明日テストをするを言いました</span> → ○ <span class='gd-jp'>明日テストをすると言いました</span>. Tuy nhiên nếu phía trước là danh từ, như <span class='gd-jp'>名前を言う</span> (nói tên), <span class='gd-jp'>お礼を言う</span> (nói lời cảm ơn) thì dùng を. Hai trường hợp này bạn nhớ phân biệt nhé.<br>・<span class='gd-jp'>言う</span> tuy viết là いう nhưng thực tế đọc là <b>ゆう</b>.<br>・Lỗi hay gặp nhất khi thuật lại là quên thêm だ sau danh từ và tính từ đuôi な: phải nói <span class='gd-jp'>雨だと言っていました</span>.<br>・Khi thuật lại, \"tôi\" phải đổi thành người khác: lời gốc của anh ấy là 「<span class='gd-jp'>私は行きません</span>」, bạn thuật lại thành \"anh ấy nói <b>anh ấy</b> không đi\". Tiếng Nhật chỉ cần nói <span class='gd-jp'>彼は行かないと言いました</span>, không cần đặt thêm 「私」.<br>・Khi nói về lời của thầy cô, cấp trên trong hoàn cảnh trang trọng, người ta sẽ đổi sang <span class='gd-jp'>おっしゃいました</span> kính trọng hơn. Bạn sẽ gặp lại khi học kính ngữ.</div><div class='gd-h'>Phân biệt với cấu trúc na ná</div><div class='gd-sec'>Cùng là thuật lại chuyện \"anh Tanaka không đến\":<br><span class='gd-jp'>田中さんは来ないと言っていました。</span>(Anh Tanaka <b>đích thân nói</b> là anh ấy không đến)<br><span class='gd-jp'>田中さんは来ないそうです。</span>(<b>Nghe nói</b> anh Tanaka không đến)<br>「と言う」nói rõ <b>ai là người đã nói</b>; còn 「そうです」chỉ là \"nghe nói\", tin có thể do chính anh Tanaka nói, cũng có thể là người khác truyền lại, trọng tâm không nằm ở người nói.</div><div class='gd-warn'>Mẹo nhỏ: muốn nói \"ai đó nói rằng ～\" thì dùng と言う; chỉ muốn nói \"nghe nói ～\" thì dùng そうです.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi <span class='gd-jp'>言います</span> thành <span class='gd-jp'>思います</span> là thành \"tôi nghĩ rằng ～\": <span class='gd-jp'>明日は雨だと思います。</span>(Tôi nghĩ ngày mai trời sẽ mưa). Cách nối hoàn toàn giống, cũng phải thêm だ.<br>Khi nhắn lại cho bạn bè, người ta thường rút gọn <span class='gd-jp'>と言っていた</span> thành <span class='gd-jp'>って</span>: <span class='gd-jp'>田中さん、来ないって。</span>(Tanaka bảo là không đến đó)</div>","n4-41":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜と思います」nghĩa là <b>「tôi nghĩ là ～」「tôi thấy ～」</b>. Khi nói quan điểm của mình hay đoán một việc sẽ ra sao, bạn đều dùng nó. Người Nhật rất hay dùng, kể cả khi đã khá chắc chắn họ vẫn thêm と思います để câu nói nghe đỡ cứng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nêu ý kiến</span>Cảm nhận, đánh giá về một việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいと思います。</span>(Tôi thấy bát ramen này ngon)</div><div class='gd-sec'><span class='gd-tag'>Phỏng đoán</span>Không chắc một trăm phần trăm, nhưng bạn cảm thấy chắc là như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>(Tôi nghĩ ngày mai trời sẽ mưa)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったと思います。</span>(Tôi nghĩ chắc anh Tanaka đã về rồi)</div><div class='gd-sec'><span class='gd-tag'>Hỏi ý kiến người khác</span>Dùng「どう思いますか」, không cần học thêm mẫu câu nào khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>この服、どう思いますか。</span>(Bạn thấy bộ đồ này thế nào?)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước phải là <b>thể thường</b>, tức cách nói không có です, ます (dạng từ điển, ない, た...).<br>Động từ và tính từ đuôi い nối thẳng:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くと思います</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないと思います</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いと思います</span></span><br>Danh từ và tính từ đuôi な phải <b>thêm だ trước</b>:<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だと思います</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだと思います</span></span><br>Khi nói với bạn bè thì đổi 思います thành <b>思う</b>: <span class='gd-jp'>おいしいと思う。</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ, tính từ đuôi な quên thêm だ: phải nói <span class='gd-jp'>学生だと思います</span>, không phải 「学生と思います」.<br>・Trước と không đặt です, ます: phải nói <span class='gd-jp'>おいしいと思います</span>, không phải 「おいしいですと思います」. Độ lịch sự đã nằm ở 「思います」 cuối câu rồi.<br>・Muốn nói \"tôi nghĩ anh ấy sẽ không đến\", tiếng Nhật đặt phủ định ngay trong mệnh đề trước と, giống như tiếng Việt: <span class='gd-jp'>彼は来ないと思います。</span> Còn nếu nói <span class='gd-jp'>来るとは思いません</span> thì là \"tôi đâu có nghĩ là anh ấy sẽ đến\", giọng mạnh hơn nhiều, nghe như đang phản bác.<br>・「と思います」chỉ dùng để nói <b>tôi</b> nghĩ gì. Muốn nói người khác nghĩ thế nào thì dùng「と思っています」: <span class='gd-jp'>母は私がまだ子どもだと思っています。</span>(Mẹ tôi nghĩ tôi vẫn còn là trẻ con)</div><div class='gd-h'>Phân biệt với cấu trúc na ná</div><div class='gd-sec'><b>行くと思います vs 行こうと思います</b>: chỉ khác một chữ nhưng nghĩa khác nhau nhiều.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、田中さんは行くと思います。</span>(Bữa tiệc ngày mai, tôi đoán anh Tanaka sẽ đi)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のパーティー、私も行こうと思います。</span>(Bữa tiệc ngày mai, tôi cũng định đi)</div><div class='gd-sec'>Phía trước là thể thường ＝ <b>đoán</b> sẽ ra sao; phía trước là thể ý chí (行こう、食べよう) ＝ <b>tôi định</b> làm.</div><div class='gd-sec'><b>と思います vs かもしれません</b>: mức độ chắc chắn khác nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>(Tôi nghĩ ngày mai trời sẽ mưa: khá chắc)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降るかもしれません。</span>(Ngày mai có thể trời sẽ mưa: năm ăn năm thua)</div><div class='gd-warn'>Mẹo nhỏ: \"tôi nghĩ, tôi đoán\" dùng thể thường＋と思います; \"tôi định\" dùng thể ý chí＋と思います; chỉ là \"biết đâu chừng\" thì dùng かもしれません.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi phần phía trước sang thể ý chí là thành \"tôi định ～\": <span class='gd-jp'>来年、日本へ行こうと思います。</span>(Năm sau tôi định đi Nhật)</div>","n4-42":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ようと思います」nghĩa là <b>「Tôi định ～」「Tôi đang nghĩ là sẽ ～」</b>. Bạn dùng nó để nói với người khác về kế hoạch đã có sẵn trong đầu, ví dụ “Cuối tuần này tôi định dọn phòng”.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は部屋を掃除しようと思います。</span>（Cuối tuần tôi định dọn phòng）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Trước hết đổi động từ sang <b>thể ý chí</b> (dạng 「〜よう」「〜こう」 mang nghĩa “nào, cùng ～ nhé”), rồi thêm <span class='gd-jp'>と思います</span> phía sau. Cách chia thể ý chí bạn xem ở bài n4-51, ở đây mình ôn nhanh lại:<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: <span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành こ, thêm う → <span class='gd-jp'>行こうと思います</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: <span class='gd-pair'><span class='gd-jp'>寝る</span> → bỏ る, thêm よう → <span class='gd-jp'>寝ようと思います</span></span><br><b>Nhóm 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しようと思います</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ようと思います</span>（こよう）</span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ようと思います</span>Nói ra dự định của mình ngay lúc này, thường là ý nghĩ vừa mới nảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝ようと思います。</span>（Hôm nay tôi định đi ngủ sớm）</div><div class='gd-sec'><span class='gd-tag'>ようと思っています</span>Dự định này <b>đã nằm trong đầu bạn một thời gian rồi</b>, rất hay dùng khi nói về kế hoạch dài hạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>来年、日本へ留学しようと思っています。</span>（Tôi định sang Nhật du học vào năm sau）</div><div class='gd-sec'><span class='gd-tag'>ようかと思っています</span>Có thêm 「か」 ở giữa, nghĩa đổi thành <b>「Tôi đang nghĩ xem có nên ～ không」</b>, tức là vẫn còn đang phân vân.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事を辞めようかと思っています。</span>（Tôi đang nghĩ xem có nên nghỉ việc không）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>行くと思います</span> và <span class='gd-jp'>行こうと思います</span> chỉ khác nhau một chút thôi nhưng nghĩa khác xa: câu đầu là “tôi nghĩ (anh ấy) sẽ đi”, tức là phỏng đoán; câu sau mới là “tôi định đi”.<br>・“Tôi <b>không</b> định đi” không được nói là <span class='gd-jp'>行かないと思います</span>, vì câu đó nghĩa là “tôi nghĩ là sẽ không đi”. Muốn nói “không định”, hãy dùng <span class='gd-jp'>行かないつもりです</span>.<br>・<span class='gd-jp'>〜ようと思います</span> chỉ dùng để nói về dự định của <b>chính mình</b>. Muốn nói về dự định của người khác, đổi sang <span class='gd-jp'>〜ようと思っています</span>: <span class='gd-jp'>兄は車を買おうと思っています。</span>（Anh trai tôi định mua xe）<br>・Khi hỏi người khác định làm gì, dùng <span class='gd-jp'>思っています</span> nghe tự nhiên hơn: <span class='gd-jp'>夏休みは何をしようと思っていますか。</span>（Kỳ nghỉ hè bạn định làm gì?）</div><div class='gd-h'>Phân biệt với những mẫu na ná nhau</div><div class='gd-sec'>Cùng là nói “đi Nhật”, nhưng ba cách nói cho cảm giác khác nhau:<br><b>たい</b> = đơn giản là “muốn”, một mong ước trong lòng, chưa chắc đã có kế hoạch: <span class='gd-jp'>日本へ行きたいです。</span>（Tôi muốn đi Nhật）<br><b>ようと思う</b> = “định”, đã có ý nghĩ đó rồi, nghe mềm hơn và còn chừa chỗ linh hoạt: <span class='gd-jp'>日本へ行こうと思います。</span>（Tôi định đi Nhật）<br><b>つもり</b> = kế hoạch khá chắc chắn, gần như đã quyết xong: <span class='gd-jp'>日本へ行くつもりです。</span>（Tôi dự định sẽ đi Nhật）</div><div class='gd-warn'>Mẹo nhỏ để chọn: chỉ là “muốn ～ quá” thì dùng たい; “định ～” thì dùng ようと思う; “đã lên kế hoạch xong là sẽ ～” thì dùng つもり. Khi nói “tôi muốn đi” bằng tiếng Việt, hãy dừng lại nghĩ một chút: đó là mong ước hay là dự định?</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi kế hoạch đã chốt hẳn, bạn có thể dùng 「〜ことにします」: <span class='gd-jp'>来年、日本へ行くことにしました。</span>（Tôi đã quyết định sang Nhật vào năm sau）</div>","n4-43":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜か（どうか）」là cách <b>lồng một câu hỏi vào trong câu</b>. Trong tiếng Việt, khi bạn nói “tôi không biết <b>anh ấy có đến hay không</b>”, đoạn ở giữa thật ra là một câu hỏi, chỉ là không được hỏi riêng ra thôi. Tiếng Nhật lúc này phải thêm 「か」 hoặc 「かどうか」 sau đoạn đó để báo cho người nghe biết: chỗ này là một câu hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が来るかどうか、分かりません。</span>（Tôi không biết anh ấy có đến hay không）</div><div class='gd-h'>Chia làm hai loại: có từ như “ai, ở đâu, cái gì” hay không</div><div class='gd-sec'><span class='gd-tag'>Không có từ nghi vấn</span>Câu trả lời chỉ là “có / không” thì dùng <b>かどうか</b>, tương đương “có ～ hay không”, “có phải ～ không”. Chỉ dùng 「か」 cũng được, văn nói hay nói như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>鍵をかけたかどうか、覚えていない。</span>（Tôi không nhớ mình đã khóa cửa hay chưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末に時間があるか、確認してください。</span>（Hãy xác nhận giúp xem cuối tuần bạn có rảnh không）</div><div class='gd-sec'><span class='gd-tag'>Có từ nghi vấn</span>Trong câu đã có các từ như <span class='gd-jp'>誰</span>、<span class='gd-jp'>どこ</span>、<span class='gd-jp'>何</span>、<span class='gd-jp'>いつ</span> thì <b>chỉ thêm 「か」</b>, không thêm どうか.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議が何時に始まるか、知っていますか。</span>（Bạn có biết mấy giờ cuộc họp bắt đầu không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレがどこか、教えてください。</span>（Làm ơn chỉ giúp tôi nhà vệ sinh ở đâu）</div><div class='gd-sec'>Những động từ hay đi sau nhất: <span class='gd-jp'>分からない</span>、<span class='gd-jp'>知っている</span>、<span class='gd-jp'>決まる</span>、<span class='gd-jp'>確認する</span>、<span class='gd-jp'>聞く</span>、<span class='gd-jp'>考える</span>、<span class='gd-jp'>覚えている</span>, đều mang nghĩa nhóm “biết, xác nhận, quyết định”.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Phía trước luôn dùng <b>thể thường</b> (tức là cách nói không có ます、です).<br>Động từ: <span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行くかどうか</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行ったかどうか</span></span><br>Tính từ い: <span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいかどうか</span></span><br>Danh từ và tính từ な: <b>không thêm だ</b>, nối thẳng với か. <span class='gd-pair'><span class='gd-jp'>本当です</span> → <span class='gd-jp'>本当かどうか</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かかどうか</span></span><br>Ngoài ra cũng có thể nói「<span class='gd-jp'>来るか来ないか</span>」, nghĩa giống với <span class='gd-jp'>来るかどうか</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tiếng Việt có sẵn “có ～ không” nên dễ quên, nhưng tiếng Nhật <b>nhất định phải có か</b>. Nói <span class='gd-jp'>彼が来る分かりません</span> là sai.<br>・Dù cả câu cần nói lịch sự, đoạn ở giữa vẫn dùng thể thường, sự lịch sự chỉ đặt ở cuối câu: phải nói <span class='gd-jp'>行くかどうか分かりません</span>, không nói「行きますかどうか」.<br>・Sau danh từ và tính từ な đừng thêm だ: phải nói <span class='gd-jp'>学生かどうか</span>, không nói「学生だかどうか」.<br>・Khi đã có từ nghi vấn thì không thêm どうか nữa: phải nói <span class='gd-jp'>どこがいいか</span>, không nói「どこがいいかどうか」.</div><div class='gd-h'>Phân biệt với những mẫu na ná nhau</div><div class='gd-sec'>Đều có 「か」 và đều mang chút không chắc chắn, nên người mới học hay nhầm với <b>かもしれない</b>.<br><span class='gd-jp'>彼は来るかどうか分からない。</span>（Không biết anh ấy có đến hay không: hoàn toàn không biết, chỉ là đang nói “chuyện này tôi không rõ”）<br><span class='gd-jp'>彼は来るかもしれない。</span>（Có thể anh ấy sẽ đến: bạn đang đoán và thấy có khả năng anh ấy đến）</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu phía sau còn có động từ kiểu 「分からない、確認する、教えて」 thì là かどうか; nếu câu kết thúc ở đó và mang nghĩa “có thể ～” thì là かもしれない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Kết hợp với「〜てみます」rất tiện: <span class='gd-jp'>行けるかどうか、先生に聞いてみます。</span>（Tôi sẽ hỏi thử thầy cô xem có đi được không）</div>","n4-44":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cảm giác trong lòng như 「muốn」「sợ quá」「lạnh quá」 thì chỉ người đó tự biết. Vì vậy khi nói về cảm giác của <b>người khác</b>, tiếng Nhật không nói thẳng 「anh ấy muốn」, mà nói 「anh ấy <b>thể hiện ra</b> dáng vẻ muốn」. Đó chính là 「〜がる」. Nó giống như tiếng Việt nói 「nó cứ đòi ~」, 「nó có vẻ sợ lắm」.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Người khác muốn gì đó</span>Em trai, bạn bè, trẻ con, thậm chí thú cưng: bạn nhìn là biết họ rất muốn có, rất muốn làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>弟が新しいゲーム機を欲しがっています。</span>(Em trai cứ muốn có máy chơi game mới)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はずっと日本へ行きたがっています。</span>(Cô ấy lúc nào cũng rất muốn đi Nhật)</div><div class='gd-sec'><span class='gd-tag'>Cảm giác của người khác</span>Sợ, lạnh, đau, ghét… đều có thể nhìn ra từ nét mặt và cử chỉ.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが注射を怖がっています。</span>(Đứa bé rất sợ tiêm)</div><div class='gd-ex-line'>・<span class='gd-jp'>娘は野菜を嫌がって、食べません。</span>(Con gái ghét rau nên không chịu ăn)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Chỉ những tính từ chỉ tình cảm, cảm giác mới đi được với 「がる」 (<span class='gd-jp'>欲しい</span>、<span class='gd-jp'>怖い</span>、<span class='gd-jp'>痛い</span>、<span class='gd-jp'>寒い</span>、<span class='gd-jp'>嫌だ</span>…).<br><b>Tính từ đuôi い</b>: bỏ 「い」 ở cuối, rồi thêm 「がる」.<br><span class='gd-pair'><span class='gd-jp'>欲しい</span> → <span class='gd-jp'>欲しがる</span></span><span class='gd-pair'><span class='gd-jp'>怖い</span> → <span class='gd-jp'>怖がる</span></span><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛がる</span></span></div><div class='gd-sec'><b>Muốn làm một việc gì đó</b>: đổi thành 「〜たい」 trước, rồi bỏ 「い」 và thêm 「がる」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きたい</span> → <span class='gd-jp'>行きたがる</span></span><span class='gd-pair'><span class='gd-jp'>働く</span> → <span class='gd-jp'>働きたい</span> → <span class='gd-jp'>働きたがる</span></span></div><div class='gd-sec'><b>Tính từ đuôi な</b>: bỏ 「だ」 trước, rồi thêm 「がる」, ví dụ <span class='gd-pair'><span class='gd-jp'>嫌だ</span> → <span class='gd-jp'>嫌がる</span></span><span class='gd-pair'><span class='gd-jp'>残念だ</span> → <span class='gd-jp'>残念がる</span></span>. Tính từ な dùng được kiểu này không nhiều, thường gặp chỉ có <span class='gd-jp'>嫌がる</span>、<span class='gd-jp'>残念がる</span>、<span class='gd-jp'>不思議がる</span>、<span class='gd-jp'>面倒がる</span>.<br>Lưu ý: <span class='gd-jp'>大きい</span> không phải cảm giác nên không thể nói ×<span class='gd-jp'>大きがる</span>; còn <span class='gd-jp'>好き</span> tuy là tình cảm nhưng cũng không nói ×<span class='gd-jp'>好きがる</span>.</div><div class='gd-sec'>Sau khi thành 「がる」, nó biến đổi như <span class='gd-jp'>帰る</span>, tức là động từ nhóm 1 (động từ ngũ đoạn): <span class='gd-jp'>がります</span>、<span class='gd-jp'>がりません</span>、<span class='gd-jp'>がっています</span>、<span class='gd-jp'>がった</span>.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>がっています</span>Khi nói 「hiện giờ người ấy đang rất muốn, đang rất sợ」, gần như luôn dùng dạng này. Nếu chỉ nói <span class='gd-jp'>欲しがります</span> thì nghe giống thói quen, xu hướng 「bình thường người ấy hay như vậy」.</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が散歩に行きたがっている。</span>(Chú chó đang muốn ra ngoài đi dạo)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Nói về bản thân thì không dùng がる</b>: tâm trạng của mình thì nói thẳng <span class='gd-jp'>私は新しいスマホが欲しいです</span>, không nói 「私は欲しがっています」. Ngược lại, tiếng Việt nói 「em ấy muốn」 rất tự nhiên, nhưng tiếng Nhật nói thẳng <span class='gd-jp'>弟は欲しいです</span> sẽ nghe là lạ, phải dùng 欲しがっています.<br>・<b>Trợ từ sẽ đổi</b>: <span class='gd-jp'>水が欲しい</span> khi thành がる thì dùng 「を」: <span class='gd-jp'>弟は水を欲しがっている</span>.<br>・<b>Hỏi trực tiếp người đối diện thì không dùng がる</b>: với bạn bè, cứ hỏi thẳng <span class='gd-jp'>何が食べたい？</span> (Bạn muốn ăn gì?) là được.<br>・<b>Đừng dùng với bề trên, cấp trên</b>: 「〜がる」 là quan sát từ bên ngoài rồi mô tả vẻ ngoài của người ta, nên dùng cho thầy cô, sếp sẽ giống như đang bình phẩm tâm trạng họ, không đủ lịch sự. Lúc này đừng nói 先生が帰りたがっています, cách nói tốt hơn là <span class='gd-jp'>先生は帰りたいとおっしゃっていました。</span>(Thầy nói là thầy muốn về rồi)</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là 「em trai muốn điện thoại mới」, nhưng ba cách nói khác nhau ở <b>tâm trạng của ai, và bạn biết bằng cách nào</b>:<br><b>欲しい</b>＝nói về tâm trạng của chính mình: <span class='gd-jp'>私は新しいスマホが欲しいです。</span>(Tôi muốn có điện thoại mới)<br><b>欲しがっている</b>＝người ấy đã nói ra, đã thể hiện ra: <span class='gd-jp'>弟は新しいスマホを欲しがっています。</span>(Em trai cứ đòi điện thoại mới)<br><b>欲しそう</b>＝người ấy không nói, bạn nhìn dáng vẻ rồi đoán: <span class='gd-jp'>弟は新しいスマホが欲しそうです。</span>(Em trai trông có vẻ muốn điện thoại mới)</div><div class='gd-warn'>Mẹo phân biệt: tâm trạng của mình dùng 「たい・欲しい」; người khác đã thể hiện ra thì dùng 「がっている」; chỉ nhìn nét mặt rồi đoán thì dùng 「そう」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi không muốn bình phẩm tâm trạng người khác, bạn có thể chuyển sang cách nói thuật lại: <span class='gd-jp'>姉は留学したいと言っています。</span>(Chị nói là chị muốn đi du học)</div>","n4-46":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なさい」 giống như câu mẹ hay nói: <b>「Đi ngủ ngay!」「Rửa tay cho sạch!」</b>. Nó có uy của người lớn nhưng không phải đang mắng. Đây là mệnh lệnh <b>từ trên xuống dưới</b>, bố mẹ nói với con, thầy cô nói với học sinh là phổ biến nhất.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Bố mẹ nói với con</span>Bảo con làm việc cần làm; các bà mẹ trong phim Nhật và anime ngày nào cũng nói câu này.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝なさい。</span>(Đi ngủ sớm đi)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を先にやりなさい。</span>(Làm bài tập trước đã)</div><div class='gd-sec'><span class='gd-tag'>Thầy cô nói với học sinh</span>Chỉ thị trong giờ học.</div><div class='gd-ex-line'>・<span class='gd-jp'>よく聞きなさい。</span>(Nghe cho kỹ)</div><div class='gd-sec'><span class='gd-tag'>Câu hỏi trong đề thi</span>Đề JLPT và đề thi ở trường Nhật rất hay viết như vậy; thấy là biết đó là chỉ thị 「hãy ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>正しいものを選びなさい。</span>(Hãy chọn đáp án đúng)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Đổi động từ sang thể ます trước, rồi <b>bỏ ます</b> và thêm なさい. Cả ba nhóm động từ đều giống nhau, không cần học thêm quy tắc riêng.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → bỏ ます → <span class='gd-jp'>行きなさい</span></span><br><span class='gd-pair'><span class='gd-jp'>洗います</span> → <span class='gd-jp'>洗いなさい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べなさい</span></span><span class='gd-pair'><span class='gd-jp'>寝ます</span> → <span class='gd-jp'>寝なさい</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強します</span> → <span class='gd-jp'>勉強しなさい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来なさい</span>（きなさい）</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nghe không dữ, nhưng <b>không phải cách nói lịch sự</b>. Nói 「<span class='gd-jp'>座りなさい</span>」 với thầy cô, cấp trên, khách hàng sẽ rất vô lễ; muốn nhờ người ta làm gì thì dùng 「<span class='gd-jp'>座ってください</span>」.<br>・<span class='gd-jp'>来なさい</span> đọc là <b>きなさい</b>, không phải こなさい.<br>・Muốn bảo người ta 「đừng ~」, なさい không có dạng phủ định, không thể ghép ない vào. Hãy đổi sang 「〜ないで」 hoặc 「〜てはいけません」, ví dụ: <span class='gd-jp'>走らないで</span> (đừng chạy).<br>・<span class='gd-jp'>おやすみなさい</span>、<span class='gd-jp'>おかえりなさい</span>、<span class='gd-jp'>ごめんなさい</span> tuy cũng có なさい nhưng đã là câu chào cố định, không có nghĩa mệnh lệnh. Có điều <span class='gd-jp'>ごめんなさい</span> khá khẩu ngữ; xin lỗi cấp trên, khách hàng thì phải dùng 「<span class='gd-jp'>すみません</span>」 hoặc 「<span class='gd-jp'>申し訳ありません</span>」.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là bảo người ta ngủ sớm, đổi cách nói thì giọng điệu và quan hệ giữa hai người cũng khác:<br><b>〜なさい</b>＝từ trên xuống, giọng dạy bảo (mẹ nói với con):</div><div class='gd-ex-line'>・<span class='gd-jp'>もう11時だよ。早く寝なさい。</span>(Đã 11 giờ rồi đấy, đi ngủ ngay)</div><div class='gd-sec'><b>Thể mệnh lệnh</b>＝trực tiếp, rất mạnh, phần lớn là cách nói của nam giới, hoặc chỉ dùng khi cãi nhau, lúc khẩn cấp:</div><div class='gd-ex-line'>・<span class='gd-jp'>早く寝ろ。</span>(Đi ngủ ngay cho tao)</div><div class='gd-sec'><b>〜てください</b>＝nhờ người ta làm một cách lịch sự, bác sĩ nói với bệnh nhân, nhân viên nói với khách đều dùng:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てくださいね。</span>(Hôm nay xin hãy nghỉ ngơi sớm nhé)</div><div class='gd-sec'><b>〜てね</b>＝lời nhắc nhẹ nhàng giữa bạn bè, người nhà:</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は早く寝てね。</span>(Hôm nay ngủ sớm nhé)</div><div class='gd-warn'>Mẹo phân biệt: người lớn đang 「dạy bảo」 trẻ con thì dùng なさい; muốn nhờ người ta một cách lịch sự thì dùng てください; nhắc nhở bạn bè thoải mái thì dùng てね; ろ là mạnh nhất, người mới học đừng tùy tiện dùng.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp 「thể mệnh lệnh・thể cấm chỉ」 (<span class='gd-jp'>寝ろ</span>、<span class='gd-jp'>寝るな</span>), bạn sẽ hiểu được những mệnh lệnh trực tiếp hơn trong phim Nhật, và cũng hiểu rõ vì sao なさい được xem là 「ôn hòa」.</div>","n4-51":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể ý chí chính là <b>phiên bản thân mật</b> của「〜ましょう」. Với đồng nghiệp bạn nói <span class='gd-jp'>一緒に行きましょう</span>, với bạn bè thì nói <span class='gd-jp'>一緒に行こう</span>. Nghĩa vẫn là \"nhé / nào / đi thôi\", chỉ là giọng điệu thoải mái hơn.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Rủ rê</span>Rủ đối phương cùng làm một việc gì đó với bạn.</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に行こう。</span>(Cùng đi nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休もう。</span>(Nghỉ một chút nào)</div><div class='gd-sec'><span class='gd-tag'>Tự cổ vũ bản thân</span>Tự quyết định trong lòng, tự nói với mình, xung quanh không có ai cũng dùng được.</div><div class='gd-ex-line'>・<span class='gd-jp'>よし、明日から早く起きよう。</span>(Được rồi, từ mai mình sẽ dậy sớm)</div><div class='gd-sec'><span class='gd-tag'>Chủ động giúp đỡ</span>Thêm「か」phía sau, nghĩa là \"để mình ~ giúp bạn nhé?\".</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物、持とうか。</span>(Để mình xách hành lý giúp bạn nhé?)</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>: đổi âm cuối sang âm hàng「お」cùng hàng, rồi thêm「う」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → く đổi thành こ → <span class='gd-jp'>行こう</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲もう</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待とう</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話そう</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ろう</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会おう</span></span><br>Nghĩ từ thể ます cũng được: đổi「き」của <span class='gd-jp'>行きます</span> thành「こ」, rồi thêm「う」.</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ「る」ở cuối, thêm「よう」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べよう</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きよう</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見よう</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, cứ học thuộc)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しよう</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来よう</span>(こよう)</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phần こう trong「行こう」phải đọc kéo dài, nghe như「いこー」. Đọc ngắn thành「いこ」là cách nói rất nũng nịu, rất khẩu ngữ, sắc thái sẽ khác.<br>・<span class='gd-jp'>会う</span>thành <span class='gd-jp'>会おう</span>. Đừng nhầm với thể ない là <span class='gd-jp'>会わない</span> rồi viết thành「会わう」.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: là <span class='gd-jp'>帰ろう</span>, không phải 帰よう.<br>・Thể ý chí của 来る đọc là <b>こよう</b>, không phải きよう.<br>・Thể này chỉ dùng để nói <b>chính mình</b> sẽ làm, hoặc <b>rủ đối phương cùng làm</b> với bạn, không dùng để sai người khác đi làm. Muốn nói \"rủ cả bạn bè đến nhé\" thì đổi thành <span class='gd-jp'>友達も呼ぼう</span> (gọi cả bạn bè đến luôn nhé).<br>・Đây là cách nói giữa bạn bè với nhau; với thầy cô, khách hàng thì phải quay lại dùng「〜ましょう」.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là rủ bạn đi xem phim, có ba cách nói:<br><span class='gd-jp'>映画を見に行こう。</span>(Đi xem phim nhé): rủ thẳng, hơi có cảm giác \"vậy chốt nhé\".<br><span class='gd-jp'>映画を見に行かない？</span>(Có muốn đi xem phim không?): hỏi xem đối phương có muốn đi không, chừa chỗ cho họ hơn.<br><span class='gd-jp'>映画を見に行きましょう。</span>(Chúng ta đi xem phim nhé): bản lịch sự của「行こう」, dùng với người chưa thân hoặc bậc trên.</div><div class='gd-warn'>Mẹo chọn nhanh: đối phương là bạn bè và bạn nghĩ họ sẽ đồng ý thì dùng「行こう」; muốn hỏi thăm ý trước thì dùng「行かない？」; cần giữ lịch sự với đối phương thì dùng「行きましょう」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「と思います」phía sau là \"tôi định ~\": <span class='gd-jp'>来年、日本へ行こうと思います。</span>(Tôi định sang Nhật vào năm sau)</div>","n4-52":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể khả năng chính là nghĩa <b>\"biết ~\", \"có thể ~\", \"được ~\"</b> trong tiếng Việt, được gắn thẳng vào động từ. <span class='gd-jp'>書く</span> là \"viết\", đổi thành <span class='gd-jp'>書ける</span> là \"biết viết, viết được\". Khi người Nhật nói \"biết hay không, làm được hay không\", họ dùng thể này nhiều nhất.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Biết (năng lực đã học)</span>Đã học, đã luyện nên làm được.</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語が書けます。</span>(Tôi biết viết tiếng Hàn)</div><div class='gd-ex-line'>・<span class='gd-jp'>ピアノが弾けますか。</span>(Bạn biết chơi piano không?)</div><div class='gd-sec'><span class='gd-tag'>Có thể / được (hoàn cảnh cho phép)</span>Không phải biết hay không, mà là thời gian, địa điểm, quy định có cho phép hay không.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真が撮れますか。</span>(Ở đây có chụp ảnh được không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は来られますか。</span>(Ngày mai bạn đến được không?)</div><div class='gd-sec'><span class='gd-tag'>Dám ăn, ăn được</span>Khi nói về đồ ăn, nó thường đúng là nghĩa \"dám ăn\" hoặc \"ăn được\" trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆が食べられますか。</span>(Bạn ăn được natto không?)</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>: đổi âm cuối sang âm hàng「え」cùng hàng, rồi thêm「る」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く đổi thành け → <span class='gd-jp'>書ける</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買える</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待てる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰れる</span></span><br>Nghĩ từ thể ます cũng được: đổi「き」của <span class='gd-jp'>書きます</span> thành「け」→ <span class='gd-jp'>書けます</span>.</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ「る」ở cuối, thêm「られる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, cứ học thuộc)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>(こられる)</span><br>Động từ dạng「danh từ＋する」cũng vậy, đổi する thành できる: <span class='gd-pair'><span class='gd-jp'>説明する</span> → <span class='gd-jp'>説明できる</span></span></div><div class='gd-h'>Chia xong rồi, còn chia tiếp được nữa</div><div class='gd-sec'>Sau khi chia xong, thể khả năng <b>tự nó là một động từ nhóm 2</b>. Muốn nói \"không biết/không làm được\" hay \"đã làm được rồi\" thì cứ chia tiếp theo quy tắc nhóm 2:<br><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けます</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けない</span></span><span class='gd-pair'><span class='gd-jp'>書ける</span> → <span class='gd-jp'>書けた</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>朝、なかなか起きられない。</span>(Buổi sáng mãi mà không dậy nổi)</div><div class='gd-h'>Trợ từ: を thường đổi thành が</div><div class='gd-sec'>Sau khi chuyển sang thể khả năng, 「を」ban đầu thường đổi thành「が」:<br><span class='gd-pair'><span class='gd-jp'>日本語を話す</span> → <span class='gd-jp'>日本語が話せる</span></span><br>Trong hội thoại hằng ngày cũng nghe thấy dùng を, nhưng sách giáo khoa và kỳ thi chủ yếu dùng が, nên nhớ <b>が</b> là chắc ăn nhất.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: là <span class='gd-jp'>帰れる</span>, không phải 帰られる.<br>・Thể khả năng của 来る đọc là <b>こられる</b>, không phải きられる.<br>・Thể khả năng của する phải đổi nguyên thành <span class='gd-jp'>できる</span>, không tự chia theo quy tắc được.<br>・Trong khẩu ngữ thường nghe <span class='gd-jp'>食べれる</span>, <span class='gd-jp'>見れる</span>, <span class='gd-jp'>来れる</span> (bỏ mất「ら」). Người Nhật bình thường đúng là hay nói vậy, nhưng trong sách giáo khoa, kỳ thi, hoàn cảnh trang trọng thì vẫn phải dùng <span class='gd-jp'>食べられる</span>, <span class='gd-jp'>見られる</span>, <span class='gd-jp'>来られる</span>.<br>・\"Nhìn thấy, nghe thấy\" nếu là <b>tự nhiên thấy, tự nhiên nghe được</b>, tiếng Nhật dùng <span class='gd-jp'>見える</span>, <span class='gd-jp'>聞こえる</span>: <span class='gd-jp'>ここから富士山が見える。</span>(Từ đây nhìn thấy núi Phú Sĩ). Còn <span class='gd-jp'>見られる</span>, <span class='gd-jp'>聞ける</span> là <b>có cơ hội, có cách để đi xem, đi nghe</b>: <span class='gd-jp'>このアプリで映画が見られる。</span>(Dùng app này có thể xem phim)</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><span class='gd-jp'>〜ことができる</span> mà bạn đã học trước đây có nghĩa giống thể khả năng:<br>・<span class='gd-jp'>日本語が話せます。</span>(Tôi biết nói tiếng Nhật)<br>・<span class='gd-jp'>日本語を話すことができます。</span>(Tôi có thể nói tiếng Nhật)<br>Khác nhau ở độ dài và sắc thái: thể khả năng ngắn hơn, dùng nhiều nhất khi nói chuyện hằng ngày; <span class='gd-jp'>ことができる</span> dài hơn, trang trọng hơn, hay gặp trong hướng dẫn sử dụng, thông báo, bài phát biểu. Còn một điểm nữa: động từ đứng trước <span class='gd-jp'>ことができる</span> không biến đổi, trợ từ cũng giữ nguyên「を」.</div><div class='gd-warn'>Mẹo chọn nhanh: nói chuyện bình thường thì dùng thể khả năng; muốn nói trang trọng, rõ ràng hơn thì dùng ことができる. Hai cách nghĩa như nhau, dùng cái nào cũng không sai.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「ようになる」phía sau là \"trở nên biết ~ rồi\": <span class='gd-jp'>日本語が少し話せるようになりました。</span>(Tôi đã biết nói được một chút tiếng Nhật rồi)</div>","n4-49":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ばかり」nghĩa là <b>「cứ ～ hoài」「suốt ngày ～」「toàn là ～」</b>. Khi mẹ mắng con «suốt ngày chỉ biết chơi game», tiếng Nhật sẽ dùng ばかり. Điểm mấu chốt: người nói thấy việc đó <b>quá nhiều, không hay lắm</b>, nên câu thường mang giọng phàn nàn hoặc trách móc.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Hành động lặp quá nhiều</span>Động từ thể て＋ばかりいる: nhấn mạnh «cứ làm mãi một việc, chẳng làm gì khác».<br><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span> → <span class='gd-jp'>遊んでばかりいる</span></span>（cứ chơi suốt）<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝て</span> → <span class='gd-jp'>寝てばかりいる</span></span>（cứ ngủ suốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの犬は一日中寝てばかりいる。</span>（Con chó nhà mình ngủ suốt cả ngày）</div><div class='gd-sec'><span class='gd-tag'>Đối tượng toàn là một thứ</span>Danh từ＋ばかり＋động từ: nhấn mạnh «làm toàn là thứ này».</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はゲームばかりしている。</span>（Em trai mình suốt ngày chơi game）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はいつも文句ばかり言っている。</span>（Anh ấy lúc nào cũng chỉ toàn than phiền）</div><div class='gd-sec'>Sau danh từ cũng có thể thêm thẳng「です／だ」, để diễn tả «nhìn đâu cũng toàn là ～»:</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、雨ばかりですね。</span>（Dạo này toàn mưa nhỉ）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Trách móc</span>「〜てばかりいないで」＝đừng cứ ～ mãi. Phía sau thường là <span class='gd-jp'>〜なさい</span>, câu thoại kinh điển của bố mẹ và thầy cô.</div><div class='gd-ex-line'>・<span class='gd-jp'>遊んでばかりいないで、勉強しなさい。</span>（Đừng chỉ chơi mãi nữa, đi học bài đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>泣いてばかりいないで、話してよ。</span>（Đừng chỉ khóc mãi thế, nói với mình đi mà）</div><div class='gd-sec'><span class='gd-tag'>Tự trào</span>Nói về chính mình cũng được, mang cảm giác «haizz, sao mình cứ thế này nhỉ».</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、食べてばかりいる。</span>（Dạo này mình cứ ăn suốt）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi danh từ đi với ばかり, 「を」ban đầu thường được bỏ: nói <span class='gd-jp'>漫画ばかり読む</span>, đừng nói thành 「漫画をばかり読む」.<br>・Mẫu này nói về trạng thái <b>lặp đi lặp lại trong một khoảng thời gian</b>, việc chỉ xảy ra một lần thì không dùng được.<br>・Giọng câu mang tính phê bình, nên nói về thầy cô, cấp trên, khách hàng sẽ rất thất lễ, hãy dùng cẩn thận.<br>・Khi nói chuyện với bạn bè, người ta hay nói thành <span class='gd-jp'>ばっかり</span>, ví dụ <span class='gd-jp'>遊んでばっかり</span>. Nghĩa y hệt, chỉ khẩu ngữ hơn thôi.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'><b>たばかり</b>（n4-29）＝<b>vừa mới</b> làm xong, không liên quan đến số lần:<br><span class='gd-jp'>ご飯を食べたばかりです。</span>（Mình vừa mới ăn cơm xong）<br><b>てばかりいる</b>＝<b>cứ</b> làm mãi:<br><span class='gd-jp'>お菓子を食べてばかりいる。</span>（Cứ ăn bánh kẹo suốt）</div><div class='gd-sec'><b>だけ</b>＝<b>chỉ có</b> cái này, đơn thuần nêu sự thật, không có ý bất mãn:<br><span class='gd-jp'>朝はコーヒーだけ飲みました。</span>（Buổi sáng mình chỉ uống cà phê）<br><b>ばかり</b>＝<b>cứ mãi, quá nhiều</b>, mang ý phàn nàn:<br><span class='gd-jp'>コーヒーばかり飲んでいる。</span>（Cứ uống cà phê suốt）</div><div class='gd-warn'>Mẹo phân biệt: phía trước là「た」thì nghĩa là «vừa mới», phía trước là「て」thì nghĩa là «cứ mãi». Chỉ muốn nói «chỉ có cái này» thì dùng だけ, còn muốn trách «sao lúc nào cũng cái này» thì dùng ばかり.</div>","n4-50":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜場合」nghĩa là <b>«trong trường hợp gặp tình huống ～»</b>. Chữ 場合 chính là «trường hợp» trong Hán Việt. Những câu bạn thấy ở ga tàu, phòng khách sạn hay trong sách hướng dẫn như «Trong trường hợp có hỏa hoạn, vui lòng ～», «Nếu có bất kỳ vấn đề gì, vui lòng ～», tiếng Nhật đều dùng「場合」. Nó trang trọng hơn「〜たら」, thường xuất hiện trong quy định, thông báo, hoặc lời giải thích của nhân viên và chăm sóc khách hàng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Quy định・Thông báo</span>Giả định trước một tình huống «có thể xảy ra, cũng có thể không», rồi nói cho đối phương biết lúc đó nên làm gì. Phía sau thường là「〜てください」hoặc một quy tắc.</div><div class='gd-ex-line'>・<span class='gd-jp'>地震の場合は、机の下に隠れてください。</span>（Trong trường hợp có động đất, hãy trốn xuống dưới gầm bàn）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の場合は、試合は中止です。</span>（Nếu trời mưa thì trận đấu sẽ bị hủy）</div><div class='gd-ex-line'>・<span class='gd-jp'>分からない場合は、先生に聞いてください。</span>（Nếu không hiểu thì hãy hỏi thầy/cô）</div><div class='gd-sec'>Sau「場合」hầu như luôn thêm「は」thành「〜場合は」, bạn cứ nhớ nguyên cụm này là được.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: ghép trực tiếp với thể từ điển, thể ない, thể た.<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れる場合</span></span><span class='gd-pair'><span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けない場合</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れた場合</span></span><br><b>Tính từ い</b>: ghép trực tiếp. <span class='gd-pair'><span class='gd-jp'>熱が高い</span> → <span class='gd-jp'>熱が高い場合</span></span><br><b>Tính từ な</b>: giữ lại「な」. <span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理な場合</span></span><br><b>Danh từ</b>: thêm「の」ở giữa. <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨の場合</span></span><span class='gd-pair'><span class='gd-jp'>火事</span> → <span class='gd-jp'>火事の場合</span></span></div><div class='gd-sec'><span class='gd-tag'>Khác nhau giữa dạng る và た</span>Động từ dùng thể từ điển hay thể た thì nghĩa hơi khác nhau:<br>・<span class='gd-jp'>遅れる場合は、電話してください。</span>（Nếu sắp bị trễ thì hãy gọi điện trước: liên lạc khi chưa trễ）<br>・<span class='gd-jp'>カードをなくした場合は、すぐ連絡してください。</span>（Lỡ làm mất thẻ thì hãy liên lạc ngay: sau khi việc đó đã xảy ra）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「場合」đọc là <b>ばあい</b>, không phải ばしょ, và cũng đừng đọc theo âm Hán Việt «trường hợp».<br>・Danh từ và tính từ な không thể thêm「だ」trực tiếp: không phải「雨だ場合」mà là <span class='gd-jp'>雨の場合</span>; không phải「無理だ場合」mà là <span class='gd-jp'>無理な場合</span>.<br>・Tính từ な phải dùng <b>な</b>, đừng lẫn với danh từ mà viết thành「の」.<br>・「場合」chỉ dùng cho việc <b>không chắc sẽ xảy ra</b>. Việc chắc chắn sẽ đến, ví dụ «khi đến 10 giờ», không thể nói「10時になった場合」mà phải dùng <span class='gd-jp'>10時になったら</span>.<br>・Việc đã xảy ra rồi cũng không dùng được: «lúc hôm qua trời mưa» không thể nói「昨日雨が降った場合」.<br>・Giọng văn khá trang trọng, khi nói chuyện với bạn bè kiểu «mưa thì mình không đi nữa», dùng <span class='gd-jp'>雨だったら</span> sẽ tự nhiên hơn.</div><div class='gd-h'>Phân biệt với các mẫu giống nhau</div><div class='gd-sec'>Cùng là «nếu trời mưa»:<br><b>場合</b>：<span class='gd-jp'>雨の場合は、イベントは中止です。</span>（Nếu trời mưa, sự kiện sẽ bị hủy）→ giống quy định ghi trên thông báo.<br><b>たら</b>：<span class='gd-jp'>雨が降ったら、家で映画を見よう。</span>（Nếu trời mưa thì mình xem phim ở nhà nhé）→ kiểu nói tự nhiên giữa bạn bè.<br>Ngoài ra,「たら」dùng được cho việc chắc chắn sẽ xảy ra (<span class='gd-jp'>駅に着いたら、電話して。</span>Đến ga rồi thì gọi cho mình nhé), còn「場合」thì không.</div><div class='gd-warn'>Mẹo phân biệt: nếu dịch được thành «trong trường hợp ～», «nếu xảy ra ～» và đang nói về quy định hay lời giải thích thì dùng「場合」; còn trò chuyện hằng ngày, hoặc việc chắc chắn sẽ xảy ra thì dùng「たら」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Các cách nói «nếu» khác nên học so sánh cùng nhau: <span class='gd-jp'>〜ば</span>（thể điều kiện）, <span class='gd-jp'>〜なら</span>, <span class='gd-jp'>〜と</span>. Sắc thái của mỗi mẫu khác nhau một chút.</div>","n4-53":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể mệnh lệnh là kiểu quát thẳng “<b>Làm ngay cho tôi～!</b>”, còn thể cấm chỉ là “<b>Cấm～!</b>”. Giống như tiếng Việt khi bạn hét “Chạy mau!”, “Cấm vào!”, không có chút khách sáo nào. Nói với người khác ngoài đời thì rất hung, bạn sẽ nghe nhiều nhất trong anime, các trận thể thao và tình huống khẩn cấp.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Khẩn cấp, nguy hiểm</span>Lúc không kịp khách sáo.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ない！逃げろ！</span>（Nguy hiểm! Chạy mau!）</div><div class='gd-sec'><span class='gd-tag'>Cổ vũ</span>Hét ở rìa sân thi đấu. Lúc này không bị xem là hung, cả nam lẫn nữ đều hét như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>頑張れ！負けるな！</span>（Cố lên! Đừng thua!）</div><div class='gd-sec'><span class='gd-tag'>Thuật lại lời người khác</span>Thêm 「と言われた」 phía sau để nói “ai đó bảo tôi phải～”. Đây là trường hợp chính bạn sẽ dùng nhiều nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲むなと言われた。</span>（Bác sĩ bảo tôi đừng uống rượu）</div><div class='gd-ex-line'>・<span class='gd-jp'>父に早く寝ろと言われた。</span>（Bố bảo tôi đi ngủ sớm）</div><div class='gd-sec'><span class='gd-tag'>Biển báo, trên nói với dưới</span>Chữ 「<span class='gd-jp'>止まれ</span>」 (dừng lại) viết trên đường chính là thể mệnh lệnh. Ngoài ra còn gặp khi cãi nhau, hoặc khi huấn luyện viên mắng cầu thủ.</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'><b>Thể mệnh lệnh</b><br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「え」 cùng hàng.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành け → <span class='gd-jp'>行け</span></span><br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走れ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲め</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待て</span></span><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急げ</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」 ở cuối, thêm 「ろ」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べろ</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きろ</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ろ</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しろ</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来い</span>（こい）</span></div><div class='gd-sec'><b>Thể cấm chỉ</b> đơn giản hơn nhiều, không phân nhóm, chỉ cần <b>thêm 「な」 vào thể từ điển</b>.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くな</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるな</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するな</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るな</span>（くるな）</span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Dùng thể mệnh lệnh với thầy cô, cấp trên, khách hàng là cực kỳ thất lễ. Những câu như 「<span class='gd-jp'>待て！</span>」「<span class='gd-jp'>見ろ！</span>」 học từ anime thì đừng đem nói với người thật nhé.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span> thuộc nhóm 1, nên là <span class='gd-jp'>帰れ</span>、<span class='gd-jp'>入れ</span>, không phải 帰ろ、入ろ.<br>・<span class='gd-jp'>来い</span> đọc là <b>こい</b>, nhưng <span class='gd-jp'>来るな</span> đọc là <b>くるな</b>, hai cách đọc khác nhau.<br>・Thể mệnh lệnh nhìn rất giống thể khả năng: <span class='gd-jp'>読め</span> là “đọc đi!”, còn <span class='gd-jp'>読める</span> là “đọc được”. Khác nhau ở chỗ cuối câu có 「る」 hay không.<br>・Trước 「な」 nhất định phải là thể từ điển: <span class='gd-jp'>行くな</span> là “cấm đi”. Nếu bỏ ます rồi thêm な, ví dụ <span class='gd-jp'>行きな</span>, thì lại là kiểu nói khẩu ngữ “đi đi”, nghĩa hoàn toàn ngược lại.</div><div class='gd-h'>Phân biệt với những cách nói giống nhau</div><div class='gd-sec'>Cùng là bảo trẻ đi ngủ:<br><span class='gd-jp'>早く寝ろ！</span>（Ngủ ngay cho tôi!）: hung nhất, quát thẳng.<br><span class='gd-jp'>早く寝なさい。</span>（Đi ngủ sớm đi.）: giọng bố mẹ, thầy cô nói với trẻ, có cảm giác trên nói với dưới nhưng không thô lỗ.<br><span class='gd-jp'>早く寝てね。</span>（Ngủ sớm nhé.）: lời nhờ thông thường, nhẹ nhàng.</div><div class='gd-sec'>Cùng là không cho vào phòng:<br><span class='gd-jp'>入るな！</span>（Cấm vào!）: hung nhất.<br><span class='gd-jp'>入ってはいけません。</span>（Không được vào.）: nói về quy định, giải thích điều bị cấm, giọng trang trọng hơn.<br><span class='gd-jp'>入らないでください。</span>（Xin đừng vào.）: nhờ vả lịch sự.</div><div class='gd-warn'>Mẹo nhận biết: quát ra thì dùng thể mệnh lệnh, thể cấm chỉ; người lớn bảo trẻ con thì dùng なさい; nói về quy tắc thì dùng てはいけません; nhờ người khác thì dùng てください、ないでください.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thể mệnh lệnh của <span class='gd-jp'>くれる</span> là <span class='gd-jp'>くれ</span>, không phải くれろ. Con trai hay nói <span class='gd-jp'>ちょっと待ってくれ。</span>（Đợi tôi một chút）, nghe mềm hơn so với chỉ nói 「待て」.</div>","n4-57":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「と」 này giống như <b>“hễ ～ là ～”</b> trong tiếng Việt. Chỉ cần A xảy ra thì B <b>lần nào cũng</b> theo sau, không có ngoại lệ, giống như “hễ bấm công tắc là đèn sáng”. Vì vậy nó hay dùng nhất cho quy luật tự nhiên, cách vận hành máy móc, chỉ đường, và những thói quen lần nào cũng làm.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Quy luật tự nhiên</span>Vốn dĩ là như vậy, không ai thay đổi được.</div><div class='gd-ex-line'>・<span class='gd-jp'>春になると、桜が咲きます。</span>（Hễ đến mùa xuân là hoa anh đào nở）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜になると、街の灯りがつきます。</span>（Hễ đến tối là đèn đường sáng lên）</div><div class='gd-sec'><span class='gd-tag'>Vận hành máy móc</span>Làm động tác này thì máy sẽ có phản ứng.</div><div class='gd-ex-line'>・<span class='gd-jp'>このボタンを押すと、ドアが開きます。</span>（Hễ bấm nút này là cửa mở）</div><div class='gd-ex-line'>・<span class='gd-jp'>この鍵を回すと、金庫が開きます。</span>（Xoay chiếc chìa khóa này là két sắt mở）</div><div class='gd-sec'><span class='gd-tag'>Chỉ đường</span>Ở Nhật, khi hỏi đường bạn sẽ thường nghe cách nói này.</div><div class='gd-ex-line'>・<span class='gd-jp'>まっすぐ行くと、右に駅があります。</span>（Đi thẳng là thấy ga ở bên phải）</div><div class='gd-sec'><span class='gd-tag'>Thói quen cố định</span>Lần nào làm A xong cũng nhất định làm tiếp B.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は家に帰ると、すぐテレビをつけます。</span>（Bố tôi hễ về đến nhà là bật tivi ngay）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Trước 「と」 đặt <b>dạng thường, không có ます và không phải thì quá khứ</b>. Động từ hay dùng nhất là thể từ điển, muốn nói “không～” thì dùng thể ない.<br>Động từ thể từ điển：<span class='gd-pair'><span class='gd-jp'>押す</span> → <span class='gd-jp'>押すと</span></span><br>Động từ thể ない：<span class='gd-pair'><span class='gd-jp'>急がない</span> → <span class='gd-jp'>急がないと</span></span><br>Tính từ い nối trực tiếp：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いと</span></span><br>Tính từ な và danh từ phải thêm だ trước：<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だと</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>急がないと、遅れるよ。</span>（Không nhanh lên là sẽ trễ đó）</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いと、手が冷たくなります。</span>（Hễ trời lạnh là tay lạnh buốt）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau 「と」 <b>không được đặt</b> lời nhờ vả, mệnh lệnh, lời mời, cũng không đặt ý định của bản thân kiểu “tôi sẽ～”. Vì 「と」 nói về kết quả tự nhiên xảy ra, không phải việc bạn muốn làm.<br>　×<span class='gd-jp'>駅に着くと、電話してください。</span><br>　○<span class='gd-jp'>駅に着いたら、電話してください。</span>（Khi đến ga thì hãy gọi cho tôi）<br>・Trước 「と」 luôn dùng <b>dạng không quá khứ (thể từ điển hoặc thể ない)</b>, dù đang kể chuyện quá khứ cũng vậy. Thì quá khứ chỉ đặt ở cuối câu: <span class='gd-jp'>子どものころ、冬になると、よく雪が降りました。</span>（Hồi nhỏ, hễ đến mùa đông là hay có tuyết rơi）. Không được nói 押したと.<br>・「と」 còn có nghĩa “cùng/với” (<span class='gd-jp'>友達と</span>) và “nói là” (<span class='gd-jp'>と言います</span>). Chỉ khi phía trước là một hành động hoặc một mệnh đề, phía sau lại nối tiếp một việc khác thì mới là 「と」 kiểu “hễ ～ là ～” này.</div><div class='gd-h'>Phân biệt với những cách nói giống nhau</div><div class='gd-sec'><b>と</b>＝hễ A là B, lần nào cũng vậy, phía sau chỉ đặt “việc sẽ xảy ra”：<span class='gd-jp'>春になると、桜が咲きます。</span>（Hễ đến mùa xuân là hoa anh đào nở）<br><b>たら</b>＝sau khi A thì làm B, phía sau có thể đặt lời nhờ, lời mời, ý định của bản thân：<span class='gd-jp'>春になったら、花見に行こう。</span>（Đến mùa xuân thì mình đi ngắm hoa nhé）<br><b>ば</b>＝nhấn mạnh “chỉ cần có điều kiện A”：<span class='gd-jp'>このボタンを押せば、ドアが開きます。</span>（Chỉ cần bấm nút này là cửa sẽ mở）<br><b>なら</b>＝tiếp lời người đối diện để đưa ra gợi ý：<span class='gd-jp'>京都へ行くなら、春がいいですよ。</span>（Nếu bạn định đi Kyoto thì mùa xuân là hợp nhất đó）</div><div class='gd-warn'>Mẹo nhận biết: nếu phía sau muốn nói “hãy～”, “cùng～nhé”, “tôi sẽ～” thì dùng たら; nếu phía sau là kết quả “chắc chắn sẽ như vậy” thì dùng と.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「と」 cũng có thể đứng trước 「いい」 để diễn tả mong muốn：<span class='gd-jp'>明日、晴れるといいですね。</span>（Mong là ngày mai trời nắng nhỉ）Cách dùng này sẽ được nói đến ở n4-58.</div>","n4-58":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Mẫu câu này giống <b>「cứ ～ là được」</b> hoặc <b>「ước gì ～ thì tốt」</b> trong tiếng Việt. Nó dùng trong hai trường hợp: một là <b>đưa lời khuyên</b> (「Bạn cứ hỏi thầy là được mà」), hai là <b>ước nguyện</b> (「Ước gì ngày mai trời nắng」, tức là 「hy vọng ngày mai trời nắng」). Phía trước có thể dùng ba cách nói điều kiện là たら, ば, と, phía sau thêm いい.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đưa lời khuyên</span>Bạn nói với đối phương rằng 「làm vậy là giải quyết được」, giọng nhẹ nhàng, hay đi với「よ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>医者に相談したらいいですよ。</span>(Bạn cứ đi trao đổi với bác sĩ là được mà)</div><div class='gd-ex-line'>・<span class='gd-jp'>分からなかったら、先生に聞けばいいよ。</span>(Nếu không hiểu thì cứ hỏi thầy cô là được)</div><div class='gd-ex-line'>・<span class='gd-jp'>疲れたときは、少し休むといいですよ。</span>(Khi mệt thì nghỉ một chút sẽ tốt hơn đấy)</div><div class='gd-sec'><span class='gd-tag'>Hỏi nên làm thế nào</span>Chuyển thành câu hỏi, nghĩa là 「nên làm thế nào thì được?」. Lúc này hầu như luôn dùng たら hoặc ば, và rất hay gặp.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅までどう行けばいいですか。</span>(Đến ga thì nên đi thế nào ạ?)</div><div class='gd-ex-line'>・<span class='gd-jp'>何を持っていったらいいですか。</span>(Nên mang theo gì thì tốt ạ?)</div><div class='gd-sec'><span class='gd-tag'>Ước nguyện</span>Mong một việc nào đó xảy ra, thường là việc mình không kiểm soát được. Hay đi với「ね」(nói với người khác) hoặc「なあ」(tự nói với mình). Với cách dùng này, 「といい」đặc biệt phổ biến.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、晴れるといいですね。</span>(Mong là ngày mai trời sẽ nắng nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降らないといいね。</span>(Mong là trời đừng mưa nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できたらいいなあ。</span>(Giá mà đậu được kỳ thi thì tốt quá)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><b>たら</b>: chuyển sang thể た trước, rồi thêm ら.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたら</span></span></div><div class='gd-sec'><b>ば</b>: chuyển sang thể ば.<br>Nhóm 1 (động từ ngũ đoạn): đổi âm cuối thành âm hàng え cùng hàng, rồi thêm ば.<span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành け → <span class='gd-jp'>行けば</span></span><br>Nhóm 2 (động từ nhất đoạn): bỏ る, thêm れば.<span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば</span></span><br>Nhóm 3 (する・来る): <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すれば</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば</span>(くれば)</span></div><div class='gd-sec'><b>と</b>: phía trước dùng <b>thể thông thường ở thì không quá khứ</b>, tức là thể từ điển hoặc thể ない; tính từ đuôi な và danh từ thì thêm だ.<br><span class='gd-pair'><span class='gd-jp'>晴れる</span> → <span class='gd-jp'>晴れるといい</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないといい</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気だといい</span></span></div><div class='gd-h'>Thêm のに: tiếc là không được như vậy</div><div class='gd-sec'>Cuối câu thành「ばいいのに」「たらいいのに」, nghĩa là 「giá mà ～ thì tốt, nhưng thực tế lại không phải vậy」, mang sắc thái tiếc nuối hoặc không hài lòng.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く春が来ればいいのに。</span>(Giá mà xuân đến sớm thì tốt, tiếc là chưa đến)</div><div class='gd-ex-line'>・<span class='gd-jp'>早く言えばいいのに。</span>(Nói sớm có phải xong rồi không)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Trước「と」không dùng thể た: <span class='gd-jp'>飲むといい</span>, <span class='gd-jp'>降らないといい</span> là đúng, <span class='gd-jp'>飲んだといい</span> là sai.<br>・「～たらいいですよ」có cảm giác 「để tôi chỉ cho bạn」, nói với thầy cô hay cấp trên sẽ hơi thiếu lịch sự, nên đổi sang <span class='gd-jp'>〜たらいかがですか</span> cho lịch sự hơn.<br>・「～ばいいのに」khi nói với người khác thường mang ý phàn nàn, như <span class='gd-jp'>早く言えばいいのに</span> là đang trách đối phương, đừng dùng với người lớn tuổi hay bề trên.<br>・Câu tiếng Việt 「hy vọng ngày mai trời nắng」 đừng dịch sát thành 「希望します」. Người Nhật ngày thường chỉ nói <span class='gd-jp'>明日晴れるといいですね</span>.</div><div class='gd-h'>Phân biệt với các mẫu câu giống nhau</div><div class='gd-sec'>Cả ba đều kết thúc bằng「いい」nhưng nghĩa khác nhau:<br><span class='gd-jp'>薬を飲んだほうがいいですよ。</span>(Bạn nên uống thuốc) → <b>ほうがいい</b> là lời khuyên, ngầm ý 「không uống thì không tốt」, giọng mạnh hơn.<br><span class='gd-jp'>薬を飲んだらいいですよ。</span>(Bạn cứ uống thuốc là được mà) → <b>たらいい</b> là nhẹ nhàng đưa ra một cách giải quyết.<br><span class='gd-jp'>薬を飲んでもいいですよ。</span>(Bạn có thể uống thuốc đấy) → <b>てもいい</b> là cho phép, không phải khuyên.</div><div class='gd-warn'>Mẹo phân biệt nhanh: 「nên ～」dùng ほうがいい, 「cứ ～ là được」dùng たらいい, 「có thể ～」dùng てもいい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thì quá khứ <span class='gd-jp'>〜ばよかった</span> nghĩa là 「giá như hồi đó ～ thì tốt」, dùng để diễn tả sự hối tiếc: <span class='gd-jp'>もっと勉強すればよかった。</span>(Giá như hồi đó học chăm hơn thì tốt)</div>","n4-64":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜させていただきます」giống <b>「Xin phép được ～」「Vậy tôi xin phép ～ ạ」</b> trong tiếng Việt. Nó nói về việc <b>của chính mình</b>, nhưng giọng hạ thấp rất nhiều, như thể 「nhờ được bạn cho phép nên tôi mới làm」. Bạn sẽ nghe rất thường xuyên khi họp, lên phát biểu, hoặc nói chuyện với cấp trên và khách hàng.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Lên sân khấu, dịp trang trọng</span>Khi sắp bắt đầu giải thích, tự giới thiệu hay thuyết trình, bạn nói trước một câu này.</div><div class='gd-ex-line'>・<span class='gd-jp'>では、説明させていただきます。</span>(Vậy, xin phép được giải thích ạ)</div><div class='gd-ex-line'>・<span class='gd-jp'>自己紹介させていただきます。</span>(Xin phép được tự giới thiệu ạ)</div><div class='gd-sec'><span class='gd-tag'>Việc ảnh hưởng đến đối phương</span>Xin nghỉ, về sớm, dùng đồ của người khác… là những việc có ảnh hưởng đến người ta, dùng mẫu này sẽ nói lịch sự hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休ませていただきます。</span>(Ngày mai tôi xin phép được nghỉ ạ)</div><div class='gd-sec'><span class='gd-tag'>Thông báo của cửa hàng</span>Cũng rất hay gặp trên bảng thông báo dán trước cửa tiệm.</div><div class='gd-ex-line'>・<span class='gd-jp'>本日は休ませていただきます。</span>(Hôm nay cửa hàng xin phép nghỉ)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Trước hết chuyển động từ sang thể sai khiến (nghĩa là 「để/cho ～ làm」), rồi chuyển sang thể て「〜させて／〜せて」, phía sau thêm <span class='gd-jp'>いただきます</span>.</div><div class='gd-h'>Cách chia: trước hết xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm hàng「あ」cùng hàng, thêm「せて」, rồi thêm いただきます.<br><span class='gd-pair'><span class='gd-jp'>休む</span> → đổi む thành ま → <span class='gd-jp'>休ませていただきます</span></span><br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせていただきます</span></span><br>Từ kết thúc bằng「う」cần đặc biệt chú ý, 「う」đổi thành「わ」: <span class='gd-pair'><span class='gd-jp'>使う</span> → <span class='gd-jp'>使わせていただきます</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」ở cuối, thêm「させて」, rồi thêm いただきます.<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えさせていただきます</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, cứ học thuộc)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させていただきます</span></span>(<span class='gd-jp'>説明する</span> thành <span class='gd-jp'>説明させていただきます</span>)<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させていただきます</span>(こさせて)</span>, từ này ít dùng hơn.</div><div class='gd-sec'>Tóm lại: <b>chỉ nhóm 2 và nhóm 3 (する → させて、来る → 来させて) mới có「さ」</b>, còn nhóm 1 là thẳng「âm hàng あ ＋ せて」.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Nhóm 1 đừng thêm「さ」thừa: đúng là <span class='gd-jp'>休ませていただきます</span>, không phải 休まさせていただきます; đúng là <span class='gd-jp'>読ませていただきます</span>, không phải 読まさせて. Lỗi này người Nhật cũng hay mắc, nhưng trong bài thi vẫn tính là sai.<br>・<span class='gd-jp'>使う</span> thành <span class='gd-jp'>使わせて</span>, không phải 使あせて.<br>・Mẫu này luôn nói về việc <b>của chính mình</b>, không dùng để nói về người khác.<br>・Thực ra nó không hẳn là 「hỏi」, mà giống một lời <b>thông báo</b> lịch sự rằng 「tôi sẽ làm như vậy」. Nếu thật sự muốn xin phép thì dùng 「〜させていただけませんか」ở phần dưới.<br>・Đừng lạm dụng: với việc không liên quan đến đối phương, cũng không cần ai đồng ý, mà cứ nói「させていただきます」mãi thì nghe rất vòng vo, dùng「〜ます」bình thường là được.</div><div class='gd-h'>Phân biệt với các mẫu câu giống nhau</div><div class='gd-sec'>Cùng là 「hôm nay muốn tan làm sớm」, nói với cấp trên có ba cách:<br><b>させていただきます</b> = thông báo một cách lịch sự, gần như đã quyết định rồi:<br><span class='gd-jp'>今日は早く帰らせていただきます。</span>(Hôm nay tôi xin phép được về sớm ạ)<br><b>させてください</b> = nhờ đối phương cho mình làm, trực tiếp hơn:<br><span class='gd-jp'>今日は早く帰らせてください。</span>(Hôm nay xin hãy cho tôi về sớm)<br><b>させていただけませんか</b> = thật sự đang hỏi, đối phương có thể từ chối, lịch sự nhất:<br><span class='gd-jp'>今日は早く帰らせていただけませんか。</span>(Hôm nay cho tôi về sớm được không ạ?)</div><div class='gd-warn'>Mẹo phân biệt nhanh: kết thúc bằng「ます」là <b>thông báo</b>, 「ください」là <b>nhờ vả</b>, còn「ませんか」mới là thật sự <b>hỏi</b>. Khi chưa được đồng ý thì dùng「〜させていただけませんか」là an toàn nhất.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo hãy xem khiêm nhường ngữ, như <span class='gd-jp'>参ります</span>, <span class='gd-jp'>申します</span>, những cách nói riêng để hạ thấp bản thân, thường xuất hiện cùng với「させていただきます」.</div>","n4-67":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Các từ thường dùng để hỏi như 「何、誰、どこ、いつ」, nếu thêm 「でも」 phía sau thì sẽ thành nghĩa <b>「cái gì cũng ~」「ai cũng ~」「đâu cũng ~」「lúc nào cũng ~」</b> trong tiếng Việt. Nghĩa là tất cả đều được, không có ngoại lệ.</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-jp'>何でも</span>＝cái gì cũng<br><span class='gd-jp'>誰でも</span>＝ai cũng<br><span class='gd-jp'>どこでも</span>＝ở đâu cũng<br><span class='gd-jp'>いつでも</span>＝lúc nào cũng<br><span class='gd-jp'>どれでも</span>＝cái nào cũng (chọn trong từ ba thứ trở lên)<br><span class='gd-jp'>どちらでも</span>＝bên nào cũng (chọn một trong hai)<br><span class='gd-jp'>どんな</span>＋danh từ＋<span class='gd-jp'>でも</span>＝bất kể ~ như thế nào cũng</div><div class='gd-ex-line'>・<span class='gd-jp'>私は何でも食べます。</span>(Tôi ăn gì cũng được)</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は誰でもできます。</span>(Bài này ai cũng làm được)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつでも連絡してください。</span>(Lúc nào cũng có thể liên lạc với tôi nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>どんな仕事でも頑張ります。</span>(Công việc nào tôi cũng sẽ cố gắng)</div><div class='gd-sec'><span class='gd-tag'>Trả lời \"sao cũng được\"</span>Thêm 「いいです」 phía sau là bạn có ngay câu \"sao cũng được\" cực hay dùng trong đời sống.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：いつがいいですか。　B：いつでもいいですよ。</span>(A: Khi nào thì được? B: Lúc nào cũng được nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>赤と青、どちらでもいいです。</span>(Đỏ hay xanh, cái nào cũng được)</div><div class='gd-h'>Còn trợ từ gốc thì sao?</div><div class='gd-sec'><b>が、を</b>: biến mất luôn, không cần giữ lại.<br><span class='gd-pair'><span class='gd-jp'>何を食べますか</span> → <span class='gd-jp'>何でも食べます</span></span> (không nói 何をでも)<br>Các trợ từ như <b>に、と、へ</b>: phải giữ lại, đặt ngay trước でも.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は誰にでも優しいです。</span>(Anh ấy đối với ai cũng dịu dàng)</div><div class='gd-ex-line'>・<span class='gd-jp'>妹は誰とでもすぐ友だちになれます。</span>(Em gái tôi chơi với ai cũng nhanh chóng thành bạn)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>何でも</span> đọc là <b>なんでも</b>, không phải なにでも.<br>・Muốn nói \"không ~ gì cả\" thì <b>không</b> dùng でも, mà phải dùng 「も」 rồi thêm phủ định: <span class='gd-jp'>何も食べません</span> (không ăn gì cả). <span class='gd-jp'>何でも食べません</span> không có nghĩa là \"không ăn gì cả\", đừng nói như vậy nhé.<br>・Khi bạn bè nghiêm túc hỏi \"bạn muốn ăn gì?\", nếu bạn chỉ đáp cụt lủn <span class='gd-jp'>何でもいいです</span> thì nghe có thể hơi giống \"gì cũng được, sao cũng xong\". Bạn có thể nói <span class='gd-jp'>何でも好きです</span> (món gì tôi cũng thích), hoặc cứ đề xuất luôn một món.<br>・Nếu phía trước không phải từ nghi vấn thì でも mang nghĩa khác: <span class='gd-jp'>子どもでもわかります</span> nghĩa là \"đến trẻ con cũng hiểu\".</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là 「何」 nhưng từ đi sau khác nhau thì nghĩa khác hẳn:<br><span class='gd-jp'>何でも食べます。</span>(Ăn gì cũng được: tất cả đều OK)<br><span class='gd-jp'>何も食べません。</span>(Không ăn gì cả: không có thứ nào)<br><span class='gd-jp'>何か食べます。</span>(Ăn cái gì đó: một thứ nào đó, chưa quyết định là gì)<br><br>Đổi sang 「誰」 cũng tương tự:<br><span class='gd-jp'>誰でも知っています。</span>(Ai cũng biết)<br><span class='gd-jp'>誰も知りません。</span>(Không ai biết)<br><span class='gd-jp'>誰か知っていますか。</span>(Có ai biết không?)</div><div class='gd-warn'>Mẹo phân biệt nhanh: \"tất cả đều OK\" dùng <b>でも</b>; \"không có cái nào\" dùng <b>も</b> và đi với phủ định; \"một cái nào đó nhưng không rõ là cái nào\" dùng <b>か</b>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Từ nghi vấn + 「ても」 sau động từ nghĩa là \"dù làm gì cũng ~\": <span class='gd-jp'>何を言っても、彼は聞きません。</span>(Dù nói gì đi nữa, anh ấy cũng không nghe)</div>","n4-68":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「とか」 giống như cách nói chuyện trong tiếng Việt: <b>「~ này ~ nọ」「kiểu như ~ các thứ」「~ hay gì đó」</b>. Bạn tiện miệng kể vài ví dụ, ý là \"không chỉ có những cái này, còn có cái khác nữa\". Nó khẩu ngữ hơn 「や」 và là kiểu hay nghe nhất giữa bạn bè.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Tiện miệng nêu ví dụ</span>Kể hai ba ví dụ, ngụ ý còn có những thứ khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニでパンとかおにぎりとか買った。</span>(Ở cửa hàng tiện lợi, mình mua bánh mì, cơm nắm các thứ)</div><div class='gd-sec'><span class='gd-tag'>Chỉ nêu một ví dụ để nói nhẹ nhàng hơn</span>Khi rủ ai đó hoặc đưa lời khuyên, chỉ nói một ví dụ cũng được, nghe sẽ không ép buộc, giống như tiếng Việt \"đi ăn cơm hay gì đó không?\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今度、ご飯とか行かない？</span>(Lần tới đi ăn cơm hay gì đó không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>疲れたら、少し寝るとかしたほうがいいよ。</span>(Nếu mệt thì nên ngủ một chút hay gì đó đi)</div><div class='gd-sec'><span class='gd-tag'>Thuật lại lời nghe được</span>「～とか言ってた」＝\"hình như nói là ~\", thể hiện bạn nhớ đại khái, không chắc lắm.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、来週休むとか言ってたよ。</span>(Hình như anh Tanaka nói tuần sau sẽ nghỉ)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Danh từ</b>: thêm とか trực tiếp. <span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンとかおにぎりとか</span></span><br><b>Động từ</b>: dùng thể thường không có ます (thể từ điển) rồi thêm とか. <span class='gd-pair'><span class='gd-jp'>寝ます</span> → <span class='gd-jp'>寝るとか</span></span><br>Sau とか cuối cùng vẫn có thể thêm 「を」「に」「が」, nhưng khi nói chuyện thì 「を」 thường bị bỏ luôn: <span class='gd-jp'>お茶とかお菓子とか買ってきた。</span>(Mình đã mua trà, bánh kẹo các thứ về)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・とか rất khẩu ngữ. Khi viết báo cáo, hoặc nói chuyện với cấp trên hay khách hàng, danh từ nên dùng 「や」, còn việc làm thì dùng 「〜たり〜たりする」 cho an toàn.<br>・Phổ biến nhất là thêm とか vào từng mục (<span class='gd-jp'>AとかBとか</span>), chỉ thêm vào mục đầu cũng có nghe thấy, nhưng hễ có 「とか」 là ngụ ý còn có thứ khác, không phải chỉ có vậy.<br>・「とか」 và 「と」 chỉ khác nhau một chữ nhưng nghĩa khác nhiều: <span class='gd-jp'>と</span> là \"chỉ có những thứ này\", còn <span class='gd-jp'>とか</span> là \"nêu vài ví dụ\".<br>・Có người câu nào cũng chêm とか, nghe sẽ hơi mơ hồ, thiếu dứt khoát; trong hoàn cảnh trang trọng đừng dùng liên tục.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về những thứ có trong tủ lạnh:<br><b>と</b>＝liệt kê hết, chỉ có vậy: <span class='gd-jp'>冷蔵庫に牛乳と卵があります。</span>(Trong tủ lạnh có sữa và trứng)<br><b>や</b>＝nêu ví dụ, còn có thứ khác, cách nói thông thường: <span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>(Trong tủ lạnh có sữa, trứng, v.v.)<br><b>とか</b>＝nêu ví dụ, còn có thứ khác, giọng nói chuyện thân mật: <span class='gd-jp'>冷蔵庫に牛乳とか卵とかあるよ。</span>(Trong tủ lạnh có sữa, trứng các thứ đó)</div><div class='gd-sec'>Ngoài ra, 「や」 chỉ nối được danh từ. Muốn liệt kê \"việc làm\" thì thường dùng <b>「〜たり〜たりする」</b>; khi nói chuyện cũng có thể dùng とか, nhưng khẩu ngữ hơn.<br><span class='gd-jp'>週末は本を読んだり、音楽を聞いたりします。</span>(Cuối tuần tôi đọc sách, nghe nhạc: cách nói thông thường)<br><span class='gd-jp'>週末は本を読むとか、音楽を聞くとかしてる。</span>(Cuối tuần mình đọc sách này, nghe nhạc này các thứ: giọng nói chuyện thân mật)</div><div class='gd-warn'>Mẹo phân biệt nhanh: chỉ có từng ấy thì dùng 「と」; danh từ nêu ví dụ thì trang trọng hơn dùng 「や」, nói chuyện thân mật dùng 「とか」; việc làm nêu ví dụ thì thường dùng 「たり」, nói chuyện cũng có thể dùng 「とか」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là \"liệt kê từng cái một\", nhưng trợ từ <span class='gd-jp'>し</span> dùng để liệt kê <b>lý do</b>: <span class='gd-jp'>安いし、おいしいし、よくこの店に来る。</span>(Vừa rẻ vừa ngon nên mình hay đến quán này)</div>","n4-69":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ずに」chính là <b>phiên bản trang trọng</b> của「〜ないで」, nghĩa là \"chưa làm ～ mà đã ～\" hoặc \"không ～ mà ～\". Giống như trong tiếng Việt, khi nói bạn sẽ bảo \"đi mà không nói một tiếng\", còn khi viết văn thì dùng \"không từ mà biệt\". Nghĩa giống nhau, chỉ là cách viết văn hơn và trang nhã hơn.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Không làm A mà làm B</span>Việc lẽ ra phải làm lại không làm, và làm luôn việc tiếp theo.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べずに出かけた。</span>（Chưa ăn sáng đã ra khỏi nhà）</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にも言わずに会社を辞めた。</span>（Nghỉ việc mà không nói với ai）</div><div class='gd-sec'><span class='gd-tag'>Không dùng A, đổi sang B</span>Bỏ cách làm này, chuyển sang cách khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>バスに乗らずに、歩いて帰った。</span>（Không đi xe buýt mà đi bộ về nhà）</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào</div><div class='gd-sec'>Trước tiên chia động từ về thể ない, sau đó bỏ「ない」đi và thay bằng「ず」hoặc「ずに」.</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>：<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かず</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わず</span></span><br><span class='gd-pair'><span class='gd-jp'>持つ</span> → <span class='gd-jp'>持たず</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>：<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べず</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ず</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, cứ học thuộc luôn)</b>：<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せず</span></span>（không phải しず）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ず</span>（こず）</span></div><div class='gd-h'>Những cách nói hay gặp nhất</div><div class='gd-sec'>Tuy nhìn chung mang tính văn viết, nhưng có vài cách nói người Nhật cũng dùng rất thường trong lúc nói chuyện, bạn có thể học thuộc nguyên câu:</div><div class='gd-ex-line'>・<span class='gd-jp'>遠慮せずに食べてください。</span>（Đừng khách sáo, mời bạn ăn）</div><div class='gd-ex-line'>・<span class='gd-jp'>気にせずに休んでね。</span>（Đừng bận tâm, nghỉ ngơi đi nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>思わず笑ってしまった。</span>（Không nhịn được mà bật cười）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>する phải đổi thành せず</b>, không phải しず：<span class='gd-jp'>勉強せずに</span>。<br>・Động từ nhóm 1 kết thúc bằng「う」thì thể ない dùng「わ」：<span class='gd-jp'>言わず</span>、<span class='gd-jp'>買わず</span>, không phải 言あず。<br>・<span class='gd-jp'>来ず</span> đọc là <b>こず</b>, không phải きず。<br>・Không dùng để nhờ vả người khác: \"Xin đừng ～\" chỉ có thể nói <span class='gd-jp'>食べないでください</span>, không có cách nói「食べずにください」.<br>・Khi trò chuyện với bạn bè, động từ thông thường phần lớn dùng「ないで」; nếu dùng「ずに」suốt thì nghe như đang đọc kịch bản; mấy cách nói cố định ở trên là ngoại lệ.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>ないで</b>＝phiên bản khẩu ngữ：<span class='gd-jp'>傘を持たないで出かけた。</span>（Ra khỏi nhà mà không mang ô）<br><b>ずに</b>＝phiên bản trang trọng, văn viết, nghĩa hoàn toàn giống nhau：<span class='gd-jp'>傘を持たずに出かけた。</span>（Ra khỏi nhà mà không mang ô）<br>Ngoài ra, trong văn bản bạn hay thấy sau「ず」là dấu phẩy ngay lập tức; lúc này thường mang nghĩa \"vì không ～\", khá giống「なくて」：<span class='gd-jp'>バスが来ず、遅刻してしまった。</span>（Xe buýt không đến, kết quả là bị trễ）</div><div class='gd-warn'>Mẹo nhỏ: thấy「ずに」thì cứ thay thầm trong đầu bằng「ないで」là hiểu; khi nói mà chưa chắc, dùng「ないで」là an toàn nhất.</div>","n4-70":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「こと」giống chữ <b>\"việc ～\"</b> trong tiếng Việt. Tiếng Việt có thể nói thẳng \"đọc sách rất vui\", nhưng tiếng Nhật thì không: động từ không thể tự làm chủ ngữ, phải thêm「こと」phía sau để gói \"đọc sách\" thành \"việc đọc sách\", rồi mới đặt vào câu làm chủ ngữ hay làm câu trả lời được.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Làm chủ ngữ của câu</span>Đặt trước「は」「が」, phía sau nói nó như thế nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日運動することは大切です。</span>（Việc tập thể dục mỗi ngày rất quan trọng）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻しないことが大切です。</span>（Việc không đến muộn rất quan trọng）</div><div class='gd-sec'><span class='gd-tag'>Làm câu trả lời</span>Với kiểu câu \"Sở thích của tôi là ～\", \"Ước mơ của tôi là ～\", khi phần「～」là một hành động thì dùng「～ことです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私の趣味は写真を撮ることです。</span>（Sở thích của tôi là chụp ảnh）</div><div class='gd-ex-line'>・<span class='gd-jp'>夢は日本で働くことです。</span>（Ước mơ của tôi là làm việc ở Nhật）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ nối trực tiếp, không cần biến đổi：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むこと</span></span><br>\"Không làm\" dùng thể ない：<span class='gd-pair'><span class='gd-jp'>読まない</span> → <span class='gd-jp'>読まないこと</span></span><br>\"Đã làm\" dùng thể た：<span class='gd-pair'><span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだこと</span></span><br>Tính từ cũng nối được, lúc này giống \"điều ～\" hơn：<span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しいこと</span></span>（điều vui）. Với tính từ đuôi な nhớ thêm な：<span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きなこと</span></span>（điều mình thích）</div><div class='gd-sec'>Thật ra bạn đã gặp nó từ lâu rồi: chữ「こと」trong <span class='gd-jp'>ことができます</span>、<span class='gd-jp'>たことがあります</span>、<span class='gd-jp'>ことにします</span> đều là \"việc ～\" này.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Theo trực giác của tiếng Việt, bạn đem động từ làm chủ ngữ luôn: <span class='gd-jp'>本を読むが好きです</span> là sai, ở giữa nhất định phải có <span class='gd-jp'>こと</span> hoặc <span class='gd-jp'>の</span>：<span class='gd-jp'>本を読むことが好きです</span>。<br>・Quên thêm な sau tính từ đuôi な: phải nói <span class='gd-jp'>好きなこと</span>, không phải 好きこと, cũng không phải 好きだこと。<br>・「Danh từ＋のこと」mang nghĩa khác, là \"về ～\"：<span class='gd-jp'>彼のことが好きです</span> nghĩa là \"tôi thích anh ấy (con người này)\", khác với cách biến hành động thành danh từ ở đây, đừng trộn lẫn.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>「の」cũng có thể biến hành động thành \"việc ～\", nhiều khi dùng cái nào cũng được, nhưng <b>có vài vị trí chỉ dùng được một trong hai</b>, không đơn giản chỉ là \"こと văn viết hơn\" đâu.</div><div class='gd-sec'><span class='gd-tag'>Dùng cái nào cũng được</span>Khi phía sau là các từ đánh giá như「好き」「大切」「難しい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むのが好きです。</span>（Tôi thích đọc sách: dùng nhiều khi nói chuyện）</div><div class='gd-ex-line'>・<span class='gd-jp'>本を読むことが好きです。</span>（Tôi thích đọc sách: trang trọng hơn một chút）</div><div class='gd-sec'><span class='gd-tag'>Chỉ dùng được こと</span>Cuối câu dạng「～は～ことです」, và các mẫu cố định như ことができます.</div><div class='gd-ex-line'>・<span class='gd-jp'>趣味は本を読むことです。</span>（Sở thích của tôi là đọc sách）</div><div class='gd-sec'>Đổi thành「のです」là sai, vì「の」ở đây sẽ bị nghe thành「のです」mang sắc thái giải thích, câu rất không tự nhiên, nên cuối câu nhất định phải dùng「ことです」. Tương tự, <span class='gd-jp'>日本語を話すことができます</span> cũng không thể đổi sang の.</div><div class='gd-sec'><span class='gd-tag'>Chỉ dùng được の</span>Tận mắt thấy, tận tai nghe một hành động đang diễn ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>犬が走るのを見ました。</span>（Tôi thấy con chó đang chạy）</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋で誰かが歌っているのが聞こえます。</span>（Nghe thấy có người đang hát ở phòng bên cạnh）</div><div class='gd-sec'>Ở đây nói <span class='gd-jp'>走ることを見ました</span>、<span class='gd-jp'>歌っていることが聞こえます</span> đều không được.</div><div class='gd-warn'>Mẹo nhỏ: trước「～です」ở cuối câu và trong các mẫu cố định như ことができる thì dùng <b>こと</b>; thấy, nghe một hành động ngay trước mắt thì dùng <b>の</b>; với「好き」「大切」thì cái nào cũng được, khi nói chuyện dùng の nghe thuận miệng hơn.</div>","n4-65":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt khi muốn lịch sự sẽ nói “Xin hỏi <b>quý danh</b> của anh/chị là gì ạ?” thay vì “Bạn tên gì?”. Tiếng Nhật cũng có cách làm tương tự: thêm <b>お</b> hoặc <b>ご</b> trước danh từ, nghe sẽ lịch sự và nhã nhặn hơn.<br>「<span class='gd-jp'>ございます</span>」là <b>phiên bản dùng ở cửa hàng, khách sạn</b> của <span class='gd-jp'>あります</span>. Nghĩa vẫn là “có, ở”, chỉ là lịch sự hơn.</div><div class='gd-h'>Khi nào dùng お・ご</div><div class='gd-sec'><span class='gd-tag'>Đồ của đối phương</span>Khi nói đến tên, gia đình, địa chỉ của đối phương, thêm お・ご để thể hiện sự tôn trọng.</div><div class='gd-ex-line'>・<span class='gd-jp'>お名前をお願いします。</span>(Phiền bạn cho tôi biết tên của bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>ご家族はお元気ですか。</span>(Gia đình bạn vẫn khỏe chứ?)</div><div class='gd-sec'><span class='gd-tag'>Làm câu nói nhã hơn</span>Một số từ thêm お・ご chỉ để nghe nhã nhặn hơn, nói về chuyện của mình cũng dùng được và rất hay gặp trong đời sống hằng ngày.</div><div class='gd-ex-line'>・<span class='gd-jp'>お茶を飲みませんか。</span>(Bạn uống chút trà nhé?)</div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯を食べました。</span>(Tôi ăn cơm rồi)</div><div class='gd-h'>Gắn thế nào: お hay ご?</div><div class='gd-sec'><b>Từ thuần Nhật</b> (chữ Hán đọc theo âm Kun, hoặc vốn là từ viết bằng hiragana) thường đi với <b>お</b>:<br><span class='gd-jp'>お名前</span>、<span class='gd-jp'>お店</span>、<span class='gd-jp'>お水</span>、<span class='gd-jp'>お手紙</span></div><div class='gd-sec'><b>Từ Hán có gốc từ Trung Quốc</b> (đọc theo âm On, nghe hơi giống âm Hán Việt, thường gồm hai chữ Hán) thường đi với <b>ご</b>:<br><span class='gd-jp'>ご住所</span>、<span class='gd-jp'>ご家族</span>、<span class='gd-jp'>ご予約</span>、<span class='gd-jp'>ご連絡</span></div><div class='gd-sec'>Tuy nhiên <b>ngoại lệ khá nhiều</b>, ví dụ <span class='gd-jp'>お電話</span>、<span class='gd-jp'>お時間</span>、<span class='gd-jp'>お食事</span> đều là từ Hán nhưng cố định đi với お. Gặp từ nào thì nhớ từ đó, đừng cố áp quy tắc một cách cứng nhắc.<br>Từ ngoại lai viết bằng katakana thường không thêm: cứ nói <span class='gd-jp'>コーヒー</span> là được.</div><div class='gd-h'>ございます: dạng lịch sự của あります</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ございます</span></span><span class='gd-pair'><span class='gd-jp'>ありません</span> → <span class='gd-jp'>ございません</span></span><span class='gd-pair'><span class='gd-jp'>ありました</span> → <span class='gd-jp'>ございました</span></span><br>Thật ra bạn đã dùng nó từ lâu rồi: trong <span class='gd-jp'>ありがとうございます</span>、<span class='gd-jp'>おはようございます</span> chính là từ này đấy.</div><div class='gd-ex-line'>・<span class='gd-jp'>お手洗いはあちらにございます。</span>(Nhà vệ sinh ở phía bên kia ạ)</div><div class='gd-ex-line'>・<span class='gd-jp'>赤いのもございますよ。</span>(Bên em cũng có loại màu đỏ nữa đấy ạ)</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございません。</span>(Thành thật xin lỗi ạ)</div><div class='gd-sec'>Ngoài ra, <b>でございます</b> là dạng lịch sự của <span class='gd-jp'>です</span>, nhân viên cửa hàng rất hay dùng khi giới thiệu đồ:</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらがメニューでございます。</span>(Đây là thực đơn ạ)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・お・ご mang nghĩa tôn trọng <b>không được dùng cho bản thân</b>: khi tự giới thiệu hãy nói <span class='gd-jp'>私の名前は</span>, không nói 「私のお名前は」. Chỉ những từ kiểu “làm câu nói nhã hơn” như <span class='gd-jp'>お茶</span>、<span class='gd-jp'>ご飯</span> thì bản thân mình cũng dùng được.<br>・<span class='gd-jp'>ございます</span> chỉ dùng cho <b>đồ vật, sự việc</b>, không dùng cho người. Muốn nói “có người ở đó không” phải dùng <span class='gd-jp'>おります</span> hoặc <span class='gd-jp'>いらっしゃいます</span> ở phần dưới.<br>・「でございます」không dùng để nói về đối phương: khi hỏi “Anh là ông Tanaka phải không ạ?” hãy nói <span class='gd-jp'>田中様でいらっしゃいますか</span>, không nói 「田中様でございますか」.<br>・お・ご không phải thêm càng nhiều càng tốt, thêm vào những từ người ta không quen thêm sẽ nghe lạ tai. Cứ học trước những từ sách giáo khoa và nhân viên cửa hàng hay dùng là đủ.</div><div class='gd-h'>Phân biệt với những từ trông giống nhau</div><div class='gd-sec'>Cùng ở trong một cửa hàng, khi nói “có, ở”:<br><b>あります</b> (lịch sự thông thường): <span class='gd-jp'>トイレはあちらにあります。</span>(Nhà vệ sinh ở phía bên kia)<br><b>ございます</b> (lịch sự hơn, dùng cho đồ vật): <span class='gd-jp'>お手洗いはあちらにございます。</span>(Nhà vệ sinh ở phía bên kia ạ)<br><b>おります</b> (nói về người phía mình, hạ thấp bản thân): <span class='gd-jp'>店長は事務所におります。</span>(Cửa hàng trưởng đang ở văn phòng)<br><b>いらっしゃいます</b> (nói về đối phương hoặc khách, nâng đối phương lên): <span class='gd-jp'>田中様はいらっしゃいますか。</span>(Xin hỏi ông Tanaka có ở đây không ạ?)</div><div class='gd-warn'>Mẹo phán đoán: nói về <b>đồ vật</b> dùng ございます; nói về <b>người</b> thì người phía mình dùng おります, đối phương dùng いらっしゃいます.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>お・ご còn có thể gắn vào động từ để thành cách nói tôn kính hoặc khiêm nhường, ví dụ <span class='gd-jp'>少々お待ちください。</span>(Xin vui lòng đợi một chút). Bạn có thể xem tiếp phần 「尊敬語」「謙譲語」.</div>","n4-66":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể rút gọn trong tiếng Nhật là khi <b>nói nhanh nên các âm dính vào nhau</b>. Giống như tiếng Việt nói nhanh “không biết” thành “hổng biết”, người Nhật khi trò chuyện cũng nói <span class='gd-jp'>見ている</span> thành <span class='gd-jp'>見てる</span>. Nghĩa hoàn toàn giống nhau, chỉ là khẩu ngữ hơn, thoải mái hơn.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trò chuyện hằng ngày</span>Khi nói chuyện với bạn bè, người nhà; trong phim truyền hình Nhật, anime, manga hầu như toàn là cách nói này.</div><div class='gd-sec'><span class='gd-tag'>Không nên dùng</span>Khi viết báo cáo, gửi mail cho sếp, phỏng vấn và những dịp trang trọng khác, hãy dùng dạng đầy đủ.</div><div class='gd-h'>Bốn kiểu nghe nhiều nhất</div><div class='gd-sec'><b>1. ている → てる</b>: bỏ chữ「い」ở giữa.<br><span class='gd-pair'><span class='gd-jp'>見ている</span> → bỏ い → <span class='gd-jp'>見てる</span></span><br>Nếu vốn là「でいる」thì thành「でる」: <span class='gd-pair'><span class='gd-jp'>読んでいる</span> → <span class='gd-jp'>読んでる</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何してるの？</span>(Bạn đang làm gì thế?)</div><div class='gd-sec'><b>2. ておく → とく</b>: 「て」và「お」dính lại thành「と」.<br><span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><br>Nếu vốn là「でおく」thì thành「どく」: <span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>飲み物、買っとくね。</span>(Đồ uống để mình mua trước nhé)</div><div class='gd-sec'><b>3. てしまう → ちゃう</b>: 「てしま」rút gọn thành「ちゃ」.<br><span class='gd-pair'><span class='gd-jp'>食べてしまう</span> → <span class='gd-jp'>食べちゃう</span></span><br>Nếu vốn là「でしまう」thì thành「じゃう」: <span class='gd-pair'><span class='gd-jp'>飲んでしまう</span> → <span class='gd-jp'>飲んじゃう</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ケーキ、全部食べちゃった。</span>(Mình ăn hết cả bánh kem rồi)</div><div class='gd-sec'><b>4. では → じゃ</b>: <span class='gd-pair'><span class='gd-jp'>学生ではない</span> → <span class='gd-jp'>学生じゃない</span></span></div><div class='gd-h'>Rút gọn xong vẫn chia được</div><div class='gd-sec'>Dạng đã rút gọn vẫn chia quá khứ, phủ định, thể て như bình thường:<br><span class='gd-pair'><span class='gd-jp'>見てる</span> → <span class='gd-jp'>見てた</span>／<span class='gd-jp'>見てない</span></span><br><span class='gd-pair'><span class='gd-jp'>買っとく</span> → <span class='gd-jp'>買っといた</span>／<span class='gd-jp'>買っといて</span></span><br><span class='gd-pair'><span class='gd-jp'>食べちゃう</span> → <span class='gd-jp'>食べちゃった</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>宿題、まだ終わってない。</span>(Bài tập vẫn chưa làm xong)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までに読んどいて。</span>(Đọc trước giùm mình trước ngày mai nhé)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Nếu gốc là「で」thì rút gọn xong cũng phải giữ âm đục: đúng là <span class='gd-jp'>飲んじゃう</span>, không phải 飲んちゃう; đúng là <span class='gd-jp'>読んどく</span>, không phải 読んとく.<br>・<span class='gd-jp'>見てる</span> (đang xem) và <span class='gd-jp'>見とく</span> (xem trước) nghe rất giống nhau nhưng nghĩa hoàn toàn khác, khi nghe phải chú ý.<br>・Kiểu “rút gọn + ます” như <span class='gd-jp'>見てます</span> rất hay nghe ở cửa hàng, giữa đồng nghiệp với nhau, nhưng khi viết văn bản, viết thư vẫn phải viết <span class='gd-jp'>見ています</span>.<br>・Rút gọn chỉ làm cách nói nhẹ nhàng hơn, nghĩa không đổi: <span class='gd-jp'>ちゃう</span> vẫn có thể là “làm xong”, cũng có thể là “lỡ làm mất rồi, chết rồi”.</div><div class='gd-h'>Phân biệt với những từ trông giống nhau</div><div class='gd-sec'><span class='gd-jp'>ては</span> cũng rút gọn thành <span class='gd-jp'>ちゃ</span>, chỉ khác <span class='gd-jp'>ちゃう</span> một chút nhưng nghĩa khác nhiều:<br><span class='gd-jp'>食べちゃった。</span>(Ăn hết rồi)＝<span class='gd-jp'>食べてしまった</span><br><span class='gd-jp'>食べちゃだめ。</span>(Không được ăn)＝<span class='gd-jp'>食べてはだめ</span></div><div class='gd-warn'>Mẹo phán đoán: nếu phía sau là「う」「った」thì là てしまう; nếu phía sau là「だめ」「いけない」thì là ては.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Trong khẩu ngữ,「なければ」rút gọn thành「なきゃ」: <span class='gd-jp'>もう帰らなきゃ。</span>(Mình phải về rồi)</div>","n4-71":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói \"có mùi thơm\", \"vọng lại tiếng động lạ\", nhưng tiếng Nhật không dùng 「ある」 mà dùng <b>「danh từ＋がする」</b>. Ý là âm thanh, vị hay mùi tự xuất hiện và bạn cảm nhận được. Nói lịch sự thì là 「がします」.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Thứ bạn cảm nhận (danh từ) ＋ が ＋ します (với bạn bè thì dùng する).<br>Phía trước thường thêm một tính từ để nói đó là âm thanh hay mùi vị như thế nào:<br><span class='gd-pair'><span class='gd-jp'>匂い</span> → <span class='gd-jp'>いい匂いがします</span></span> (có mùi thơm)<br><span class='gd-pair'><span class='gd-jp'>音</span> → <span class='gd-jp'>変な音がします</span></span> (có tiếng động lạ)</div><div class='gd-h'>Những trường hợp hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Âm thanh</span><span class='gd-jp'>音</span> (tiếng của đồ vật), <span class='gd-jp'>声</span> (tiếng của người hoặc động vật)</div><div class='gd-ex-line'>・<span class='gd-jp'>外で変な音がします。</span> (Bên ngoài có tiếng động lạ)</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋から子どもの声がする。</span> (Phòng bên cạnh vọng sang tiếng trẻ con)</div><div class='gd-sec'><span class='gd-tag'>Mùi</span><span class='gd-jp'>匂い</span>, <span class='gd-jp'>香り</span> (hương thơm, cách nói nghe hay hơn)</div><div class='gd-ex-line'>・<span class='gd-jp'>台所からいい匂いがする。</span> (Từ nhà bếp bay ra mùi thơm)</div><div class='gd-sec'><span class='gd-tag'>Vị</span><span class='gd-jp'>味</span> mà bạn nếm được khi ăn uống</div><div class='gd-ex-line'>・<span class='gd-jp'>このお茶、レモンの味がする。</span> (Trà này có vị chanh)</div><div class='gd-sec'><span class='gd-tag'>Cảm giác</span><span class='gd-jp'>感じがする</span> nghĩa là \"mang lại cảm giác ～\", còn <span class='gd-jp'>気がする</span> nghĩa là \"tôi cứ cảm thấy ～\". Trước <span class='gd-jp'>気がする</span> có thể đặt nguyên cả một câu (động từ dùng thể thông thường, tức là dạng không có ます).</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は優しい感じがします。</span> (Người đó mang lại cảm giác rất dịu dàng)</div><div class='gd-ex-line'>・<span class='gd-jp'>前に会った気がします。</span> (Tôi có cảm giác trước đây đã gặp bạn rồi)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ dùng <b>が</b>, không phải を: phải nói <span class='gd-jp'>音がする</span>, không nói được 「音をする」.<br>・Khi nói \"bây giờ đang ngửi thấy, nghe thấy\" thì dùng がする, thường không nói 「いい匂いがあります」.<br>・Tiếng Việt quen nói \"<b>tôi</b> ngửi thấy mùi thơm\", nhưng chủ thể trong tiếng Nhật là <b>chính cái mùi</b>, nên không nói 「私はいい匂いがします」. Muốn nói nơi nào có mùi, hãy nói <span class='gd-jp'>この部屋は変な匂いがします</span> (Căn phòng này có mùi lạ).<br>・<b>Thứ nhìn bằng mắt thì không dùng がする</b>: màu sắc, hình dáng không nói như vậy được, không nói 「きれいな色がします」.<br>・Phía trước nhất định phải là danh từ: không nói 「甘いがします」, mà phải nói <span class='gd-jp'>甘い匂いがします</span> hoặc <span class='gd-jp'>甘い味がします</span>.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>音がする vs 聞こえる</b><br><span class='gd-jp'>外で音がする。</span> (Bên ngoài có tiếng động): trọng tâm là <b>có âm thanh xuất hiện</b>.<br><span class='gd-jp'>外の音が聞こえる。</span> (Nghe được tiếng bên ngoài): trọng tâm là <b>nghe được hay không</b>, nên hay dùng trong tình huống như <span class='gd-jp'>よく聞こえない</span> (nghe không rõ lắm).</div><div class='gd-sec'><b>気がする vs と思う</b><br><span class='gd-jp'>彼は来ないと思います。</span> (Tôi nghĩ anh ấy sẽ không đến): là suy nghĩ hay phán đoán khá rõ ràng.<br><span class='gd-jp'>彼は来ない気がします。</span> (Tôi cứ có cảm giác anh ấy sẽ không đến): khó giải thích rõ lý do, chỉ là trực giác, giọng điệu kém chắc chắn hơn.</div><div class='gd-warn'>Mẹo phân biệt: \"có âm thanh, có mùi\" dùng がする, \"nghe được hay không\" dùng 聞こえる; suy nghĩ có cơ sở thì dùng と思う, chỉ là trực giác thì dùng 気がする.</div>","n4-72":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜さ」biến tính từ thành <b>danh từ</b>, giống như tiếng Việt biến \"cao\" thành \"chiều cao\", \"nặng\" thành \"độ nặng\", \"quan trọng\" thành \"tầm quan trọng\". <span class='gd-jp'>高い</span> là \"cao\", còn <span class='gd-jp'>高さ</span> là \"chiều cao\". Dùng để nói một thứ <b>～ đến mức nào</b>, hoặc <b>cảm giác ～ ấy</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Tính từ い</b>: bỏ 「い」 ở cuối, thêm 「さ」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → bỏ い → <span class='gd-jp'>高さ</span></span> (chiều cao)<br><span class='gd-pair'><span class='gd-jp'>深い</span> → <span class='gd-jp'>深さ</span></span> (độ sâu) <span class='gd-pair'><span class='gd-jp'>重い</span> → <span class='gd-jp'>重さ</span></span> (trọng lượng) <span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒さ</span></span> (cái lạnh) <span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きさ</span></span> (kích cỡ)</div><div class='gd-sec'><b>Tính từ な</b>: thêm thẳng 「さ」, không cần chen な vào giữa.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利さ</span></span> (sự tiện lợi) <span class='gd-pair'><span class='gd-jp'>親切</span> → <span class='gd-jp'>親切さ</span></span> (sự tử tế) <span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切さ</span></span> (tầm quan trọng)</div><div class='gd-sec'><b>Cần học thuộc riêng</b>:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさ</span></span> (ưu điểm, điểm tốt. Vì <span class='gd-jp'>いい</span> vốn biến từ <span class='gd-jp'>よい</span>, nên không nói いいさ)<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静けさ</span></span> (sự yên tĩnh. Thường không nói 静かさ)</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói về con số, kích thước</span>Với những thứ đo được như chiều cao, chiều dài, trọng lượng, phía sau thường có con số hoặc 「どのくらい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山の高さは3776メートルです。</span> (Chiều cao của núi Phú Sĩ là 3776 mét)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋の広さはどのくらいですか。</span> (Căn phòng này rộng khoảng bao nhiêu?)</div><div class='gd-sec'><span class='gd-tag'>Nói về cảm nhận, đặc tính</span>Nói một thứ mang lại cảm giác mạnh đến đâu, hoặc ưu điểm, nét đặc trưng của nó.</div><div class='gd-ex-line'>・<span class='gd-jp'>北海道の冬の寒さにびっくりしました。</span> (Tôi giật mình vì cái lạnh của mùa đông Hokkaido)</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になって、健康の大切さが分かりました。</span> (Sau khi bị bệnh, tôi mới hiểu sức khỏe quan trọng đến thế nào)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店のよさは安いところです。</span> (Ưu điểm của quán này là giá rẻ)</div><div class='gd-ex-line'>・<span class='gd-jp'>夜の静けさが好きです。</span> (Tôi thích sự yên tĩnh của ban đêm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải bỏ い: là <span class='gd-jp'>高さ</span>, không phải 高いさ.<br>・Tính từ な không thêm な: là <span class='gd-jp'>便利さ</span>, không phải 便利なさ.<br>・Thêm さ vào là thành danh từ rồi, phía trước nối bằng 「の」, phía sau đi với 「は・が・を・に」: <span class='gd-jp'>冬の寒さ</span>, không phải 冬は寒さ.<br>・「高さ」「重さ」「大きさ」là <b>thước đo trung tính</b>, giống như \"chiều cao\" trong tiếng Việt. Dù ngọn núi có thấp đến đâu, khi hỏi vẫn nói <span class='gd-jp'>高さ</span>, không đổi thành 低さ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Bạn đã học <span class='gd-jp'>楽しみ</span> từ lâu rồi, nó và <span class='gd-jp'>楽しさ</span> đều bắt nguồn từ <span class='gd-jp'>楽しい</span> nhưng nghĩa lại khác nhau.<br><b>楽しさ</b> = vui đến mức nào, niềm vui đó: <span class='gd-jp'>日本語の楽しさが分かりました。</span> (Tôi đã hiểu được niềm vui khi học tiếng Nhật)<br><b>楽しみ</b> = sự mong chờ, háo hức: <span class='gd-jp'>旅行を楽しみにしています。</span> (Tôi rất mong chờ chuyến du lịch)</div><div class='gd-warn'>Mẹo phân biệt: khi nói mức độ như \"vui đến thế nào, lạnh đến thế nào, quan trọng đến thế nào\" thì dùng さ; khi nói \"rất mong chờ\" thì dùng <span class='gd-jp'>楽しみ</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Mẫu câu rất tiện khi hỏi về kích thước: <span class='gd-jp'>〜の長さはどのくらいですか。</span> (Chiều dài của ～ khoảng bao nhiêu?) Thay 長さ bằng <span class='gd-jp'>重さ</span>, <span class='gd-jp'>大きさ</span>, <span class='gd-jp'>深さ</span> là bạn có thể hỏi về đủ loại đồ vật.</div>","n4-73":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜ことがあります」nghĩa là <b>「đôi khi có thể ～」</b>. Việc này <b>không xảy ra lần nào cũng vậy, nhưng thỉnh thoảng vẫn xảy ra</b>. Giống như thông báo ở nhà ga hay trang mua sắm online ghi \"có thể bị chậm trễ\", nhắc bạn rằng \"tình huống này hoàn toàn có thể gặp phải\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Đôi khi <b>có</b> làm: thể từ điển＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れることがあります</span></span>（đôi khi bị trễ, bị chậm）<br>Đôi khi <b>không</b> làm: thể ない＋ことがあります<br><span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないことがあります</span></span>（đôi khi không ăn）<br>Nói với bạn bè thì dùng thể thường <span class='gd-jp'>ことがある</span>, nghĩa vẫn y như vậy.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói về thói quen của mình</span>Không phải ngày nào cũng vậy, chỉ thỉnh thoảng thôi. Thường đi cùng <span class='gd-jp'>ときどき</span>（đôi khi）và <span class='gd-jp'>たまに</span>（thỉnh thoảng）.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいとき、朝ご飯を食べないことがあります。</span>（Lúc bận, đôi khi tôi không ăn sáng）</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに電車で寝てしまうことがある。</span>（Thỉnh thoảng tôi ngủ quên trên tàu）</div><div class='gd-sec'><span class='gd-tag'>Nhắc nhở, thông báo</span>Cửa hàng, nhà ga, phần mô tả sản phẩm rất hay dùng, để báo trước với bạn rằng \"chuyện này có thể xảy ra đấy nhé\".</div><div class='gd-ex-line'>・<span class='gd-jp'>雨の日は、バスが遅れることがあります。</span>（Những ngày mưa, xe buýt đôi khi bị trễ）</div><div class='gd-ex-line'>・<span class='gd-jp'>商品の色が写真と違うことがあります。</span>（Màu sản phẩm đôi khi có thể khác với ảnh）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Việc xảy ra <b>mỗi ngày, chắc chắn, lúc nào cũng vậy</b> thì không dùng được. <span class='gd-jp'>毎日コーヒーを飲むことがあります</span> là sai; uống mỗi ngày thì nói thẳng <span class='gd-jp'>毎日コーヒーを飲みます</span>.<br>・Chữ \"sẽ\" hay \"có thể\" trong tiếng Việt có rất nhiều nghĩa, không phải chỗ nào cũng thay được bằng ことがあります. \"Tôi biết nói tiếng Nhật\" là <span class='gd-jp'>日本語が話せます</span>; \"Ngày mai trời sẽ mưa\" là <span class='gd-jp'>明日は雨が降るでしょう</span>. Chỉ khi nghĩa là \"<b>đôi khi có lúc</b>\" thì mới dùng ことがあります.<br>・Phía trước nhất định phải là thể từ điển hoặc thể ない. Chỉ cần viết thành thể た là nghĩa đổi hẳn, phần dưới sẽ nói.<br>・Bạn sẽ hay nghe <span class='gd-jp'>遅れることもあります</span>. Đổi が thành も thì sắc thái thành \"<b>cũng có khả năng</b> ～\", nhẹ nhàng hơn, thông báo rất hay dùng.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Thể từ điển＋ことがある</b>＝đôi khi có (nói về xu hướng ở hiện tại)<br><span class='gd-jp'>この電車は遅れることがあります。</span>（Chuyến tàu này đôi khi bị trễ）<br><b>Thể た＋ことがある</b>＝đã từng ～ (nói về kinh nghiệm trong quá khứ)<br><span class='gd-jp'>この電車は遅れたことがあります。</span>（Chuyến tàu này đã từng bị trễ）<br>Chỉ khác một chữ: câu trước là \"bình thường thỉnh thoảng vẫn vậy\", câu sau là \"trước đây từng xảy ra (một lần trở lên)\".</div><div class='gd-sec'><b>かもしれません</b>＝đoán xem <b>một lần nào đó</b> có xảy ra không<br><span class='gd-jp'>明日は電車が遅れるかもしれません。</span>（Ngày mai tàu có thể bị trễ）<br><b>ことがあります</b>＝nói về tình trạng <b>thường ngày</b>, thỉnh thoảng sẽ gặp<br><span class='gd-jp'>雪の日は電車が遅れることがあります。</span>（Những ngày tuyết rơi, tàu đôi khi bị trễ）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: \"đã từng ～\" dùng thể た＋ことがある; \"bình thường đôi khi có ～\" dùng thể từ điển＋ことがある; \"lần này có thể ～\" dùng かもしれません.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Danh từ cũng dùng được, chỉ cần thêm <span class='gd-jp'>の</span> sau danh từ: <span class='gd-jp'>この時間は満席のことがあります。</span>（Khung giờ này đôi khi kín chỗ）</div>","n4-74":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>Trong tiếng Việt, muốn lịch sự với bề trên, bạn sẽ thêm \"ạ\", \"thưa\" hay gọi \"thầy\", \"sếp\". Tiếng Nhật cũng có một cách khá giống: <b>biến hành động của người lớn tuổi, cấp trên, khách hàng thành dạng 「れる・られる」</b> là đã mang sắc thái tôn kính.<br>Ví dụ \"giám đốc đã về rồi\", bình thường nói <span class='gd-jp'>帰りました</span>, muốn tôn kính hơn thì nói <span class='gd-jp'>帰られました</span>. Đây là kiểu kính ngữ dễ làm quen nhất, mức độ lịch sự khá nhẹ.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói về hành động của người trên</span>Khi trò chuyện với người khác về việc thầy cô, cấp trên đã làm.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長はもう帰られました。</span>（Trưởng phòng đã về rồi ạ）</div><div class='gd-ex-line'>・<span class='gd-jp'>社長は来週、大阪に出張されます。</span>（Tuần sau giám đốc sẽ đi công tác Osaka）</div><div class='gd-sec'><span class='gd-tag'>Hỏi trực tiếp đối phương</span>Hỏi thẳng thầy cô, khách hàng định làm gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生はいつ日本へ行かれますか。</span>（Khi nào thầy đi Nhật ạ?）</div><div class='gd-ex-line'>・<span class='gd-jp'>何を飲まれますか。</span>（Anh/chị dùng gì ạ?）</div><div class='gd-h'>Cách biến đổi: xem động từ thuộc nhóm nào</div><div class='gd-sec'>Tin vui: hình dạng của nó <b>giống hệt thể bị động (受身形)</b>, biết thể bị động là coi như biết luôn cái này.</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段)</b>: đổi âm cuối sang âm hàng 「あ」 cùng hàng, rồi thêm 「れる」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành か → <span class='gd-jp'>行かれる</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読まれる</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話される</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰られる</span></span><br>Động từ kết thúc bằng 「う」 thì đổi thành <b>わ</b>, không phải あ: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会われる</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ 「る」 ở cuối rồi thêm 「られる」.<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけられる</span></span><span class='gd-pair'><span class='gd-jp'>始める</span> → <span class='gd-jp'>始められる</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span>（<span class='gd-pair'><span class='gd-jp'>出発する</span> → <span class='gd-jp'>出発される</span></span>）、<span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Khi nói thực tế, thường ghép tiếp thành thể ます: <span class='gd-pair'><span class='gd-jp'>行かれる</span> → <span class='gd-jp'>行かれます</span></span>, quá khứ là <span class='gd-jp'>行かれました</span>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chỉ dùng cho <b>người khác</b>. Dùng dạng tôn kính cho hành động của chính mình rất kỳ, <span class='gd-jp'>私は明日行かれます</span> là sai, phải nói <span class='gd-jp'>私は明日行きます</span>.<br>・Khi nói chuyện với người ngoài về <b>người nhà mình</b> cũng không dùng, không thể nói <span class='gd-jp'>父は帰られました</span>, chỉ cần nói <span class='gd-jp'>父は帰りました</span>.<br>・<span class='gd-jp'>会う</span> thành <span class='gd-jp'>会われる</span>, không phải 「あれる」.<br>・Dạng tôn kính của nhóm 2 và <span class='gd-jp'>来る</span> lại trùng hình với thể khả năng (có thể ～): <span class='gd-jp'>来られます</span> có thể là \"ngài sẽ đến\" hoặc \"có thể đến\". Sợ bị hiểu nhầm, người Nhật thường chuyển sang cách nói tôn kính riêng, như <span class='gd-jp'>来る</span> đổi thành <span class='gd-jp'>いらっしゃる</span>, <span class='gd-jp'>食べる</span> đổi thành <span class='gd-jp'>召し上がる</span>, <span class='gd-jp'>見る</span> đổi thành <span class='gd-jp'>ご覧になる</span>.<br>・Đừng chồng hai loại kính ngữ lên nhau. <span class='gd-jp'>お帰りになられる</span> tuy hay nghe, nhưng bị coi là dùng quá đà, là cách nói sai, chọn một kiểu thôi.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Thể tôn kính</b>＝người trên <b>tự mình</b> làm việc này, trong câu không có ai \"bị\" gì cả:<br><span class='gd-jp'>部長が帰られました。</span>（Trưởng phòng đã về rồi）<br><b>Thể bị động</b>＝có người <b>\"bị\"</b> làm gì đó, trước người thực hiện hành động thường có 「に」:<br><span class='gd-jp'>部長に怒られました。</span>（Tôi bị trưởng phòng mắng）<br><b>Thể khả năng</b>＝hỏi <b>\"có thể hay không\"</b>:<br><span class='gd-jp'>先生は刺身が食べられますか。</span>（Thầy có ăn được sashimi không ạ?）<br>Cùng là 「られます」, nghĩa phải dựa vào ngữ cảnh để xác định.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: chủ ngữ là người trên, chính họ đang làm, không có nghĩa \"bị\" cũng không có nghĩa \"có thể hay không\", thì đó là thể tôn kính.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói lịch sự hơn là 「お＋thể ます bỏ ます＋になる」: <span class='gd-jp'>社長はお帰りになりました。</span>（Giám đốc đã về rồi ạ）, lễ phép hơn <span class='gd-jp'>帰られました</span>, bạn có thể học tiếp bài 「尊敬語」.</div>","n4-75":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói “uống, không uống, uống được, bị uống, cho anh ấy uống” là thêm từ vào trước hoặc sau “uống”. Tiếng Nhật thì <b>đổi phần đuôi của động từ</b>, và đổi thế nào còn tùy động từ đó thuộc nhóm nào. Vì vậy dù học dạng biến đổi nào, <b>bước đầu tiên luôn là phân nhóm</b>. Phân đúng rồi thì phần sau chỉ là áp dụng quy tắc.</div><div class='gd-h'>Bước 1: Xác định động từ thuộc nhóm nào</div><div class='gd-sec'>Nhìn dạng từ điển (dạng gốc chưa biến đổi, tra được trong từ điển, ví dụ <span class='gd-jp'>飲む</span>、<span class='gd-jp'>食べる</span>), rồi lần lượt tự hỏi ba câu:<br><b>1. Có phải する hoặc 来る không?</b> Nếu đúng thì đó là <b>nhóm 3 (する・来る)</b>. Dạng “danh từ＋する” như <span class='gd-jp'>勉強する</span>、<span class='gd-jp'>掃除する</span> cũng thuộc nhóm này.<br><b>2. Âm cuối có khác る không?</b> Như <span class='gd-jp'>飲む</span>、<span class='gd-jp'>書く</span>、<span class='gd-jp'>買う</span>、<span class='gd-jp'>話す</span> thì luôn là <b>nhóm 1 (động từ 五段)</b>.<br><b>3. Nếu cuối là る, hãy nghe âm đứng ngay trước る:</b><br>Trước đó là âm hàng “i” hoặc “e” thì phần lớn là <b>nhóm 2 (động từ 一段)</b>: <span class='gd-jp'>食べる</span> (べ là be)、<span class='gd-jp'>起きる</span> (き là ki)、<span class='gd-jp'>見る</span> (み là mi).<br>Trước đó là âm “a, u, o” thì là <b>nhóm 1</b>: <span class='gd-jp'>わかる</span>、<span class='gd-jp'>作る</span>、<span class='gd-jp'>乗る</span>.<br>Ở bước 3 có vài ngoại lệ: <span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>、<span class='gd-jp'>要る</span> trông giống nhóm 2 nhưng thật ra là <b>nhóm 1</b>, bạn cần học thuộc luôn.</div><div class='gd-h'>Cùng một động từ, sáu dạng hay dùng nhất</div><div class='gd-sec'><b>Nhóm 1: lấy <span class='gd-jp'>飲む</span> làm ví dụ</b>. Cách làm là đổi chữ cuối “む” thành âm khác trong cùng hàng:<br>Đổi む thành み, thêm ます: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span> (uống, cách nói lịch sự)<br>Đổi む thành ま, thêm ない: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span> (không uống)<br>Đổi む thành め, thêm る: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲める</span></span> (uống được, dạng khả năng)<br>Đổi む thành ま, thêm れる: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まれる</span></span> (bị uống, dạng bị động)<br>Đổi む thành ま, thêm せる: <span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span> (cho/bắt ai uống, dạng sai khiến)</div><div class='gd-sec'><b>Dạng て của nhóm 1</b> có một bộ quy tắc riêng, tùy vào chữ cuối:<br>う・つ・る → って：<span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br>む・ぶ・ぬ → んで：<span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><br>く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span>　ぐ → いで：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br>す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span></div><div class='gd-sec'><b>Nhóm 2: lấy <span class='gd-jp'>食べる</span> làm ví dụ</b>. Nhóm này đơn giản nhất, luôn bỏ る đi rồi thêm phần phía sau:<br><span class='gd-jp'>食べます</span>、<span class='gd-jp'>食べない</span>、<span class='gd-jp'>食べて</span>、<span class='gd-jp'>食べられる</span> (ăn được)、<span class='gd-jp'>食べられる</span> (bị ăn)、<span class='gd-jp'>食べさせる</span> (cho/bắt ai ăn)<br>Dạng khả năng và dạng bị động của nhóm 2 <b>giống hệt nhau</b>, bạn chỉ có thể dựa vào ngữ cảnh để biết đó là dạng nào.</div><div class='gd-sec'><b>Nhóm 3: chỉ có hai từ, học thuộc luôn</b><br><span class='gd-jp'>する</span>：<span class='gd-jp'>します</span>、<span class='gd-jp'>しない</span>、<span class='gd-jp'>して</span>、<span class='gd-jp'>できる</span> (làm được)、<span class='gd-jp'>される</span> (bị làm)、<span class='gd-jp'>させる</span> (cho/bắt ai làm)<br><span class='gd-jp'>来る</span>：<span class='gd-jp'>来ます</span>、<span class='gd-jp'>来ない</span>、<span class='gd-jp'>来て</span>、<span class='gd-jp'>来られる</span> (đến được; dạng bị động cũng có hình thức này)、<span class='gd-jp'>来させる</span> (cho/bắt ai đến)<br>Chữ Hán của 来る không đổi, nhưng cách đọc thì đổi theo:<br>Dạng từ điển và dạng ば đọc là く（くる、くれば）；<br>Dạng ます, dạng て, dạng た đọc là き（きます、きて、きた）；<br>Dạng ない, dạng khả năng, bị động, sai khiến đọc là こ（こない、こられる、こさせる）。</div><div class='gd-h'>Các dạng không biến nối tiếp nhau</div><div class='gd-sec'>Các dạng ở trên đều <b>biến trực tiếp từ dạng từ điển</b>. Bạn không cần đổi sang dạng ます mới ra được dạng て, cũng không cần qua dạng khả năng mới ra được dạng bị động.<br>Có một quy luật rất tiện: dạng khả năng, bị động, sai khiến đều kết thúc bằng “〜る”, nên <b>sau khi biến xong sẽ thành một động từ nhóm 2 mới</b>, và bạn có thể tiếp tục biến theo quy tắc nhóm 2:<br><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めます</span></span><span class='gd-pair'><span class='gd-jp'>飲める</span> → <span class='gd-jp'>飲めない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本語の新聞が読めます。</span>(Tôi đọc hiểu được báo tiếng Nhật)</div><div class='gd-ex-line'>・<span class='gd-jp'>漢字はまだあまり書けない。</span>(Chữ Hán tôi vẫn chưa viết giỏi lắm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Những ngoại lệ như <span class='gd-jp'>帰る</span> thuộc nhóm 1, nên phải nói <span class='gd-jp'>帰ります</span>、<span class='gd-jp'>帰らない</span>、<span class='gd-jp'>帰って</span>, không thể nói 帰ます、帰ない、帰て.<br>・Động từ kết thúc bằng う, khi chuyển sang dạng ない, bị động, sai khiến thì う phải đổi thành <b>わ</b>, không phải あ: <span class='gd-jp'>買わない</span>、<span class='gd-jp'>買われる</span>、<span class='gd-jp'>買わせる</span>.<br>・Dạng て của <span class='gd-jp'>行く</span> là <span class='gd-jp'>行って</span>, không theo quy tắc “く → いて”, nên không thể nói 行いて.<br>・Dạng khả năng của “danh từ＋する” là đổi する thành <span class='gd-jp'>できる</span>: <span class='gd-jp'>勉強できる</span> (có thể học). Còn <span class='gd-jp'>勉強される</span> là dạng bị động, nghĩa khác hẳn.<br>・Trong khẩu ngữ hằng ngày bạn hay nghe <span class='gd-jp'>食べれる</span>、<span class='gd-jp'>見れる</span> (bỏ ら). Khi nói chuyện thì rất phổ biến, nhưng trong bài thi và văn bản trang trọng phải dùng <span class='gd-jp'>食べられる</span>、<span class='gd-jp'>見られる</span>.</div><div class='gd-h'>Phân biệt với những dạng trông giống nhau</div><div class='gd-sec'>Cùng là <span class='gd-jp'>飲む</span>, nhưng dạng khả năng, bị động, sai khiến chỉ khác nhau một hai âm mà nghĩa hoàn toàn khác:<br><b>Được / có thể</b>: dạng khả năng</div><div class='gd-ex-line'>・<span class='gd-jp'>少しならお酒が飲める。</span>(Uống một chút rượu thì tôi vẫn được)</div><div class='gd-sec'><b>Bị</b>: dạng bị động</div><div class='gd-ex-line'>・<span class='gd-jp'>弟に私のジュースを飲まれた。</span>(Nước ép của tôi bị em trai uống mất rồi)</div><div class='gd-sec'><b>Cho / bắt</b>: dạng sai khiến</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもに薬を飲ませる。</span>(Cho con uống thuốc)</div><div class='gd-warn'>Mẹo phân biệt nhanh: với nhóm 1, nhìn phần đuôi: “え段音＋る” là được/có thể, “あ段音＋れる” là bị, “あ段音＋せる” là cho/bắt. Với nhóm 2, “られる” có thể là được/có thể hoặc bị, phải xem ngữ cảnh; còn “させる” thì là sai khiến.</div><div class='gd-h'>Học tiếp sau bài này</div><div class='gd-sec'>Khi đã quen với việc phân nhóm, bạn có thể đi sâu từng dạng một: dạng ý chí (<span class='gd-jp'>飲もう</span>), dạng khả năng, dạng ば (<span class='gd-jp'>飲めば</span>), dạng bị động, dạng sai khiến. Cuối cùng là dạng sai khiến-bị động, gộp sai khiến và bị động lại với nhau (<span class='gd-jp'>飲ませられる</span>／<span class='gd-jp'>飲まされる</span>, bị ép uống).</div>","n4-23":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てみる」nghĩa là <b>「thử ~」</b>: ăn thử, mặc thử, hỏi thử. Bạn chưa biết kết quả nên làm thử một lần xem sao. Cách dùng là thêm「みる」sau thể て của động từ, nói lịch sự thì dùng「みます」.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm thử</span>Lần đầu làm, chưa biết kết quả nên thử một chút.</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆を食べてみた。</span>(Mình đã ăn thử nattou)</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないから、駅員さんに聞いてみます。</span>(Mình không biết nên sẽ hỏi thử nhân viên nhà ga)</div><div class='gd-sec'><span class='gd-tag'>Mặc thử・dùng thử</span>Hay gặp nhất khi ở cửa hàng, phía sau thường thêm「〜てもいいですか」để hỏi xin phép.</div><div class='gd-ex-line'>・<span class='gd-jp'>この服、着てみてもいいですか。</span>(Cái áo này tôi mặc thử được không ạ?)</div><div class='gd-sec'><span class='gd-tag'>Mời người khác thử</span>「〜てみてください」＝xin bạn hãy thử ~.</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴、はいてみてください。</span>(Đôi giày này, mời bạn xỏ thử)</div><div class='gd-sec'><span class='gd-tag'>Muốn thử</span>「〜てみたい」＝muốn thử ~, dùng cho việc chưa từng làm và bạn thấy tò mò.</div><div class='gd-ex-line'>・<span class='gd-jp'>一度、富士山に登ってみたい。</span>(Mình muốn thử leo núi Phú Sĩ một lần)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Đầu tiên chuyển động từ sang thể て, rồi thêm「みる」.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span> → <span class='gd-jp'>行ってみる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてみる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してみる</span></span><br>Bản thân「みる」là <b>động từ nhóm 2 (động từ một đoạn)</b>, nên phần phía sau chia theo quy tắc nhóm 2: bỏ る rồi nối thêm đuôi.<br><span class='gd-pair'><span class='gd-jp'>やってみる</span> → <span class='gd-jp'>やってみます</span></span><span class='gd-pair'><span class='gd-jp'>やってみた</span></span><span class='gd-pair'><span class='gd-jp'>やってみたい</span></span><span class='gd-pair'><span class='gd-jp'>やってみて</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・「みる」ở đây thường được <b>viết bằng hiragana</b>, không viết thành 見る. Nó không còn nghĩa là “nhìn bằng mắt” nữa, nên <span class='gd-jp'>聞いてみる</span> là “hỏi thử”, chẳng liên quan gì đến mắt.<br>・Muốn nói “nhìn thử” thật thì dùng <span class='gd-jp'>見てみる</span>. 見る phía trước là “nhìn”, みる phía sau là “thử”, không phải viết trùng nhầm đâu nhé.<br>・Chỉ dùng cho việc <b>chính mình quyết định làm</b>. Những việc không kiểm soát được như mưa, bị bệnh thì không thêm てみる, bạn không thể nói「雨が降ってみる」.<br>・<span class='gd-jp'>試してみる</span> nghe như lặp ý “thử” hai lần, nhưng người Nhật nói thật và nghe rất tự nhiên.<br>・Ở cửa hàng, nói <span class='gd-jp'>ちょっと考えてみます</span> (để tôi suy nghĩ thử đã) thường là cách từ chối khéo kiểu “thôi, chưa mua đâu”. Nghe câu này thì đừng mong người ta sẽ quay lại mua nhé.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>てみた</b>＝trọng tâm là「<b>đã thử</b>」, thường kể về đúng một lần đó rồi nói cảm nghĩ tiếp theo:<br><span class='gd-jp'>納豆を食べてみた。けっこうおいしかった。</span>(Mình ăn thử nattou, hóa ra khá ngon)<br><b>たことがある</b>＝trọng tâm là「<b>có kinh nghiệm hay không</b>」:<br><span class='gd-jp'>納豆を食べたことがある。</span>(Mình đã từng ăn nattou)</div><div class='gd-sec'><b>たい</b>＝đơn thuần「muốn làm」: <span class='gd-jp'>沖縄に行きたい。</span>(Mình muốn đi Okinawa)<br><b>てみたい</b>＝chưa từng làm, tò mò, muốn「thử một lần」: <span class='gd-jp'>沖縄に行ってみたい。</span>(Mình muốn thử đến Okinawa xem sao)</div><div class='gd-warn'>Mẹo nhỏ để chọn: tiếng Việt nói được “thử ~” thì dùng てみる; nói “đã từng ~” thì dùng たことがある; chỉ là “muốn ~” thì dùng たい; còn có chút tò mò, muốn trải nghiệm một lần thì dùng てみたい.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là kiểu ghép「thể て + một động từ」, bạn có thể học tiếp <span class='gd-jp'>〜てしまう</span> (lỡ ~ mất / ~ xong rồi) và <span class='gd-jp'>〜ておく</span> (làm sẵn ~). Cách nối giống hệt nhau, chỉ khác nghĩa.</div>","n4-25":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ておきます」nghĩa là <b>「làm sẵn ~ trước」</b>. Mua vé trước khi đi du lịch, ướp lạnh bia trước khi bạn bè đến… những hành động “làm trước bây giờ để dùng cho lát nữa, cho sau này” như vậy, tiếng Nhật dùng「〜ておく」. Ngoài ra nó còn có thể diễn tả <b>「cứ để nguyên như vậy, đừng động vào」</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Chuẩn bị trước</span>Vì một việc nào đó sau này nên bây giờ làm sẵn. Đây là cách dùng phổ biến nhất.</div><div class='gd-ex-line'>・<span class='gd-jp'>出張の前に切符を買っておきます。</span>(Trước chuyến công tác, mình sẽ mua sẵn vé)</div><div class='gd-ex-line'>・<span class='gd-jp'>会議の前に資料を読んでおきます。</span>(Trước cuộc họp, mình sẽ đọc trước tài liệu)</div><div class='gd-ex-line'>・<span class='gd-jp'>ホテルはもう予約しておきました。</span>(Khách sạn mình đã đặt sẵn rồi)</div><div class='gd-sec'><span class='gd-tag'>Giữ nguyên hiện trạng</span>Cố ý để đồ vật giữ nguyên như bây giờ, không động vào.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けておいてください。</span>(Xin hãy để cửa sổ mở nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのままにしておいてください。</span>(Cứ để nguyên như vậy, đừng động vào nhé)</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Đầu tiên chuyển động từ sang thể て, rồi thêm「おく」(nói lịch sự là「おきます」).<br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span> → <span class='gd-jp'>買っておく</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでおく</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べておく</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しておく</span></span></div><div class='gd-sec'>Bản thân「おく」ở phía sau cũng được chia, giống cách chia của <span class='gd-jp'>置く</span>, động từ nhóm 1 (động từ năm đoạn):<br>Quá khứ: <span class='gd-jp'>買っておきました</span> (đã mua sẵn rồi)<br>Nhờ người khác: <span class='gd-jp'>買っておいてください</span> (nhờ bạn mua sẵn giúp mình)</div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>Rút gọn khi nói</span>Khi nói chuyện với bạn bè,「ておく」thường rút thành「とく」,「でおく」rút thành「どく」:<br><span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><br><span class='gd-pair'><span class='gd-jp'>置いておく</span> → <span class='gd-jp'>置いとく</span></span><br><span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span><br>Khi nhờ bạn bè,「ておいて」cũng rút thành「といて」:<br><span class='gd-pair'><span class='gd-jp'>言っておいて</span> → <span class='gd-jp'>言っといて</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ビール、冷やしとくね。</span>(Bia để mình ướp lạnh sẵn nha)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>置いておいてください</span> không phải gõ nhầm bị lặp đâu. <span class='gd-jp'>置いて</span> phía trước là hành động “đặt”, còn <span class='gd-jp'>おいて</span> phía sau là ておく nghĩa “để sẵn”, cả câu có nghĩa “xin hãy cứ để đó”.<br>・Thể て đứng sau「ん」là「で」, nên viết <span class='gd-jp'>読んでおく</span>, không phải 読んておく.<br>・Tiếng Việt nói “mua vé trước”, còn <span class='gd-jp'>切符を買います</span> chỉ là “mua vé”, không có cảm giác chuẩn bị sẵn. Phải thêm ておく mới đúng ý.<br>・<span class='gd-jp'>買っとく</span> (mua sẵn) sau khi rút gọn trông giống <span class='gd-jp'>買っちゃう</span> (lỡ mua mất rồi), nhưng nghĩa hoàn toàn khác, đừng nghe lẫn nhé.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>ておく kiểu “giữ nguyên hiện trạng” và「〜まま」đều có thể dịch là “để mở”, nhưng cảm giác khác nhau. Cùng là cửa sổ đang mở:<br><b>ておく</b>＝<b>cố ý</b> để mở, có mục đích: <span class='gd-jp'>暑いから、窓を開けておきました。</span>(Vì nóng nên mình cố ý để cửa sổ mở)<br><b>まま</b>＝trạng thái không thay đổi, cứ thế làm việc khác, hay dùng khi quên hoặc làm vậy là không nên: <span class='gd-jp'>窓を開けたまま出かけてしまった。</span>(Mình ra khỏi nhà mà quên đóng cửa sổ)</div><div class='gd-warn'>Mẹo nhỏ để chọn: có mục đích, chính bạn quyết định để như vậy thì dùng ておく; trạng thái không đổi, cứ thế tiếp tục (thường là do không để ý) thì dùng まま.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là kiểu ghép「thể て + một động từ」, còn có <span class='gd-jp'>〜てみる</span> (thử ~) và <span class='gd-jp'>〜てしまう</span> (làm xong rồi / lỡ mất rồi). Học chung với nhau, bạn sẽ nhanh quen với cách nối này.</div>","n4-29":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たばかりです」tương đương với <b>「vừa mới ~ thôi」</b> trong tiếng Việt. Điểm mấu chốt là người nói <b>cảm thấy</b> 「chuyện này chưa qua bao lâu」. Ví dụ khi bạn nói với đồng nghiệp 「Tôi mới vào công ty thôi」, có thể thực tế bạn đã vào được ba tháng rồi, nhưng trong lòng vẫn thấy còn mới, thì bạn vẫn có thể nói như vậy.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Thêm 「ばかりです」sau <b>thể た</b> của động từ.<br>Thể た chia giống hệt thể て: đổi 「て」thành 「た」, đổi 「で」thành 「だ」là xong.<br><span class='gd-pair'><span class='gd-jp'>入って</span> → <span class='gd-jp'>入った</span> → <span class='gd-jp'>入ったばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span> → <span class='gd-jp'>飲んだばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかりです</span></span><br><span class='gd-pair'><span class='gd-jp'>来て</span> → <span class='gd-jp'>来た</span>（きた）→ <span class='gd-jp'>来たばかりです</span></span><br>Khi nói với bạn bè thì bỏ 「です」đi, hoặc đổi thành 「だ」: <span class='gd-jp'>来たばかりだよ。</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Thật sự vừa xảy ra</span>Chuyện mới xảy ra cách đây vài phút hoặc vài giờ.</div><div class='gd-ex-line'>・<span class='gd-jp'>さっきご飯を食べたばかりです。</span>（Tôi vừa mới ăn cơm xong）</div><div class='gd-sec'><span class='gd-tag'>Cảm thấy vẫn còn mới</span>Thực tế đã qua mấy tháng, thậm chí một năm, nhưng bạn vẫn thấy chưa lâu lắm.</div><div class='gd-ex-line'>・<span class='gd-jp'>去年大学を卒業したばかりです。</span>（Tôi mới tốt nghiệp đại học năm ngoái thôi）</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>ばかりの＋名詞</span>「Thứ vừa mới ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>買ったばかりの傘をなくしました。</span>（Tôi làm mất cái ô vừa mới mua）</div><div class='gd-sec'><span class='gd-tag'>ばかりで</span>「Vì mới ~ nên…」, hay dùng để giải thích rằng mình còn chưa quen.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだよくわかりません。</span>（Tôi mới đến Nhật nên vẫn chưa hiểu rõ lắm）</div><div class='gd-sec'><span class='gd-tag'>ばかりなのに</span>「Rõ ràng mới vừa ~ mà…」, mang chút tiếc nuối, phàn nàn.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日洗ったばかりなのに、もう汚れた。</span>（Rõ ràng hôm qua mới giặt xong mà đã bẩn rồi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Khi theo sau là danh từ, phải thêm <b>の</b>: đúng là <span class='gd-jp'>買ったばかりの靴</span>, không phải 「買ったばかり靴」.<br>・Nhất định phải dùng <b>thể た</b>. <span class='gd-jp'>食べたばかり</span> nghĩa là 「vừa ăn xong」, còn <span class='gd-jp'>食べてばかり</span> nghĩa là 「cứ ăn suốt, chỉ toàn ăn」, nghĩa khác nhau rất nhiều.<br>・Chỉ dùng cho việc đã xảy ra. Việc 「sắp đi」hay 「lát nữa mới làm」thì không dùng được.<br>・Giữa bạn bè hay nói thành <b>ばっか</b>: <span class='gd-jp'>来たばっかだよ。</span>（Tớ mới đến thôi mà）Đừng nói kiểu này với người bề trên.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>たところです</b>（n4-28）cũng là 「vừa mới ~」, nhưng nó nói về <b>thời điểm khách quan ngay lúc vừa rồi</b>, thường là chuyện trong vòng vài phút. Còn <b>たばかりです</b> dựa vào <b>cảm giác trong lòng bạn</b>, thời gian dài hay ngắn đều được.<br>Với chuyện rất gần thì dùng cái nào cũng được:<br>・<span class='gd-jp'>今、家に着いたところです。</span>（Tôi vừa mới về đến nhà）<br>・<span class='gd-jp'>今、家に着いたばかりです。</span>（Tôi mới về đến nhà thôi）<br>Khi khoảng thời gian dài hơn thì chỉ dùng được ばかり:<br>・<span class='gd-jp'>先月、日本に来たばかりです。</span>（Tháng trước tôi mới đến Nhật）○<br>・「先月、日本に来たところです」×</div><div class='gd-warn'>Mẹo phân biệt nhanh: nếu phía trước có mốc thời gian khá xa như 「先月」「去年」thì dùng ばかり; còn 「vừa mới làm xong ngay lúc này」thì dùng ところ cũng được.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng dùng 「ばかり」nhưng mang nghĩa 「chỉ toàn ~, cứ ~ suốt」, xem n4-49: <span class='gd-jp'>弟はゲームばかりしている。</span>（Em trai tôi cứ chơi game suốt）</div>","n4-37":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「BよりAのほうが～」tương đương với <b>「So với B thì A ~ hơn」</b> trong tiếng Việt. Bạn đặt hai thứ cạnh nhau để so sánh, rồi chọn bên 「~ hơn」để nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>バスより電車のほうが速いです。</span>（So với xe buýt, tàu điện nhanh hơn）</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Danh từ＋より、danh từ＋<b>の</b>ほうが</div><div class='gd-ex-line'>・<span class='gd-jp'>夏より冬のほうが好きです。</span>（So với mùa hè, tôi thích mùa đông hơn）</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Thể từ điển＋より、thể từ điển＋ほうが（ở giữa <b>không thêm の</b>）</div><div class='gd-ex-line'>・<span class='gd-jp'>外で食べるより、家で作るほうが安いです。</span>（So với ăn ngoài, tự nấu ở nhà rẻ hơn）</div><div class='gd-sec'>Sau ほうが có thể dùng tính từ, hoặc những cách nói về cảm giác như <span class='gd-jp'>好きです</span>、<span class='gd-jp'>落ち着きます</span>.<br>Hai vế trước sau cũng có thể đảo chỗ mà nghĩa không đổi, trọng tâm vẫn nằm ở bên ほうが: <span class='gd-jp'>電車のほうがバスより速いです。</span></div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Trả lời câu hỏi 「cái nào」</span>Khi đối phương hỏi 「AとBと、どちらが～ですか」（A và B, cái nào ~ hơn?）, bạn trả lời bằng 「Aのほうが～です」. Lúc này hai thứ đã được nhắc đến rồi nên より thường được lược bỏ.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車とバスと、どちらが速いですか。</span>（Tàu điện và xe buýt, cái nào nhanh hơn?）</div><div class='gd-ex-line'>・<span class='gd-jp'>電車のほうが速いです。</span>（Tàu điện nhanh hơn）</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーと紅茶と、どちらがいいですか。</span>（Cà phê và trà đen, bạn chọn cái nào?）</div><div class='gd-ex-line'>・<span class='gd-jp'>紅茶のほうがいいです。</span>（Trà đen thì hơn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・より đi sau <b>「đối tượng làm mốc so sánh」</b>, tức là bên 「kém ～ hơn」; còn ほうが đi sau bên 「~ hơn」. Đừng nghĩ theo kiểu 「ai thắng ai thua」: <span class='gd-jp'>兄より弟のほうが下手です。</span>（So với anh trai, em trai kém hơn）Ở câu này, anh trai đứng trước より thực ra lại là người giỏi hơn.<br>・Tiếng Việt nói 「nhanh hơn xe buýt」, xe buýt đứng <b>sau</b> chữ 「hơn」; còn trong tiếng Nhật thì より phải đứng <b>sau</b> バス, viết thành <span class='gd-jp'>バスより</span>. Nhớ là より đi kèm ngay sau vật làm mốc, và vật đó đứng đầu vế.<br>・Động từ nối thẳng với ほうが, không thêm の: ×<span class='gd-jp'>歩くのほうが</span>　○<span class='gd-jp'>歩くほうが</span>. Chỉ danh từ mới cần の: <span class='gd-jp'>電車のほうが</span>.<br>・ほう viết bằng chữ Hán là <span class='gd-jp'>方</span>, nhưng ở đây đọc là ほう, nghĩa là 「phía bên đó」, khác với <span class='gd-jp'>方</span> (かた, cách thức) trong <span class='gd-jp'>読み方</span>.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>AはBより～</b>: chỉ đơn giản mô tả A.<br><span class='gd-jp'>電車はバスより速いです。</span>（Tàu điện nhanh hơn xe buýt）<br><b>BよりAのほうが～</b>: đặt hai thứ cạnh nhau và nhấn mạnh 「chính là bên A」.<br><span class='gd-jp'>バスより電車のほうが速いです。</span>（So với xe buýt, tàu điện nhanh hơn）<br>Hai câu này nghĩa gần như giống nhau, nhưng khi trả lời câu hỏi 「どちら？」thì phải dùng <b>ほうが</b>.</div><div class='gd-sec'><b>Động từ thể た＋ほうがいい</b>: đưa ra lời khuyên, 「nên ~」.<br><span class='gd-jp'>疲れているなら、休んだほうがいいですよ。</span>（Nếu mệt thì bạn nên nghỉ một chút nhé）<br><span class='gd-jp'>タクシーより歩いたほうがいいですよ。</span>（Thay vì đi taxi, bạn nên đi bộ thì hơn nhé）←có より nhưng dùng thể た, vẫn là đưa lời khuyên<br><b>AよりBのほうがいい</b>: so sánh, nói về sở thích.<br><span class='gd-jp'>コーヒーより紅茶のほうがいいです。</span>（So với cà phê, trà đen thì hơn）</div><div class='gd-warn'>Mẹo phân biệt nhanh: nhìn dạng của động từ. 「Động từ thể た＋ほうがいい」（<span class='gd-jp'>休んだほうがいい</span>）là đưa lời khuyên; 「thể từ điển＋ほうが＋tính từ」（<span class='gd-jp'>歩くほうが早い</span>）hoặc 「danh từ のほうが～」là so sánh. Lưu ý 「AよりBのほうがいいです」cũng là so sánh (B tốt hơn).</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói ngược lại 「B không ~ bằng A」thì dùng 「ほど…ない」: <span class='gd-jp'>バスは電車ほど速くないです。</span>（Xe buýt không nhanh bằng tàu điện）<br>Khi so sánh từ ba thứ trở lên, muốn nói 「nhất」thì dùng 「でいちばん」: <span class='gd-jp'>クラスで田中さんがいちばん背が高いです。</span>（Trong lớp, Tanaka cao nhất）</div>","n4-28":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「ところ」vốn có nghĩa là「地方」(nơi chốn), nhưng ở đây nó chỉ <b>một thời điểm nhất định</b>. Nó khớp hoàn toàn với <b>\"sắp ～\", \"đang ～\", \"vừa mới ～\"</b> trong tiếng Việt: chỉ cần đổi dạng của động từ phía trước là bạn nói được việc đó đang ở giai đoạn nào.</div><div class='gd-h'>Cùng một tình huống, ba cách trả lời</div><div class='gd-sec'>Bạn bè gọi điện hỏi bạn「<span class='gd-jp'>今、大丈夫？</span>」(Bây giờ có tiện không?), bạn có thể trả lời thế này:</div><div class='gd-ex-line'>・<span class='gd-jp'>ごめん、今から出かけるところ。</span>(Xin lỗi, mình sắp ra ngoài)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べているところ。</span>(Giờ mình đang ăn cơm)</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょうど今、家に着いたところ。</span>(Mình vừa mới về đến nhà)</div><div class='gd-sec'>Đây chính là lúc「ところ」xuất hiện nhiều nhất: <b>giải thích cho đối phương biết tình trạng hiện tại của bạn</b>. Nói với bạn bè thì chỉ cần dừng ở「ところ」, muốn lịch sự hơn thì thêm「です」.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Sắp làm</span>Thể từ điển (dạng gốc tra được trong từ điển) ＋ ところ. Việc này <b>chưa bắt đầu</b>, nhưng sắp bắt đầu ngay.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところです</span></span>(sắp ăn)</div><div class='gd-ex-line'>・<span class='gd-jp'>これから晩ご飯を作るところです。</span>(Mình sắp bắt đầu nấu bữa tối)</div><div class='gd-sec'><span class='gd-tag'>Đang làm</span>ている＋ところ. Việc này <b>đang làm dở</b>, chưa kết thúc.<br><span class='gd-pair'><span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べているところです</span></span>(đang ăn)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、宿題をしているところです。</span>(Giờ mình đang làm bài tập)</div><div class='gd-sec'><span class='gd-tag'>Vừa làm xong</span>Thể た (dạng quá khứ) ＋ ところ. Việc này <b>vừa mới kết thúc</b>.<br><span class='gd-pair'><span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたところです</span></span>(vừa ăn xong)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、起きたところです。</span>(Mình vừa mới thức dậy)</div><div class='gd-sec'>Những từ hay đi cùng: <span class='gd-jp'>これから</span>、<span class='gd-jp'>今から</span> (đi với \"sắp\"), <span class='gd-jp'>今</span> (đi với \"đang\"), <span class='gd-jp'>ちょうど</span>、<span class='gd-jp'>今</span> (đi với \"vừa làm xong\").</div><div class='gd-h'>Nói về quá khứ cũng được</div><div class='gd-sec'>Đổi「です」thành「でした」là bạn có thể nói về việc <b>vào một thời điểm trong quá khứ</b>, bạn đang ở giai đoạn nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>電話が来たとき、お風呂に入っているところでした。</span>(Lúc có điện thoại gọi đến, mình đang tắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が来たとき、ちょうど出かけるところでした。</span>(Lúc bạn đến, mình vừa hay sắp ra ngoài)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Ba dạng này chỉ ba thời điểm khác nhau, ghép sai là nghĩa đổi hẳn: <b>thể từ điển＝chưa bắt đầu, ている＝đang diễn ra, thể た＝vừa kết thúc</b>.「<span class='gd-jp'>食べるところです</span>」là \"sắp ăn\", không phải \"đang ăn\".<br>・Trước ところ phải dùng thể thường, không ghép với ます: đúng là <span class='gd-jp'>行くところです</span>, không phải 行きますところです.<br>・「ているところ」nói về hành động đang diễn ra tại <b>một thời điểm cụ thể</b> (bây giờ, hoặc một lúc nào đó trong quá khứ). Thói quen hằng ngày chỉ dùng ている thông thường: <span class='gd-jp'>毎日日本語を勉強しています。</span>(Ngày nào mình cũng học tiếng Nhật), không nói là「毎日勉強しているところです」.<br>・Những trạng thái kéo dài liên tục như「住んでいる」「結婚している」cũng không thêm ところ được.<br>・「たところ」là <b>thật sự vừa mới xảy ra</b>, thường chỉ trong vài phút, nhiều lắm là vài giờ. Đến Nhật đã ba tháng thì đừng nói「来たところです」.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'><b>たところ</b> và <b>たばかり</b> (n4-29) đều dịch là \"vừa mới ～\".<br>Ngay lúc vừa bước vào ga thì dùng cái nào cũng được: <span class='gd-jp'>今、駅に着いたところです。</span>／<span class='gd-jp'>今、駅に着いたばかりです。</span>(Mình vừa đến ga)<br>Nhưng nếu đã qua một thời gian mà <b>bạn tự cảm thấy vẫn còn mới</b>, thì chỉ dùng được たばかり: <span class='gd-jp'>日本に来たばかりです。</span>(Mình mới đến Nhật chưa lâu, ví dụ mới được ba tháng)<br>Ngoài ra, たばかり đặt thẳng trước danh từ được: <span class='gd-jp'>買ったばかりの靴</span> (đôi giày vừa mới mua), còn たところ thì không dùng kiểu này được.</div><div class='gd-warn'>Mẹo nhỏ để chọn: nếu đúng là vừa xảy ra, thời điểm rất chính xác thì dùng たところ; nếu đã qua một lúc nhưng cảm giác vẫn còn mới thì dùng たばかり.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「<span class='gd-jp'>もう少しで</span>」trước「thể từ điển＋ところでした」sẽ thành \"suýt nữa thì ～\": <span class='gd-jp'>もう少しで電車に遅れるところでした。</span>(Suýt nữa thì trễ tàu)</div>","n4-31":"<div class='gd-h'>Hiểu ngay trong một câu</div><div class='gd-sec'>「〜そう」tương đương với <b>\"trông có vẻ ～\", \"có vẻ sắp ～\"</b> trong tiếng Việt. Mắt bạn thấy một dáng vẻ nào đó, và cảm giác bật ra ngay thì dùng nó. Ví dụ nhìn cái bánh rồi nói \"trông ngon quá\", nhìn bầu trời tối sầm rồi nói \"có vẻ sắp mưa\".</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Động từ: sắp xảy ra</span>Thấy dấu hiệu và cảm thấy việc đó sắp xảy ra ngay.</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗いですね。雨が降りそうです。</span>(Trời tối quá nhỉ, có vẻ sắp mưa)</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ボタンが取れそう。</span>(A, cái cúc sắp rớt rồi)</div><div class='gd-sec'><span class='gd-tag'>Tính từ: trông có vẻ ～</span>Dáng vẻ cảm nhận được từ bề ngoài.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう！</span>(Cái bánh này trông ngon quá!)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは今日も元気そうですね。</span>(Hôm nay anh Tanaka trông cũng khỏe khoắn nhỉ)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><b>Động từ</b>: đổi sang thể ます, bỏ ます, rồi thêm そう.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそう</span></span><br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣きそう</span></span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できそう</span></span></div><div class='gd-sec'><b>Tính từ đuôi い</b>: bỏ「い」ở cuối, rồi thêm そう.<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱そう</span></span></div><div class='gd-sec'><b>Tính từ đuôi な</b>: thêm そう trực tiếp, không cần thêm だ.<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>Hai trường hợp ngoại lệ, cứ học thuộc</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span><br>Muốn nói \"trông không ～\", với tính từ thì ghép từ dạng phủ định: <span class='gd-pair'><span class='gd-jp'>おいしくない</span> → <span class='gd-jp'>おいしくなさそう</span></span><br>Với động từ, muốn nói \"trông có vẻ sẽ không ～\" thì dùng <span class='gd-jp'>降りそうにない</span> hoặc <span class='gd-jp'>降りそうもない</span> (trông có vẻ sẽ không mưa).</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-sec'>そう được dùng giống như tính từ đuôi な: đứng trước danh từ thì thành <b>そうな</b>, đứng trước động từ thì thành <b>そうに</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>おいしそうなパンですね。</span>(Ổ bánh mì trông ngon quá nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>(Bọn trẻ chơi trông vui lắm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Dạng \"trông có vẻ\" của <span class='gd-jp'>いい</span> là <b>よさそう</b>, không nói được いさそう; còn <span class='gd-jp'>いいそう</span> sẽ thành nghĩa \"nghe nói là tốt\".<br>・<span class='gd-jp'>かわいそう</span> nghĩa là \"tội nghiệp quá\", không phải \"trông có vẻ dễ thương\".<br>・Điều gì nhìn là biết ngay thì không dùng そう. Hoa đẹp thì cứ nói thẳng <span class='gd-jp'>きれいですね</span>, không nói きれいそう kiểu \"trông có vẻ đẹp\".<br>・Danh từ không thể thêm そう này trực tiếp; \"trông giống học sinh\" không nói được là 学生そう.<br>・Động từ＋そう thường mang nghĩa \"<b>sắp</b> ～ rồi\", không chỉ là \"có vẻ\": <span class='gd-jp'>泣きそう</span> là \"sắp khóc rồi\".</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>「〜そうです (truyền văn)」ở bài sau mang nghĩa <b>\"nghe nói ～\"</b>, trông gần như giống hệt, chỉ khác ở dạng đứng trước. Hãy so sánh với cùng một từ:<br><b>Động từ</b>: <span class='gd-jp'>雨が降りそうです。</span>(Trông có vẻ sắp mưa)<br>　　　<span class='gd-jp'>雨が降るそうです。</span>(Nghe nói sẽ mưa)<br><b>Tính từ đuôi い</b>: <span class='gd-jp'>おいしそうです。</span>(Trông có vẻ ngon)<br>　　　　<span class='gd-jp'>おいしいそうです。</span>(Nghe nói ngon)<br><b>Tính từ đuôi な</b>: <span class='gd-jp'>元気そうです。</span>(Trông có vẻ khỏe khoắn)<br>　　　　<span class='gd-jp'>元気だそうです。</span>(Nghe nói khỏe khoắn)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu trước そう là thể từ điển hoặc thể thường (<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>元気だ</span>) ＝ nghe nói; còn động từ bỏ ます, tính từ đuôi い bỏ い, tính từ đuôi な ghép trực tiếp và không có だ (<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>、<span class='gd-jp'>元気</span>) ＝ trông có vẻ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy học tiếp「〜そうです (truyền văn)」và luyện hai mẫu này cùng nhau. Sau đó là「〜ようです・〜みたいです」, mẫu \"có vẻ ～\" được suy đoán dựa trên manh mối.</div>"});
